nz <- function(x) !is.null(x) && length(x) > 0 && all(nzchar(as.character(x)))

fmt <- function(x, d = 3) {
  ifelse(is.na(x), "-", formatC(as.numeric(x), digits = d, format = "f"))
}

## An effect's SE(m), SE(d) or C.D. for display (`what` is "sem", "sed" or "cd"):
## the single value when one applies to every mean and pair, otherwise its
## range, so a figure that fits only some of the means is never printed as if
## it fitted them all.
err_text <- function(e, what, digits = 2, html = TRUE) {
  v <- e[[what]]
  ## a small-valued response at two decimals would print SE(d) 0.00 and
  ## C.D. 0.00; decimals are added until the figure shows
  if (length(v) == 1L && !is.na(v)) {
    dg <- digits
    while (dg < digits + 4 && v != 0 && as.numeric(fmt(v, dg)) == 0) dg <- dg + 1
    return(fmt(v, dg))
  }
  rg <- e[[c(sem = "se_range", sed = "sed_range", cd = "cd_range")[[what]]]]
  if (length(rg) != 2L || anyNA(rg)) return("-")
  ## a range whose ends round to the same figure reads as nonsense, so show
  ## enough decimals to tell them apart
  dg <- digits
  while (dg < digits + 3 && (fmt(rg[1], dg) == fmt(rg[2], dg) || as.numeric(fmt(rg[1], dg)) == 0)) dg <- dg + 1
  paste0(fmt(rg[1], dg), if (html) "&ndash;" else " to ", fmt(rg[2], dg))
}

## a p-value for reading: never in scientific notation, never "= <0.0001".
## Given alpha, a p below one of the thresholds the marks use (alpha,
## alpha / 5) gains figures until it no longer prints at or above it:
## 0.049973 prints as 0.04997, not 0.05, beside its star.
p_text <- function(p, alpha = NULL) {
  s <- ifelse(is.na(p), "-", ifelse(p < 1e-4, "< 0.0001",
              trimws(formatC(signif(p, 3), format = "fg", digits = 3))))
  for (cut in alpha / c(5, 1)) {
    for (i in which(!is.na(p) & p >= 1e-4 & p < cut)) {
      d <- 3
      while (as.numeric(s[i]) >= cut && d < 12) {
        d <- d + 1
        s[i] <- trimws(formatC(signif(p[i], d), format = "fg", digits = d))
      }
    }
  }
  s
}
p_show <- function(p, alpha) p_text(p, alpha)
pval <- function(p, alpha = NULL) gsub("<", "&lt;", p_text(p, alpha), fixed = TRUE)

## "p = 0.0373" or "p &lt; 0.0001", for running text
p_eq <- function(p, alpha = NULL) ifelse(!is.na(p) & p < 1e-4, "p &lt; 0.0001", paste("p =", p_text(p, alpha)))

## Significance marks at the level the user chose: one star at alpha, two at
## alpha / 5. At alpha = 0.05 that is the familiar 5% and 1% pair; at any other
## level the marks follow the choice instead of staying at 5% and 1%.
star <- function(p, alpha) {
  ifelse(is.na(p), "", ifelse(p < alpha / 5, "**", ifelse(p < alpha, "*", "NS")))
}

## a probability as it is written in labels: 0.05, 0.01, 0.002
p_lab <- function(a) format(a, digits = 6, drop0trailing = TRUE, trim = TRUE, scientific = FALSE)

## a probability as a percentage, for "the 5% level"
pct <- function(a) format(100 * a, digits = 6, drop0trailing = TRUE, trim = TRUE, scientific = FALSE)

## the key printed under an ANOVA table, so the stars mean what they say
star_key <- function(alpha)
  sprintf("** significant at p &lt; %s; * significant at p &lt; %s; NS not significant at the %s%% level.",
          p_lab(alpha / 5), p_lab(alpha), pct(alpha))

## Letters from critical differences. `cd` is one number that applies to every
## pair, or a square matrix holding one critical difference per pair (unequal
## replication). Any missing value means no letters can be given.
cld_lsd <- function(mu, cd) {
  n <- length(mu)
  if (n < 2) return(rep("a", n))
  if (!length(cd) || anyNA(cd) || any(!is.finite(cd))) return(rep("", n))
  crit <- if (is.matrix(cd)) cd else matrix(cd, n, n)
  sig <- abs(outer(mu, mu, "-")) > crit
  diag(sig) <- FALSE
  off <- crit[row(crit) != col(crit)]
  if (diff(range(off)) <= 1e-12 * max(abs(off))) cld_sweep(mu, sig) else cld_from_sig(mu, sig)
}

## Letters when one critical difference applies to every pair: a single sweep
## down the sorted means. Exact in that case and instant for hundreds of means,
## where the general algorithm below is slow; both give identical letters.
cld_sweep <- function(mu, sig) {
  n <- length(mu)
  ord <- order(mu, decreasing = TRUE)
  groups <- list(); done <- integer(0)
  for (i in ord) {
    joined <- FALSE
    for (k in seq_along(groups)) {
      if (all(!sig[i, groups[[k]]])) {
        groups[[k]] <- c(groups[[k]], i); joined <- TRUE
      }
    }
    if (!joined) groups[[length(groups) + 1L]] <- c(done[!sig[i, done]], i)
    done <- c(done, i)
  }
  keep <- rep(TRUE, length(groups))
  for (i in seq_along(groups)) for (j in seq_along(groups)) {
    if (i != j && keep[i] && keep[j] && all(groups[[i]] %in% groups[[j]]) &&
        length(groups[[i]]) < length(groups[[j]])) keep[i] <- FALSE
  }
  groups <- groups[keep]
  groups <- groups[!duplicated(vapply(groups, function(g)
    paste(sort(g), collapse = "-"), character(1)))]
  lets <- letter_seq(length(groups))
  out <- character(n)
  for (k in seq_along(groups)) out[groups[[k]]] <- paste0(out[groups[[k]]], lets[k])
  out
}

## Compact letter display from a symmetric logical matrix `sig` (TRUE where two
## means differ significantly), by the insert and absorb steps of Piepho's
## (2004, Journal of Computational and Graphical Statistics 13, 456-466)
## algorithm. Two means share a letter exactly when they do not differ
## significantly, whatever produced `sig`. The sweep above only guarantees that
## when one critical difference applies to every pair, which unequal
## replication and the step-down range tests both break.
cld_from_sig <- function(mu, sig) {
  n <- length(mu)
  if (n < 2) return(rep("a", n))
  G <- matrix(TRUE, n, 1L)                      # one column per letter
  pairs <- which(upper.tri(sig) & sig, arr.ind = TRUE)
  for (r in seq_len(nrow(pairs))) {
    i <- pairs[r, 1]; j <- pairs[r, 2]
    both <- which(G[i, ] & G[j, ])
    if (!length(both)) next
    ## insert: split every letter holding both members of a significant pair
    ## into one copy without i and one without j
    add <- G[, both, drop = FALSE]
    add[j, ] <- FALSE
    G[i, both] <- FALSE
    G <- absorb_letters(cbind(G, add))
  }
  ## letter "a" goes to the group holding the highest mean, and so on down
  rk <- integer(n); rk[order(mu, decreasing = TRUE)] <- seq_len(n)
  key <- apply(G, 2, function(g) paste(sprintf("%06d", sort(rk[g])), collapse = "-"))
  G <- G[, order(key), drop = FALSE]
  lets <- letter_seq(ncol(G))
  vapply(seq_len(n), function(i) paste(lets[G[i, ]], collapse = ""), character(1))
}

## absorb: drop any letter whose members all carry another letter too, and any
## repeat of an identical letter. sub[a, b] is TRUE when letter a lies inside
## letter b; done as one matrix product because this runs after every insert.
absorb_letters <- function(G) {
  if (ncol(G) < 2L) return(G)
  sub <- crossprod(G, !G) == 0
  diag(sub) <- FALSE
  same <- sub & t(sub)
  drop <- rowSums(sub & !t(sub)) > 0 | rowSums(same & row(same) > col(same)) > 0
  G[, !drop, drop = FALSE]
}

## a, b, ..., z, then aa, bb, ..., then aaa, ...
letter_seq <- function(k)
  unlist(lapply(seq_len(ceiling(k / 26)), function(r) strrep(letters, r)))[seq_len(k)]

## read data pasted straight out of Excel
read_pasted <- function(txt, sep = "\t", header = TRUE) {
  txt <- gsub("\r\n", "\n", txt, fixed = TRUE)
  if (!nzchar(trimws(txt))) return(NULL)
  s <- switch(sep, "tab" = "\t", "comma" = ",", "semicolon" = ";",
              "space" = "", sep)
  ## only empty cells and NA count as missing here: markers such as "-" or
  ## "n/a" are left as typed so the data check can show them and say what it
  ## will do with them, rather than R changing them silently
  ## Everything is read as text first and converted only where no information
  ## is lost (convert_lossless), so codes such as 1.1 and 1.10 stay distinct.
  rd <- function(q) utils::read.table(text = txt, header = header, sep = s,
                         stringsAsFactors = FALSE, check.names = FALSE,
                         na.strings = c("NA", ""), fill = TRUE, colClasses = "character",
                         strip.white = TRUE, quote = q, comment.char = "")
  ## quotes are honoured only when they are real quoting, not inch marks
  ## (12" pot), which would swallow lines (see quote_char)
  q <- quote_char(strsplit(txt, "\n", fixed = TRUE)[[1]])
  ## A line with more values than the header (or than most lines) would push
  ## its values one column to the right: comma-separated text with decimal
  ## commas (5,6) splits each such number in two. Such text is refused, as an
  ## uploaded file is; a line with fewer values is only short of its last cells.
  n <- tryCatch(utils::count.fields(textConnection(txt), sep = s, quote = q, comment.char = "",
                                    blank.lines.skip = TRUE), error = function(e) integer(0))
  n <- n[!is.na(n)]
  body <- if (header) n[-1] else n
  base <- if (header && length(n)) n[1] else as.integer(names(which.max(table(body))))
  rownamed <- header && length(body) > 0 && all(body == base + 1)
  if (length(body) && !rownamed && any(body > base))
    stop(paste0("Some lines have more values than ", if (header) "the header has names" else "most lines",
      ". This usually means numbers written with decimal commas in comma-separated text, which splits ",
      "each of them in two. Choose 'Semicolon' or 'Tab' as the column separator, or copy the cells ",
      "straight from Excel, which separates them with tabs."), call. = FALSE)
  d <- rd(q)
  ## a header one name short on every line (row names, as R writes them) makes
  ## read.table use the first column as row names; keep it as a column, even
  ## when it holds 1, 2, 3, so row numbers in messages stay the visible ones
  if (rownamed) {
    d <- cbind(Label = rownames(d), d, stringsAsFactors = FALSE)
    rownames(d) <- NULL
  }
  d[] <- lapply(d, convert_lossless)
  names(d) <- make.names(names(d), unique = TRUE)
  d
}

## data.frame -> plain HTML table (used by the integrated-means view & report)
df_html <- function(df, caption = NULL, foot = NULL, digits = 3) {
  num <- vapply(df, is.numeric, logical(1))
  int <- names(df) %in% c("n", "N", "Df") | vapply(df, is.integer, logical(1))
  df[num & !int] <- lapply(df[num & !int], function(z) fmt(z, digits))
  df[num & int]  <- lapply(df[num & int],
    function(z) ifelse(is.na(z), "-", as.character(as.integer(round(z)))))
  df[] <- lapply(df, function(z) gsub("<", "&lt;", as.character(z), fixed = TRUE))
  hdr <- paste0("<th>", names(df), "</th>", collapse = "")
  body <- paste0(apply(df, 1, function(r)
    paste0("<tr><td>", paste(r, collapse = "</td><td>"), "</td></tr>")),
    collapse = "")
  paste0(
    "<table class='doe'>",
    if (!is.null(caption)) paste0("<caption>", caption, "</caption>") else "",
    "<thead><tr>", hdr, "</tr></thead><tbody>", body, "</tbody>",
    if (!is.null(foot)) paste0("<tfoot>", foot, "</tfoot>") else "",
    "</table>")
}

anova_display <- function(an, alpha) {
  data.frame(Source = an$Source, Df = an$Df,
             `Sum of squares` = an$SS, `Mean square` = an$MS,
             `F value` = an$F,
             `p value` = p_text(an$p, alpha),
             Signif = star(an$p, alpha), check.names = FALSE)
}

## ------------------------------------------------------------- demo datasets
## Deterministic stand-in for stats::demo_noise(), used only to build the example
## datasets returned by demo_data(). A stored vector of standardised deviates is
## recycled instead of drawing random numbers, so the examples are identical on
## every machine and the user's random number stream is left untouched. The
## vector has prime length, so recycling cannot line up with the block, plot or
## treatment structure of any of the example designs.
demo_noise <- function(n, mean = 0, sd = 1) {
  z <- c(
    1.148, 0.655, 0.101, 0.001, 1.317, 1.446, 0.718,
    0.083, -0.971, -0.872, -1.400, 0.655, 1.004, 0.486,
    -2.939, 0.063, -0.688, 0.641, -1.337, -1.727, 1.300,
    0.508, 1.206, 0.001, 0.586, -1.277, 0.092, 0.863,
    -1.769, 0.100, -1.178, -0.107, -0.280, 1.361, -0.274,
    0.579, 0.529, -0.265, -0.343, 0.616, -0.633)
  mean + sd * rep_len(z, n)
}

#' Example datasets for each design
#'
#' Generates a small, balanced example dataset for a design, so you can try
#' DOEpro without your own data. These are the datasets behind the
#' \strong{Load example} button in the application.
#'
#' @param which The example to build: \code{"CRD"}, \code{"RCBD"}, \code{"LSD"},
#'   \code{"FCRD"} (a factorial in a CRD, with two responses), \code{"FRCBD"}
#'   (factorial in blocks), \code{"SPLIT"}, \code{"STRIP"},
#'   \code{"POOLRCBD"} or \code{"POOLCRD"} (a single treatment factor over
#'   environments), \code{"POOLFACT"} or \code{"POOLFACTC"} (factorial
#'   treatments over environments, RCBD and CRD base respectively).
#'
#' @return A data frame in long format, ready to pass to \code{\link{analyze}}.
#'   The values are synthetic: built from fixed effects and a stored set of
#'   deviates for demonstration, not observed in any experiment.
#'
#' @examples
#' head(demo_data("RCBD"))
#' str(demo_data("SPLIT"))
#'
#' @export
demo_data <- function(which) {
  switch(which,
    "CRD" = {
      d <- expand.grid(Rep = 1:4, Treatment = paste0("T", 1:5))
      d$Yield <- round(demo_noise(nrow(d), rep(c(28, 31, 35, 30, 40), each = 4), 2.2), 2)
      d[, c("Treatment", "Rep", "Yield")]
    },
    "RCBD" = {
      d <- expand.grid(Block = paste0("B", 1:4), Variety = paste0("V", 1:6))
      d$Yield <- round(demo_noise(nrow(d), rep(c(42, 47, 39, 55, 50, 44), each = 4) +
                               rep(c(-1.5, 0, 1, 0.5), 6), 2.0), 2)
      d[, c("Block", "Variety", "Yield")]
    },
    "LSD" = {
      d <- expand.grid(Row = paste0("R", 1:4), Column = paste0("C", 1:4))
      d$Treatment <- c("A","B","C","D","B","C","D","A",
                       "C","D","A","B","D","A","B","C")
      d$Yield <- round(demo_noise(16, c(20, 24, 27, 22)[
        match(d$Treatment, c("A","B","C","D"))], 1.4), 2)
      d[, c("Row", "Column", "Treatment", "Yield")]
    },
    "FCRD" = {                                   # 3 x 3 factorial in pots, completely randomised
      d <- expand.grid(Rep = 1:4,
                       Variety  = c("V1", "V2", "V3"),
                       Nitrogen = c("N0", "N40", "N80"))
      vi <- as.integer(d$Variety); ni <- as.integer(d$Nitrogen)
      ## yield (g per pot): both factors matter, and V3 gains most from N80
      mu_y <- 18 + c(0, 3, 5)[vi] + c(0, 4, 6)[ni] +
              ifelse(vi == 3 & ni == 3, 3, 0) + ifelse(vi == 1 & ni == 3, -1.5, 0)
      ## plant height (cm): nitrogen raises it in every variety alike
      mu_h <- 62 + c(0, 5, -3)[vi] + c(0, 6, 10)[ni]
      d$Yield <- round(demo_noise(nrow(d), mu_y, 1.2), 2)
      d$Plant_height <- round(mu_h + demo_noise(nrow(d) + 13, 0, 2.4)[-(1:13)], 1)
      d[, c("Variety", "Nitrogen", "Rep", "Yield", "Plant_height")]
    },
    "FRCBD" = {
      d <- expand.grid(Block = paste0("B", 1:3),
                       Nitrogen = c("N0", "N60", "N120"),
                       Variety  = c("V1", "V2"))
      mu <- 30 + c(0, 6, 9)[as.integer(d$Nitrogen)] +
            c(0, 4)[as.integer(d$Variety)] +
            ifelse(d$Variety == "V2" & d$Nitrogen == "N120", 5, 0)
      d$Yield <- round(demo_noise(nrow(d), mu, 1.8), 2)
      d[, c("Block", "Nitrogen", "Variety", "Yield")]
    },
    "SPLIT" = {
      d <- expand.grid(Rep = paste0("R", 1:4),
                       Irrigation = c("I1", "I2", "I3"),
                       Variety    = c("V1", "V2", "V3", "V4"))
      mu <- 40 + c(0, 5, 8)[as.integer(d$Irrigation)] +
            c(0, 3, 6, 2)[as.integer(d$Variety)] +
            ifelse(d$Irrigation == "I3" & d$Variety == "V3", 4, 0)
      wp <- demo_noise(12, 0, 2.0)[as.integer(interaction(d$Rep, d$Irrigation))]
      d$Yield <- round(mu + wp + demo_noise(nrow(d), 0, 1.3), 2)
      d[, c("Rep", "Irrigation", "Variety", "Yield")]
    },
    "STRIP" = {
      d <- expand.grid(Rep = paste0("R", 1:4),
                       Tillage = c("Conventional", "Minimum", "Zero"),
                       Mulch   = c("M0", "M1", "M2", "M3"))
      mu <- 25 + c(0, 2, -3)[as.integer(d$Tillage)] +
            c(0, 3, 5, 6)[as.integer(d$Mulch)] +
            ifelse(d$Tillage == "Zero" & d$Mulch %in% c("M2", "M3"), 2.5, 0)
      ea <- demo_noise(12, 0, 1.0)[as.integer(interaction(d$Rep, d$Tillage))]
      eb <- demo_noise(16, 0, 0.8)[as.integer(interaction(d$Rep, d$Mulch))]
      d$Yield <- round(mu + ea + eb + demo_noise(nrow(d), 0, 0.9), 2)
      d[, c("Rep", "Tillage", "Mulch", "Yield")]
    },
    "POOLRCBD" = {
      d <- expand.grid(Rep = paste0("R", 1:3),
                       Variety = c("V1", "V2", "V3", "V4"),
                       Location = c("Shalimar", "Wadura", "Zampathan"))
      loc  <- c(0, 4, -3)[as.integer(d$Location)]        # site effect
      var  <- c(0, 3, 6, 4)[as.integer(d$Variety)]       # variety effect
      vxl  <- ifelse(d$Location == "Zampathan" & d$Variety %in% c("V3", "V4"), 3.5, 0) +
              ifelse(d$Location == "Wadura" & d$Variety == "V2", 2.0, 0)  # V x L
      repe <- demo_noise(9, 0, 1.1)[as.integer(interaction(d$Rep, d$Location))]
      d$Yield <- round(28 + loc + var + vxl + repe + demo_noise(nrow(d), 0, 1.0), 2)
      d[, c("Location", "Rep", "Variety", "Yield")]
    },
    "POOLCRD" = {
      d <- expand.grid(Rep = 1:4,
                       Treatment = c("T1", "T2", "T3", "T4"),
                       Season = c("Kharif", "Rabi", "Zaid"))
      sea <- c(0, 5, -4)[as.integer(d$Season)]
      trt <- c(0, 4, 7, 5)[as.integer(d$Treatment)]
      txs <- ifelse(d$Season == "Zaid" & d$Treatment %in% c("T3", "T4"), 3.0, 0)
      d$Yield <- round(22 + sea + trt + txs + demo_noise(nrow(d), 0, 1.3), 2)
      d[, c("Season", "Treatment", "Yield")]
    },
    "POOLFACT" = {                                   # 2-factor factorial over locations (RCBD)
      d <- expand.grid(Rep = paste0("R", 1:3),
                       Nitrogen = c("N0", "N1"),
                       Variety  = c("V1", "V2", "V3"),
                       Location = c("Shalimar", "Wadura", "Zampathan"))
      loc <- c(0, 4, -3)[as.integer(d$Location)]
      nit <- c(0, 5)[as.integer(d$Nitrogen)]
      var <- c(0, 3, 6)[as.integer(d$Variety)]
      nxv <- ifelse(d$Nitrogen == "N1" & d$Variety == "V3", 2.5, 0)           # N x V
      nxl <- ifelse(d$Nitrogen == "N1" & d$Location == "Zampathan", -2.0, 0)  # N x Location
      rep_e <- demo_noise(9, 0, 1.0)[as.integer(interaction(d$Rep, d$Location))]
      d$Yield <- round(26 + loc + nit + var + nxv + nxl + rep_e +
                       demo_noise(nrow(d), 0, 1.0), 2)
      d[, c("Location", "Rep", "Nitrogen", "Variety", "Yield")]
    },
    "POOLFACTC" = {                                  # 2-factor factorial over seasons (CRD)
      d <- expand.grid(Rep = 1:4,
                       Spacing = c("S1", "S2"),
                       Variety = c("V1", "V2", "V3"),
                       Season  = c("Kharif", "Rabi", "Zaid"))
      sea <- c(0, 5, -4)[as.integer(d$Season)]
      sp  <- c(0, 3)[as.integer(d$Spacing)]
      var <- c(0, 4, 7)[as.integer(d$Variety)]
      sxv <- ifelse(d$Spacing == "S2" & d$Variety == "V3", 3.0, 0)
      d$Yield <- round(24 + sea + sp + var + sxv + demo_noise(nrow(d), 0, 1.3), 2)
      d[, c("Season", "Spacing", "Variety", "Yield")]
    }
  )
}

## ------------------------------------------------------------ ANOVA helpers
tidy_aov <- function(fit) {
  a <- summary(fit)[[1]]
  ## with no error degrees of freedom summary() has no F column; say so later
  ## in words rather than fail here
  data.frame(Source = trimws(rownames(a)), Df = a[["Df"]], SS = a[["Sum Sq"]],
             MS = a[["Mean Sq"]],
             F = if (is.null(a[["F value"]])) NA_real_ else a[["F value"]],
             p = if (is.null(a[["Pr(>F)"]])) NA_real_ else a[["Pr(>F)"]],
             check.names = FALSE)
}

tidy_aovlist <- function(fit) {
  s <- summary(fit)
  out <- lapply(names(s), function(nm) {
    a <- s[[nm]][[1]]
    data.frame(Stratum = nm, Source = trimws(rownames(a)), Df = a[["Df"]],
               SS = a[["Sum Sq"]], MS = a[["Mean Sq"]],
               F = if (is.null(a[["F value"]])) NA_real_ else a[["F value"]],
               p = if (is.null(a[["Pr(>F)"]])) NA_real_ else a[["Pr(>F)"]],
               check.names = FALSE)
  })
  do.call(rbind, out)
}

## residual mean square + df of a given stratum
strat_res <- function(tab, stratum) {
  r <- tab[tab$Stratum == stratum & tab$Source == "Residuals", ]
  list(ms = r$MS[1], df = r$Df[1], ss = r$SS[1])
}

t_weighted <- function(w1, t1, w2, t2) (w1 * t1 + w2 * t2) / (w1 + w2)

## Bartlett's test of homogeneity of k error variances, each an s^2 with df
## degrees of freedom (as they arise from k separate error mean squares).
## Used in combined analysis to decide whether the errors may be pooled.
bartlett_ms <- function(df, s2) {
  ok <- is.finite(df) & is.finite(s2) & df > 0 & s2 > 0
  df <- df[ok]; s2 <- s2[ok]; k <- length(s2)
  if (k < 2) return(NULL)
  N <- sum(df); sp2 <- sum(df * s2) / N
  num <- N * log(sp2) - sum(df * log(s2))
  C <- 1 + (sum(1 / df) - 1 / N) / (3 * (k - 1))
  chisq <- num / C
  list(chisq = chisq, df = k - 1, p = stats::pchisq(chisq, k - 1, lower.tail = FALSE),
       pooled_var = sp2, k = k)
}

## Factor levels in natural order: numbers inside labels compare as numbers, so
## D0, D60, D120, D180 and T1, T2, ..., T10 come out in the order people mean
## rather than the alphabetical D0, D120, D180, D60. A column that is already a
## factor keeps the order it was given; a numeric column sorts numerically.
natural_levels <- function(x) {
  if (is.factor(x)) return(levels(droplevels(x)))
  if (is.numeric(x)) return(levels(factor(x)))
  u <- unique(as.character(x[!is.na(x)]))
  if (!length(u)) return(u)
  ## dates in time order: sowing dates read by their day number alone ran
  ## 10 Nov, 25 Nov, 25 Oct
  dk <- date_key(u)
  if (!is.null(dk)) return(u[order(dk, u, method = "radix")])
  ## a thousands separator is part of the number (1,000 ppm); a decimal comma
  ## (5,6) is left for the data checks to flag
  s <- gsub("(?<=[0-9]),(?=[0-9]{3}([^0-9]|$))", "", u, perl = TRUE)
  ## a simple fraction (1/4 RDF) is one number; a dose such as 120/60/40 or
  ## 120/60 is not a fraction and keeps its numbers
  fr <- gregexpr("(?<![0-9./])[0-9]+/[0-9]+(?![0-9]|/[0-9])", s, perl = TRUE)
  regmatches(s, fr) <- lapply(regmatches(s, fr), function(h) vapply(h, function(z) {
    ab <- as.numeric(strsplit(z, "/", fixed = TRUE)[[1]])
    if (ab[1] < ab[2] && ab[2] <= 16) format(ab[1] / ab[2], digits = 10) else z
  }, ""))
  ## a sign belongs to the number only when it stands apart from the letters
  ## and digits before it: "-20 C" is negative, "SR-1" and "0-15 cm" are not
  num <- "(?:(?<![[:alnum:].])[-+])?[0-9]+(?:[.][0-9]+)?"
  m <- gregexpr(num, s, perl = TRUE)
  hits <- regmatches(s, m)
  ## each number is replaced by its zero-padded rank among all the numbers, so
  ## numbers of any size or sign compare correctly as text
  vals <- sort(unique(as.numeric(unlist(hits))))
  w <- nchar(length(vals))
  regmatches(s, m) <- lapply(hits, function(h)
    formatC(match(as.numeric(h), vals), width = w, flag = "0"))
  ## a label without a number beside numbered ones is usually the control or
  ## the starting point (Control, Fresh, Local check), so it comes first
  plain <- lengths(hits) == 0
  first <- if (sum(!plain) >= 2 && any(plain)) ifelse(plain, "0", "1") else ""
  u[order(paste0(first, tolower(s)), u, method = "radix")]
}

## A sort key for labels that are all dates, or NULL. Day and month name
## (25 Oct, Oct 25, 25-October-2023), with or without a year: without one, a
## season that runs over the new year (Oct, Nov, Jan) starts after the
## longest gap between the months used. Numeric dates (15/06/2023) are read
## day first, as they are written in India, unless a middle part above 12
## shows the month comes first.
date_key <- function(u) {
  lu <- tolower(u)
  if (all(grepl("^[0-9]{1,2}[/.-][0-9]{1,2}[/.-][0-9]{2,4}$", lu))) {
    p <- do.call(rbind, lapply(strsplit(lu, "[/.-]"), as.numeric))
    yr <- ifelse(p[, 3] < 100, 2000 + p[, 3], p[, 3])
    dm <- if (any(p[, 2] > 12) && all(p[, 1] <= 12)) p[, 2:1, drop = FALSE] else p[, 1:2, drop = FALSE]
    if (any(dm[, 2] > 12) || any(dm[, 1] > 31)) return(NULL)
    return(sprintf("%04d%02d%02d", yr, dm[, 2], dm[, 1]))
  }
  mon <- c(tolower(month.abb), "sept")
  w <- regmatches(lu, regexpr("(?<![[:alpha:]])[[:alpha:]]{3,9}(?![[:alpha:]])", lu, perl = TRUE))
  if (length(w) != length(u)) return(NULL)
  full <- tolower(month.name)
  m <- ifelse(w %in% full, match(w, full), match(w, mon))
  m[!is.na(m) & m == 13] <- 9
  if (anyNA(m)) return(NULL)
  ## nothing but the month word, the day, a year and separators
  rest <- gsub("[[:alpha:]]+", "", lu)
  if (any(grepl("[^0-9 ,./-]", rest))) return(NULL)
  nums <- regmatches(lu, gregexpr("[0-9]+", lu))
  yr <- vapply(nums, function(z) { y <- as.numeric(z[nchar(z) == 4]); if (length(y) == 1) y else NA_real_ }, 0)
  dy <- vapply(nums, function(z) { d <- as.numeric(z[nchar(z) <= 2]); if (length(d) == 1 && d >= 1 && d <= 31) d else NA_real_ }, 0)
  if (anyNA(dy) || length(unique(is.na(yr))) > 1) return(NULL)
  if (all(is.na(yr))) {
    used <- sort(unique(m))
    gaps <- c(diff(used), used[1] + 12 - used[length(used)])
    start <- used[(which.max(gaps) %% length(used)) + 1]
    m <- (m - start) %% 12
    yr <- 0
  }
  sprintf("%04d%02d%02d", yr, m, dy)
}

## cell means for a set of factors
eff_means <- function(d, resp, vars) {
  agg <- stats::aggregate(d[[resp]], by = d[vars], FUN = mean)
  names(agg)[ncol(agg)] <- "Mean"
  agg$N <- stats::aggregate(d[[resp]], by = d[vars], FUN = length)$x
  agg$SD <- stats::aggregate(d[[resp]], by = d[vars], FUN = stats::sd)$x
  agg[do.call(order, agg[vars]), , drop = FALSE]
}

## one label per row of a table of means, naming its level(s), as shown to the
## user and used for the dimnames of an effect's SE(d) and C.D. matrices
level_key <- function(df, vars)
  do.call(paste, c(lapply(df[vars], as.character), sep = " : "))

## the same, joined by a character that cannot appear in data, for matching
## cells internally: two cells whose level names contain " : " could otherwise
## share a label and be merged
cell_key <- function(df, vars)
  do.call(paste, c(lapply(df[vars], as.character), sep = "\u001f"))

## Least-squares (adjusted) means of `vars` from a fitted linear model, with
## their covariance matrix, in the order of `keys`. Each mean averages the
## model's predictions over every level of the other factors with equal weight,
## so a treatment that lost a plot is not pulled up or down by the block that
## plot was in, and a marginal mean is not weighted by unequal cell sizes. With
## complete, balanced data these are the plain averages with variance MSE / n.
## Base R only: the model matrix of a reference grid, coef() and vcov().
ls_means <- function(fit, vars, keys) {
  xl <- fit$xlevels
  grid <- expand.grid(xl, KEEP.OUT.ATTRS = FALSE, stringsAsFactors = FALSE)
  for (v in names(xl)) grid[[v]] <- factor(grid[[v]], levels = xl[[v]])
  X <- stats::model.matrix(stats::delete.response(stats::terms(fit)), grid,
                           contrasts.arg = fit$contrasts)
  g <- cell_key(grid, vars)
  L <- rowsum(X, g, reorder = FALSE) / as.vector(table(g)[unique(g)])
  L <- L[match(keys, rownames(L)), , drop = FALSE]
  ## a mean is estimable only if its row of L lies in the row space of the
  ## data's model matrix; otherwise the data cannot separate it from the blocks
  Xd <- stats::model.matrix(fit)
  off <- qr.resid(qr(t(Xd)), t(L))
  if (any(abs(off) > 1e-8 * max(1, abs(L))))
    stop("Some means cannot be estimated: the treatments that are present never ",
         "appear together in a block, so their differences cannot be separated ",
         "from the block differences.", call. = FALSE)
  b <- stats::coef(fit); ok <- !is.na(b)
  Lk <- L[, ok, drop = FALSE]
  V <- Lk %*% stats::vcov(fit)[ok, ok, drop = FALSE] %*% t(Lk)
  list(est = drop(Lk %*% b[ok]), V = V)
}

## One effect's table of means, with the standard errors and critical
## differences for every comparison. Every standard error comes from V, the
## covariance matrix of the means: SE(m)_i = sqrt(V_ii) and
## SE(d)_ij = sqrt(V_ii + V_jj - 2 V_ij). Without a fitted model the means are
## plain averages with V = diag(MSE / n_i), so with unequal replication each
## mean and each pair still gets its own value. Given `fit`, the means are
## least-squares means and V comes from the model, which is what blocked
## designs with a missing plot and factorials with unequal cells need.
new_effect <- function(d, resp, vars, mse, df, p, Fv, alpha, label = NULL, fit = NULL) {
  m <- eff_means(d, resp, vars)
  key <- level_key(m, vars)
  notes <- character(0)
  if (is.null(fit)) {
    V <- diag(mse / m$N, nrow(m))
  } else {
    ls <- ls_means(fit, vars, cell_key(m, vars))
    V <- ls$V
    ## judged on the means' own scale: values near 1e-8 (counts on the
    ## reciprocal scale) lost their adjustment against a floor of 1
    if (any(abs(ls$est - m$Mean) > 1e-8 * max(abs(c(m$Mean, ls$est)), 1e-300))) {
      m$Raw_mean <- m$Mean
      m$Mean <- unname(ls$est)
      notes <- paste0("The data are unbalanced, so these are adjusted (least-squares) ",
        "means: each is estimated as if every level had appeared in every block and ",
        "alongside every level of the other factors. The plain average of the data ",
        "is shown as the unadjusted mean.")
    }
  }
  dv <- diag(V)
  S <- sqrt(pmax(outer(dv, dv, "+") - 2 * V, 0))
  diag(S) <- 0
  dimnames(S) <- list(key, key)
  tq <- stats::qt(1 - alpha / 2, df)
  C <- tq * S
  m$SE <- sqrt(dv)
  m$Letter <- cld_lsd(m$Mean, C)
  e <- list(label = label %||% paste(vars, collapse = " x "), vars = vars,
            means = m, mse = mse, df = df, alpha = alpha, tcrit = tq,
            p = p, F = Fv, notes = notes)
  set_errors(e, m$SE, S, C)
}

## Attach the standard errors to an effect: the per-mean SE (already a column
## of the means), the SE(d) and C.D. matrices, and single values sem, sed and cd
## only when one number genuinely applies to every mean and every pair. When it
## does not they are NA, the range is kept for display, and equal_rep is FALSE,
## so no table can print one SE that fits some means and not others.
set_errors <- function(e, se, S, C) {
  off <- row(S) != col(S)
  sd_ <- S[off]; sd_ <- sd_[!is.na(sd_)]
  cd_ <- C[off]; cd_ <- cd_[!is.na(cd_)]
  same <- function(x) length(x) > 0 && diff(range(x)) <= 1e-9 * max(abs(x))
  one <- function(x) if (same(x)) x[1] else NA_real_
  n <- e$means$N
  e$sem <- one(se); e$sed <- one(sd_); e$cd <- one(cd_)
  e$se_range <- range(se)
  e$sed_range <- if (length(sd_)) range(sd_) else c(NA_real_, NA_real_)
  e$cd_range <- if (length(cd_)) range(cd_) else c(NA_real_, NA_real_)
  e$equal_rep <- same(se) && same(sd_)
  e$n_per_mean <- if (length(unique(n)) == 1L) n[1] else NA_real_
  e$sed_mat <- S; e$cd_mat <- C
  e
}

## An interaction effect from a design with several error strata (split plot,
## strip plot, pooled analysis). Only comparisons inside one level of `slice`
## share a single standard error, so the SE(d) and C.D. matrices are filled for
## those pairs and left NA across slices; letters and post-hoc tests then work
## one slice at a time. These designs are analysed only when complete, so every
## within-slice comparison has the same SE(d). The SE column here is the
## conventional SE(m) for those comparisons, SE(d) / sqrt(2), not the standard
## error of a cell mean on its own, which would also carry the main-plot (or
## environment) variation; plots and tables say so. `extra` holds the SE(d) and
## C.D. of the other comparisons, and `extra_p` the p-value that gates each
## C.D. (NA for an SE(d), which is always shown).
slice_effect <- function(m, vars, slice, label, se, sed, tcrit, mse, df, alpha,
                         p, Fv, extra, notes, ...) {
  key <- level_key(m, vars)
  k <- nrow(m)
  inside <- outer(as.character(m[[slice]]), as.character(m[[slice]]), "==")
  S <- matrix(NA_real_, k, k, dimnames = list(key, key))
  S[inside] <- sed
  diag(S) <- 0
  m$SE <- rep(se, k)
  e <- c(list(label = label, vars = vars, means = m, mse = mse, df = df,
              alpha = alpha, tcrit = tcrit, p = p, F = Fv, slice = slice,
              extra = extra, notes = notes), list(...))
  set_errors(e, m$SE, S, tcrit * S)
}

## The variance of a difference between two treatment means of a pooled
## factorial, with the environment random. A mean of the factors Sp (averaged
## over the others) carries the environment's interaction with every set of
## factors that shares one with Sp, and two means that differ in the factors D
## keep, in their difference, those that share one with D. Solving the
## expected mean squares (E x T random, unrestricted model) gives
## Var = 2 / (e r) * sum over V of w_V * MS(E x V), over the sets V within Sp
## that share a factor with D, with
##   w_V = prod_{f not in V} 1/n_f * prod_{f in V, not D} (1 - 1/n_f)
##         * [prod_{f in V and D} (1 - 1/n_f) - prod_{f in V and D} (-1/n_f)],
## which is never negative, so Gomez and Gomez's weighted t applies. With two
## factors this is their strip-plot formula with the environment as the
## replication: two A means at the same B have (b - 1) MS(E x A x B) +
## MS(E x A) over e r b. A main effect keeps MS(E x A) alone. `n` holds the
## number of levels of every treatment factor, named.
pool_weights <- function(n, Sp, D) {
  Vs <- unlist(lapply(seq_along(Sp), function(k) utils::combn(Sp, k, simplify = FALSE)),
               recursive = FALSE)
  w <- vapply(Vs, function(V) {
    vd <- intersect(V, D)
    if (!length(vd)) return(0)
    prod(1 / n[setdiff(names(n), V)]) * prod(1 - 1 / n[setdiff(V, D)]) *
      (prod(1 - 1 / n[vd]) - prod(-1 / n[vd]))
  }, numeric(1))
  names(w) <- vapply(Vs, paste, "", collapse = ":")
  w[w > 1e-12]
}

## An interaction of a pooled factorial: every pair of means has the SE(d) of
## the factors in which the two differ, and a C.D. from the weighted t of the
## mean squares in it. `ms` and `dfs` are the mean squares and df of E x V,
## named by the factors of V joined by ":". Each kind of comparison is listed
## in `extra`; `mix` keeps each one's mean squares for the post-hoc tests,
## which use Satterthwaite's degrees of freedom where they need them.
pool_effect <- function(d, resp, vars, n, ms, dfs, ne, r, alpha, p, Fv, label, mse, df) {
  m <- eff_means(d, resp, vars)
  key <- level_key(m, vars); k <- nrow(m)
  lv <- as.matrix(m[vars])
  D_of <- function(i, j) vars[lv[i, ] != lv[j, ]]
  types <- list(); tkey <- character(0)
  type <- matrix(0L, k, k)
  for (i in seq_len(k)) for (j in seq_len(k)) if (i != j) {
    D <- D_of(i, j); kk <- paste(D, collapse = ":")
    if (!kk %in% tkey) { tkey <- c(tkey, kk); types[[kk]] <- D }
    type[i, j] <- match(kk, tkey)
  }
  ## fewer factors differing first, then in the order of the factors
  o <- order(lengths(types), vapply(types, function(D) paste(match(D, vars) + 10, collapse = ""), ""))
  types <- types[o]; type[type > 0] <- match(type[type > 0], o)
  comp <- lapply(types, function(D) {
    w <- pool_weights(n, vars, D)
    list(w = w * ms[names(w)], df = dfs[names(w)])
  })
  sed <- vapply(comp, function(z) sqrt(2 * sum(z$w) / (ne * r)), numeric(1))
  tq  <- vapply(comp, function(z) sum(z$w * stats::qt(1 - alpha / 2, z$df)) / sum(z$w), numeric(1))
  S <- matrix(0, k, k, dimnames = list(key, key)); Tm <- S
  S[type > 0] <- sed[type[type > 0]]; Tm[type > 0] <- tq[type[type > 0]]
  C <- Tm * S
  ## the standard error of a mean as the tables show it: SE(d) / sqrt(2) for
  ## two means that differ in every factor
  u <- pool_weights(n, vars, vars)
  m$SE <- rep(sqrt(sum(u * ms[names(u)]) / (ne * r)), k)
  m$Letter <- cld_lsd(m$Mean, C)
  what <- vapply(types, function(D) {
    same <- setdiff(vars, D)
    if (length(same)) sprintf("two %s means at the same %s", paste(D, collapse = " x "),
                              paste(same, collapse = " x "))
    else if (length(D) == 2) sprintf("two means that differ in both %s", join_and(D))
    else sprintf("two means that differ in every factor (%s)", join_and(D))
  }, "")
  cdl <- cd_name(alpha)
  extra <- as.list(c(rbind(sed, tq * sed)))
  names(extra) <- c(rbind(paste0("SE(d): ", what), paste0(cdl, ": ", what)))
  sig <- !is.na(p) && p < alpha
  dft <- vapply(comp, function(z) sum(z$w)^2 / sum(z$w^2 / z$df), numeric(1))
  e <- list(label = label, vars = vars, means = m, mse = mse, df = df, alpha = alpha,
            tcrit = NA_real_, p = p, F = Fv, extra = extra,
            extra_p = rep(c(NA, p), length(types)),
            notes = if (sig) paste0("The environment is random, so the difference between two of ",
              "these means carries the environment's interaction with each factor in which they ",
              "differ: each kind of comparison has its own SE(d) and C.D., listed below, the ",
              "C.D. with Gomez and Gomez's weighted t. The letters use the C.D. of each pair.") else "",
            error_desc = sprintf(paste0("The environment is random, so the SE(d) of each pair ",
              "combines the mean squares of the environment's interactions with the factors in ",
              "which the two means differ. The LSD and Bonferroni tests use Gomez and Gomez's ",
              "weighted t; the tests that need degrees of freedom use Satterthwaite's ",
              "approximation for each pair (%s df)."),
              if (diff(range(dft)) < 0.05) fmt(dft[1], 1) else paste(fmt(min(dft), 1), "to", fmt(max(dft), 1))),
            mix = list(type = type, comp = comp))
  set_errors(e, m$SE, S, C)
}

## An effect's further comparisons (e$extra) as label and display text, each
## C.D. replaced by "NS" when the F-test it belongs to is not significant.
extra_text <- function(e, digits = 3) {
  if (is.null(e$extra)) return(NULL)
  v <- unlist(e$extra)
  p <- if (is.null(e$extra_p)) rep(NA_real_, length(v)) else e$extra_p
  txt <- ifelse(!is.na(p) & !(p < e$alpha), "NS", fmt(v, digits))
  stats::setNames(txt, names(e$extra))
}

## Two-sided critical t for an effect at level alpha: plain t on the effect's
## error df, or, for a comparison whose standard error mixes two error terms,
## the weighted t of Gomez & Gomez (1984) stored in t_mix.
t_crit <- function(e, alpha) {
  if (is.null(e$t_mix)) return(stats::qt(1 - alpha / 2, e$df))
  w <- e$t_mix$w
  sum(w * stats::qt(1 - alpha / 2, e$t_mix$df)) / sum(w)
}
## For an effect whose pairs mix several error mean squares, each pair its
## own way (a pooled factorial's interactions, see pool_effect()): each pair's
## weighted t at two-sided level a, and its Satterthwaite degrees of freedom,
## as matrices over the effect's means.
mix_t <- function(e, a) {
  tt <- vapply(e$mix$comp, function(z) sum(z$w * stats::qt(1 - a / 2, z$df)) / sum(z$w), numeric(1))
  matrix(tt[pmax(e$mix$type, 1L)], nrow(e$mix$type))
}
mix_df <- function(e) {
  dd <- vapply(e$mix$comp, function(z) sum(z$w)^2 / sum(z$w^2 / z$df), numeric(1))
  matrix(dd[pmax(e$mix$type, 1L)], nrow(e$mix$type))
}
## the error degrees of freedom as a table states them
df_label <- function(e, ix = seq_len(nrow(e$means))) {
  if (is.null(e$mix)) return(df_text(e$df))
  r <- range(mix_df(e)[ix, ix][row(diag(length(ix))) != col(diag(length(ix)))])
  if (diff(r) < 0.05) paste(fmt(r[1], 1), "(Satterthwaite)")
  else sprintf("%s to %s, by pair (Satterthwaite)", fmt(r[1], 1), fmt(r[2], 1))
}
`%||%` <- function(a, b) if (is.null(a)) b else a

## ---------------------------------------------------------- data_quality.R ----
###############################################################################
##  DATA QUALITY
###############################################################################
## Checks run on the data as soon as it is loaded, before any analysis. Each
## problem is described in plain words with the rows it affects and, where a
## correction is safe, what that correction will be. Nothing is changed until
## the user asks, and then only entry by entry: a value is rewritten only when
## its meaning is certain (5,6 is 5.6; "n/a" means no value). An entry whose
## meaning is not certain (12a, nil, 1,250, a word among numbers, a % sign on
## some entries only) is never changed or emptied; it is listed for the user,
## and an analysis that cannot use it says so.

## what people type for "no value", including the error values Excel pastes
## along with the data. "nil" is not here: in field records it usually means
## zero, so it is shown to the user instead.
MISSING_MARKS <- c("na", "n/a", "n.a.", "n.a", "missing", "-", "--", "---",
                   ".", "?", "*", "nd", "n.d.", "#n/a", "#value!", "#div/0!",
                   "#num!", "#ref!", "#name?", "#null!")

## Units that may follow a number in a column of measurements. Only these are
## recognised, so that a variety such as "1121 Basmati", a stage such as
## "30 DAS" or DMRT letters such as "12ab" are never taken for units.
KNOWN_UNITS <- c("kg", "g", "mg", "t", "q", "qt", "ha", "cm", "mm", "m", "km",
                 "m2", "cm2", "mm2", "ml", "l", "kg/ha", "q/ha", "t/ha", "g/plant",
                 "g/m2", "kg/m2", "kg/plot", "g/plot", "ppm", "ppb", "ds/m",
                 "mg/kg", "mg/l", "mg/g", "g/kg")

## user text going into HTML: "<LOD" must show as text, not open a tag
esc <- function(x) {
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  gsub(">", "&gt;", x, fixed = TRUE)
}

## one or many: pl(1, "row", "rows")
pl <- function(n, one, many) if (n == 1) one else many

## the row numbers shown in the data table, which are the data frame's row
## names, so that numbers in messages are ones the user can find
row_ids <- function(d) {
  id <- suppressWarnings(as.integer(rownames(d)))
  if (anyNA(id)) seq_len(nrow(d)) else id
}

## "row 3" or "rows 3, 7 and 12" (at most eight listed)
rows_text <- function(i) {
  if (!length(i)) return("")
  paste(pl(length(i), "row", "rows"), join_and(head_more(as.character(i), 8)))
}

## a few entries, quoted, saying "such as" when there are more
eg_text <- function(x) {
  u <- unique(x)
  paste0(if (length(u) > 3) "such as " else "", join_and(sprintf("'%s'", head(u, 3))))
}

## a number as it will be written back: as many digits as it needs, no more
## (never in scientific notation: 400000, not 4e+05, which would also be
## written into the data by a correction)
num_text <- function(v) vapply(v, function(z) format(z, digits = 15, trim = TRUE, scientific = FALSE), "")

## rows with no value in any cell: empty, or holding only entries such as "-"
## or "n/a", so that one pass of the corrections removes them
empty_rows <- function(d) {
  if (!nrow(d) || !ncol(d)) return(integer(0))
  which(Reduce(`&`, lapply(d, function(x) {
    s <- trimws(as.character(x))
    is.na(x) | s == "" | tolower(s) %in% MISSING_MARKS
  })))
}

## a label tidied of spacing only: no-break spaces made plain, runs of spaces
## made single, the ends trimmed. Nothing else in a label is touched; a dash
## or a capital letter may carry meaning.
label_tidy <- function(x) {
  s <- as.character(x)
  for (ch in ODD_SPACES) s <- gsub(ch, " ", s, fixed = TRUE)
  gsub("[[:space:]]+", " ", trimws(s))
}

## Characters that look like a minus sign or a space but are not the plain
## ones: the minus sign and en dash from Word, the no-break spaces Excel puts
## between thousands. Built here rather than written into the source, which
## must stay ASCII.
ODD_MINUS  <- intToUtf8(c(0x2212, 0x2013), multiple = TRUE)
ODD_SPACES <- intToUtf8(c(0x00A0, 0x202F, 0x2009), multiple = TRUE)

## How the number part of an entry reads (no % sign or unit attached).
read_core <- function(core) {
  n <- length(core)
  kind <- rep("text", n); value <- rep(NA_real_, n)
  num <- function(v) suppressWarnings(as.numeric(v))
  plain <- grepl("^[-+]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][-+]?[0-9]+)?$", core)
  ## 1,250 may be a thousands separator or a decimal comma; 0,125 cannot be
  ## thousands, so it is a decimal comma
  three <- grepl("^[-+]?[1-9][0-9]{0,2},[0-9]{3}$", core)
  comma <- grepl("^[-+]?[0-9]+,[0-9]+$", core) & !three
  thous <- grepl("^[-+]?[1-9][0-9]{0,2}(,[0-9]{3})+([.][0-9]+)?$", core) & !three
  space <- grepl("^[-+]?[1-9][0-9]{0,2}( [0-9]{3})+([.,][0-9]+)?$", core)
  euro  <- grepl("^[-+]?[1-9][0-9]{0,2}([.][0-9]{3})+,[0-9]+$", core)
  value[plain] <- num(core[plain])
  value[comma] <- num(sub(",", ".", core[comma], fixed = TRUE))
  value[thous] <- num(gsub(",", "", core[thous], fixed = TRUE))
  value[space] <- num(sub(",", ".", gsub(" ", "", core[space], fixed = TRUE), fixed = TRUE))
  value[euro]  <- num(sub(",", ".", gsub(".", "", core[euro], fixed = TRUE), fixed = TRUE))
  kind[plain] <- "number"; kind[comma] <- "comma"; kind[thous | space] <- "thousands"
  kind[euro] <- "european"; kind[three] <- "ambiguous"
  list(kind = kind, value = value)
}

## How each entry reads as a number. `kind` is one of
##   blank      empty
##   mark       a no-value marker such as n/a, - or #DIV/0!
##   number     a plain number with a decimal point (5.6, -2, 1e3)
##   comma      a decimal comma (5,6; 0,125; 1234,5)
##   ambiguous  1,250: a thousands separator or a decimal comma
##   thousands  1,250,000; 1,250.5; 1 250
##   european   1.250,5 (point between thousands, decimal comma)
##   percent    45% or 4,5 %
##   unit       a number followed by a known unit (45 cm, 2.5kg, 12 q/ha)
##   text       anything else
## `value` is the number it would be, `text` the entry tidied of odd spaces and
## minus signs, `unit` the unit text, and `core` the kind of the number part of
## an entry with a % sign or a unit.
read_entries <- function(x) {
  s <- as.character(x)
  s[is.na(s)] <- ""
  for (ch in ODD_SPACES) s <- gsub(ch, " ", s, fixed = TRUE)
  for (ch in ODD_MINUS) s <- gsub(ch, "-", s, fixed = TRUE)
  s <- trimws(s)
  n <- length(s)
  pct <- grepl("^[-+]?[0-9][0-9., ]*%$", s)
  sci <- grepl("^[-+]?([0-9]+([.][0-9]*)?|[.][0-9]+)[eE][-+]?[0-9]+$", s)
  ut  <- ifelse(!pct & !sci, sub("^[-+]?[0-9][0-9.,]* ?", "", s), "")
  ## a known unit, with a space before it or at least two letters (45 cm,
  ## 2.5kg): a single letter stuck to a number (5m, 12a) may well be a code
  unit <- !pct & !sci & grepl("^[-+]?[0-9][0-9.,]*( [A-Za-z]|[A-Za-z]{2})[A-Za-z/0-9]*$", s) &
          tolower(ut) %in% KNOWN_UNITS
  core <- s
  core[pct] <- trimws(sub("%$", "", s[pct]))
  core[unit] <- sub("^([-+]?[0-9][0-9.,]*) ?[A-Za-z].*$", "\\1", s[unit])
  r <- read_core(core)
  kind <- r$kind; value <- r$value; ckind <- r$kind
  ok <- !ckind %in% c("text", "ambiguous")
  kind[pct & ok] <- "percent"
  kind[unit & ok] <- "unit"
  kind[(pct | unit) & !ok] <- ifelse(ckind[(pct | unit) & !ok] == "ambiguous", "ambiguous", "text")
  un <- rep("", n)
  un[unit] <- ut[unit]
  un[pct] <- "%"
  kind[tolower(s) %in% MISSING_MARKS & s != ""] <- "mark"
  kind[s == ""] <- "blank"
  value[!kind %in% c("number", "comma", "thousands", "european", "percent", "unit")] <- NA_real_
  list(kind = kind, value = value, text = s, unit = un, core = ckind)
}

NUMBER_KINDS <- c("number", "comma", "ambiguous", "thousands", "european", "percent", "unit")

## A response as the analysis uses it: a column of numbers as it is; a column
## of text read entry by entry, keeping only entries that are plainly numbers.
## Anything the data check would flag (5,6; 45%; 0x10; 12a) is left out, with
## the reason recorded by excluded_rows().
response_values <- function(x) {
  if (is.numeric(x)) return(x)
  r <- read_entries(x)
  ifelse(r$kind == "number", r$value, NA_real_)
}

## Everything the check and the corrections need to know about one column.
## A column is read as numbers when at least three quarters of its filled-in,
## non-marker entries read as numbers in some notation, and as labels when
## fewer than a quarter do; in between it is a mixture the user should see.
## `new` holds each entry's corrected form, or NA where nothing is changed.
assess_column <- function(x) {
  raw <- as.character(x)
  r <- read_entries(x)
  k <- r$kind; txt <- r$text
  real <- !k %in% c("blank", "mark")
  share <- if (any(real)) mean(k[real] %in% NUMBER_KINDS) else 0
  role <- if (!any(real)) "empty" else if (share >= 0.75) "numbers" else
          if (share >= 0.25) "mixed" else "labels"
  ## which notation the column writes its decimals in; an entry like 1.250 is
  ## not evidence of decimal points, since it is the very thing in doubt
  dot3_pat <- "^[-+]?[0-9]{1,3}([.][0-9]{3})+$"
  dot_dec <- any((k == "number" & grepl(".", txt, fixed = TRUE) & !grepl(dot3_pat, txt)) |
                 (k == "thousands" & grepl("[.][0-9]+$", txt)) |
                 (k %in% c("percent", "unit") & r$core == "number" & grepl(".", txt, fixed = TRUE)))
  comma_dec <- any(k %in% c("comma", "european") |
                   (k == "thousands" & grepl(",[0-9]+$", txt) & grepl(" ", txt, fixed = TRUE)) |
                   (k %in% c("percent", "unit") & r$core == "comma"))
  sep <- any(k == "thousands" & grepl(",[0-9]{3}", txt))
  ## 1,250 is settled by the rest of the column: decimal commas and no
  ## decimal points means a decimal; decimal points or separators and no
  ## decimal commas means a thousands separator; both or neither, the user
  ## must say
  three <- if (comma_dec && !dot_dec && !sep) "comma" else
           if ((dot_dec || sep) && !comma_dec) "thousands" else NA_character_
  ## in a column written with decimal commas, 1.250 is the mirror image
  dot3_rows <- if (comma_dec && !dot_dec) which(k == "number" & grepl(dot3_pat, txt)) else integer(0)
  ## a % sign or a unit is dropped only when every number in the column
  ## carries it (and, for units, the same one): 62% beside 0.45 and 0.50, or
  ## 1.5 kg beside 1500, may be on another scale. Entries such as 1,250 kg
  ## count too.
  numlike <- k %in% NUMBER_KINDS
  has_pct <- r$unit == "%"
  has_unit <- r$unit != "" & !has_pct
  units <- unique(r$unit[has_unit & numlike])
  all_pct <- any(has_pct & numlike) && all(has_pct[numlike])
  all_unit <- length(units) == 1 && all(has_unit[numlike])
  val <- r$value
  amb <- k == "ambiguous"
  ## While a 1,250 or a 1.250 waits for the user, no other number in the
  ## column is rewritten: changing 5,6 to 5.6 would change the evidence, and a
  ## second press of the button would then settle the doubtful entry by itself.
  hold <- (any(amb) && is.na(three)) || length(dot3_rows) > 0
  if (any(amb) && !is.na(three)) {
    cr <- sub(" ?%$", "", sub(" ?[A-Za-z].*$", "", txt[amb]))
    val[amb] <- suppressWarnings(as.numeric(
      if (three == "comma") sub(",", ".", cr, fixed = TRUE) else gsub(",", "", cr, fixed = TRUE)))
  }
  sign_ok <- (!has_unit & !has_pct) | (has_unit & all_unit) | (has_pct & all_pct)
  new <- rep(NA_character_, length(k))
  if (role == "numbers" && !hold) {
    change <- (k %in% c("comma", "thousands", "european") & sign_ok) |
              (k %in% c("percent", "unit") & sign_ok) | (amb & !is.na(three) & sign_ok) |
              (k == "number" & !is.na(raw) & txt != trimws(raw))       # odd minus or spaces
    new[change] <- num_text(val[change])
  }
  list(r = r, kind = k, txt = txt, raw = raw, role = role, share = share, three = three,
       dot3_rows = dot3_rows, all_pct = all_pct, all_unit = all_unit, units = units,
       has_pct = has_pct, has_unit = has_unit, hold = hold, value = val, new = new)
}

## The checks on labels (used for columns of labels and for mixtures): extra
## spaces, which are certainly a slip and are tidied; and labels that differ
## only in capitals or punctuation, which can carry meaning (genotypes AA, Aa,
## aa; codes T1 and T-1) and are therefore shown, never merged.
label_issues <- function(v, a, keep, at, add) {
  real <- intersect(which(!a$kind %in% c("blank", "mark")), keep)
  if (!length(real)) return(invisible())
  tidy <- label_tidy(a$raw)
  sp <- real[!is.na(a$raw[real]) & a$raw[real] != tidy[real]]
  if (length(sp))
    add(v, "correct", sprintf(paste0("In '%s', %s %s extra spaces in the label (%s). ",
      "They will be removed so that %s the same label as the rest."), v, rows_text(at(sp)),
      pl(length(sp), "has", "have"), eg_text(a$raw[sp]),
      pl(length(sp), "it counts as", "they count as")), at(sp))
  if (length(real) < 2) return(invisible())
  lab <- tidy[real]
  g1 <- split(real, tolower(lab))
  g1 <- g1[vapply(g1, function(i) length(unique(tidy[i])) > 1, logical(1))]
  if (length(g1)) {
    ex <- head_more(vapply(g1, function(i) join_and(sprintf("'%s'", unique(tidy[i]))), ""), 4)
    add(v, "check", sprintf(paste0("In '%s', some labels differ only in capital letters (%s), so ",
      "the analysis treats them as different groups. If they are the same, retype them in the ",
      "table so they match exactly."), v, paste(ex, collapse = "; ")),
      at(sort(unlist(g1))), fixable = FALSE)
  }
  ## the same letters and the same numbers written with different spacing or
  ## punctuation (T1, T-1, T 1); labels whose numbers differ (1.5 kg and
  ## 15 kg, -10 and 10) are not grouped
  nums <- vapply(regmatches(lab, gregexpr("(?<![[:alnum:].])[-+]?[0-9]+([.][0-9]+)?|[0-9]+([.][0-9]+)?",
                                          lab, perl = TRUE)), paste, "", collapse = "|")
  key <- paste(gsub("[^[:alpha:]]", "", tolower(lab)), nums)
  g2 <- split(real, key)
  g2 <- g2[vapply(g2, function(i) length(unique(tolower(tidy[i]))) > 1, logical(1))]
  if (length(g2)) {
    ## one spelling for each way of writing it, ignoring capitals (those are
    ## reported above), with the rows that use exactly that spelling
    rep_rows <- lapply(g2, function(i) {
      cls <- split(i, tolower(tidy[i]))
      unlist(lapply(cls, function(j) { tb <- table(tidy[j]); j[tidy[j] == names(tb)[which.max(tb)]] }))
    })
    ex <- head_more(vapply(rep_rows, function(i) {
      u <- unique(tidy[i])
      join_and(sprintf("'%s' (%s)", u, vapply(u, function(z) rows_text(at(i[tidy[i] == z])), "")))
    }, ""), 4)
    add(v, "check", sprintf(paste0("In '%s', some labels differ only in spaces or punctuation: %s. ",
      "The analysis treats them as different groups. If they are the same, retype them in the ",
      "table so they match exactly."), v, paste(ex, collapse = "; ")),
      at(sort(unlist(rep_rows))), fixable = FALSE)
  }
}

#' Check data for common entry problems
#'
#' Looks through every column for the problems that most often spoil an
#' analysis of field data: numbers written with a decimal comma, decimal points
#' and commas mixed in one column, thousands separators, per cent signs and
#' units typed after numbers, numbers stored as text, entries that are not
#' numbers, empty cells and the markers people type for them (such as n/a or
#' Excel's #DIV/0!), labels that differ only in spacing, capitals or
#' punctuation, and empty or repeated rows. Each problem is described with the
#' rows it affects and, where a correction is safe, what the correction would
#' be. Nothing is changed; see \code{\link{fix_data}}.
#'
#' @param d A data frame, as loaded.
#'
#' @return A list with \code{issues}, a list with one element per problem
#'   (\code{column}; \code{level}: \code{"correct"} for a correction
#'   \code{\link{fix_data}} will make, \code{"check"} for something only the
#'   user can settle, \code{"note"} for information; \code{message};
#'   \code{rows}, as row numbers of the data; \code{fixable}), and
#'   \code{numeric} and \code{labels}, the columns read as numbers and as
#'   labels.
#'
#' @examples
#' d <- data.frame(Variety = c("V1", "V1", "V2", "V2"),
#'                 Yield = c("5,6", "6.1", "n/a", "12a"))
#' chk <- check_data(d)
#' vapply(chk$issues, `[[`, "", "message")
#'
#' @export
check_data <- function(d) {
  issues <- list()
  add <- function(column, level, message, rows = integer(0), fixable = level == "correct")
    issues[[length(issues) + 1L]] <<- list(column = column, level = level, message = message,
                                           rows = rows, fixable = fixable)
  ids <- row_ids(d)
  numeric_cols <- character(0); label_cols <- character(0)

  empty <- empty_rows(d)
  if (length(empty))
    add(NA, "correct", sprintf("%s %s no values and will be removed.",
      sub("^r", "R", rows_text(ids[empty])), pl(length(empty), "has", "have")), ids[empty])
  keep <- setdiff(seq_len(nrow(d)), empty)
  at <- function(i) ids[intersect(i, keep)]

  for (v in names(d)) {
    x <- d[[v]]
    if (is.numeric(x)) {
      numeric_cols <- c(numeric_cols, v)
      miss <- at(which(is.na(x) & !is.nan(x)))
      if (length(miss))
        add(v, "note", sprintf("In '%s', %s %s empty, so %s left out of any analysis that uses '%s'.",
          v, rows_text(miss), pl(length(miss), "is", "are"), pl(length(miss), "it is", "they are"), v), miss)
      ## Inf, -Inf or NaN (a division by zero, say) is not a measurement
      odd <- intersect(which(is.nan(x) | is.infinite(x)), keep)
      if (length(odd))
        add(v, "check", sprintf(paste0("In '%s', %s %s %s (%s). Correct %s in the table; until then %s ",
          "left out of any analysis of '%s'."), v, rows_text(at(odd)), pl(length(odd), "has", "have"),
          pl(length(odd), "an entry that is not a number", "entries that are not numbers"),
          eg_text(as.character(x[odd])), pl(length(odd), "it", "them"),
          pl(length(odd), "that row is", "those rows are"), v), at(odd), fixable = FALSE)
      next
    }
    a <- assess_column(x)
    k <- a$kind; txt <- a$txt
    marks <- function() {
      w <- intersect(which(k == "mark"), keep)
      if (length(w))
        add(v, "correct", sprintf(paste0("In '%s', %s %s %s, meaning no value. %s will be emptied ",
          "and treated as missing. If a value meant zero, type 0 instead."), v, rows_text(at(w)),
          pl(length(w), "has", "have"), eg_text(txt[w]), pl(length(w), "It", "They")), at(w))
    }
    blanks <- function() {
      w <- at(which(k == "blank"))
      if (length(w))
        add(v, "note", sprintf("In '%s', %s %s empty, so %s left out of any analysis that uses '%s'.",
          v, rows_text(w), pl(length(w), "is", "are"), pl(length(w), "it is", "they are"), v), w)
    }
    if (a$role == "empty") {
      if (any(k == "mark")) { label_cols <- c(label_cols, v); marks() }
      else add(v, "note", sprintf("Column '%s' is empty.", v))
      next
    }

    if (a$role == "numbers") {
      numeric_cols <- c(numeric_cols, v)
      hp <- a$has_pct & k %in% NUMBER_KINDS; hu <- a$has_unit & k %in% NUMBER_KINDS
      ## while a doubtful entry waits for the user, the column's other number
      ## corrections wait too (see assess_column); say what is waiting
      pend <- if (a$hold) c(
        if (any(k[keep] == "comma")) "decimal commas",
        if (any(k[keep] %in% c("thousands", "european"))) "thousands separators",
        if (any(hp[keep])) "% signs", if (any(hu[keep])) "units") else character(0)
      waiting <- if (length(pend)) sprintf(" The other corrections to '%s' (%s) will be offered once this is settled.",
                                           v, join_and(pend)) else ""
      if (!a$hold) {
        w <- intersect(which(k == "comma"), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s written with a decimal comma (%s)%s. ",
            "%s will be changed to %s, so %s becomes %s."), v, rows_text(at(w)),
            pl(length(w), "is", "are"), eg_text(txt[w]),
            if (any(k == "number" & grepl(".", txt, fixed = TRUE))) ", while other entries use a decimal point" else "",
            pl(length(w), "The comma", "The commas"), pl(length(w), "a point", "points"),
            txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(k == "thousands"), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s a separator between the thousands (%s). ",
            "It will be removed, so %s becomes %s."), v, rows_text(at(w)),
            pl(length(w), "has", "have"), eg_text(txt[w]), txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(k == "european"), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s written with a point between the thousands ",
            "and a decimal comma (%s). %s will be read the usual way, so %s becomes %s."),
            v, rows_text(at(w)), pl(length(w), "is", "are"), eg_text(txt[w]),
            pl(length(w), "It", "They"), txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(hp), keep)
        if (length(w) && a$all_pct)
          add(v, "correct", sprintf(paste0("In '%s', every value has a %% sign (%s). The signs will be ",
            "dropped, so %s becomes %s."), v, eg_text(txt[w]), txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(hu), keep)
        if (length(w) && a$all_unit)
          add(v, "correct", sprintf(paste0("In '%s', every value has the unit '%s' after it. It will be ",
            "dropped, so %s becomes %s; consider putting the unit in the column name."),
            v, a$units[1], txt[w[1]], a$new[w[1]]), at(w))
        w <- intersect(which(k == "number" & !is.na(a$new)), keep)
        if (length(w))
          add(v, "correct", sprintf(paste0("In '%s', %s %s a minus sign or space typed with an unusual ",
            "character (%s). %s will be written the usual way, as %s."), v, rows_text(at(w)),
            pl(length(w), "has", "have"), eg_text(a$raw[w]), pl(length(w), "It", "They"),
            join_and(head(a$new[w], 3))), at(w))
      }
      w <- intersect(which(hp), keep)
      if (length(w) && !a$all_pct)
        add(v, "check", sprintf(paste0("In '%s', %s %s a %% sign (%s) but other values do not, so they ",
          "may be on a different scale (62%% beside 0.45 could be 0.62). Make them consistent in the ",
          "table; until then %s left out of any analysis of '%s'."), v, rows_text(at(w)),
          pl(length(w), "has", "have"), eg_text(txt[w]), pl(length(w), "it is", "they are"), v),
          at(w), fixable = FALSE)
      w <- intersect(which(hu), keep)
      if (length(w) && !a$all_unit)
        add(v, "check", if (length(a$units) > 1)
          sprintf(paste0("In '%s', the values carry different units (%s). Convert them to one unit, ",
            "without the unit text, in the table; until then %s left out of any analysis of '%s'."),
            v, eg_text(txt[w]), pl(length(w), "that row is", "those rows are"), v)
          else sprintf(paste0("In '%s', %s %s the unit '%s' after the number but other values have none, ",
            "so they may be on a different scale. Make them consistent in the table; until then %s ",
            "left out of any analysis of '%s'."), v, rows_text(at(w)), pl(length(w), "has", "have"),
            a$units[1], pl(length(w), "it is", "they are"), v), at(w), fixable = FALSE)
      w <- intersect(which(k == "ambiguous"), keep)
      two <- function(z) { z <- sub(" ?%$", "", sub(" ?[A-Za-z].*$", "", z))
        c(gsub(",", "", z, fixed = TRUE), sub(",", ".", z, fixed = TRUE)) }
      w2 <- w[!is.na(a$new[w])]                 # settled, and their sign or unit can go
      if (length(w2) && !is.na(a$three))
        add(v, "correct", sprintf(paste0("In '%s', %s (%s) could mean %s or %s. %s will be read as %s, ",
          "because the rest of the column uses %s. If that is wrong, retype %s in the table."),
          v, rows_text(at(w2)), eg_text(txt[w2]), two(txt[w2[1]])[1], two(txt[w2[1]])[2],
          pl(length(w2), "It", "They"), a$new[w2[1]],
          if (a$three == "comma") "decimal commas" else "decimal points or thousands separators",
          pl(length(w2), "it", "them")), at(w2))
      else if (length(w) && is.na(a$three))
        add(v, "check", sprintf(paste0("In '%s', %s (%s) could mean %s or %s, and the rest of the ",
          "column does not show which. Retype %s as %s or as %s, whichever you meant; until then ",
          "%s left out of any analysis of '%s'.%s"), v, rows_text(at(w)), eg_text(txt[w]),
          two(txt[w[1]])[1], two(txt[w[1]])[2], pl(length(w), "it", "each"),
          two(txt[w[1]])[1], two(txt[w[1]])[2], pl(length(w), "it is", "they are"), v, waiting),
          at(w), fixable = FALSE)
      w <- intersect(a$dot3_rows, keep)
      if (length(w))
        add(v, "check", sprintf(paste0("In '%s', %s (%s) could mean %s or %s: the rest of the column ",
          "uses decimal commas, where a point usually separates thousands. Retype %s as %s or as %s, ",
          "whichever you meant.%s"), v, rows_text(at(w)), eg_text(txt[w]),
          gsub(".", "", txt[w[1]], fixed = TRUE), txt[w[1]], pl(length(w), "it", "each"),
          gsub(".", "", txt[w[1]], fixed = TRUE), txt[w[1]],
          if (any(k[keep] == "ambiguous") && is.na(a$three)) "" else waiting),
          at(w), fixable = FALSE)
      nil <-intersect(which(k == "text" & tolower(txt) %in% c("nil", "none", "zero")), keep)
      if (length(nil))
        add(v, "check", sprintf(paste0("In '%s', %s %s %s. If %s zero, type 0; if %s no value, clear ",
          "the cell. Until then %s left out of any analysis of '%s'."), v, rows_text(at(nil)),
          pl(length(nil), "has", "have"), eg_text(txt[nil]), pl(length(nil), "it means", "they mean"),
          pl(length(nil), "it means", "they mean"), pl(length(nil), "that row is", "those rows are"), v),
          at(nil), fixable = FALSE)
      w <- setdiff(intersect(which(k == "text"), keep), nil)
      if (length(w)) {
        recurs <- any(duplicated(tolower(txt[w])))
        add(v, "check", sprintf(paste0("'%s' is mostly numbers, but %s %s %s (%s).%s If '%s' holds ",
          "measurements, correct %s in the table; until then %s left out of any analysis of '%s'."),
          v, rows_text(at(w)), pl(length(w), "has", "have"),
          pl(length(w), "an entry that is not a number", "entries that are not numbers"), eg_text(txt[w]),
          if (recurs) sprintf(" That is fine if '%s' holds labels, such as treatment codes with a check.", v)
          else "", v, pl(length(w), "it", "them"), pl(length(w), "that row is", "those rows are"), v),
          at(w), fixable = FALSE)
      }
      if (!any(k[keep] %in% c("comma", "thousands", "european", "percent", "unit", "ambiguous",
                              "text", "mark")) && !length(a$dot3_rows))
        add(v, "correct", sprintf(paste0("'%s' contains only numbers but is being read as text. It ",
          "will be changed to a column of numbers."), v))
      marks(); blanks()
      next
    }

    label_cols <- c(label_cols, v)
    if (a$role == "mixed") {
      w <- intersect(which(!k %in% c(NUMBER_KINDS, "blank", "mark")), keep)
      add(v, "check", sprintf(paste0("'%s' is being read as labels, not numbers, because %d of its %d ",
        "filled-in entries %s (%s). If it should hold numbers, correct %s in the table."), v,
        length(w), sum(!k[keep] %in% c("blank", "mark")),
        pl(length(w), "is not a number", "are not numbers"), eg_text(txt[w]),
        pl(length(w), "that entry", "those entries")), at(w), fixable = FALSE)
    }
    marks(); blanks()
    label_issues(v, a, keep, at, add)
  }

  ## identical rows: often two plots that happen to have the same values, so
  ## this is information, not an error
  if (length(keep) > 1) {
    rk <- do.call(paste, c(lapply(d[keep, , drop = FALSE], as.character), sep = "|"))
    grp <- split(keep, rk)
    grp <- grp[lengths(grp) > 1]
    if (length(grp)) {
      sets <- vapply(grp, function(i) join_and(as.character(ids[i])), "")
      rest <- sets[-1]
      more <- if (!length(rest)) "" else paste0(", and so are rows ",
        paste(head(rest, 3), collapse = "; rows "),
        if (length(rest) > 3) sprintf("; and %d more groups", length(rest) - 3) else "")
      add(NA, "note", sprintf(paste0("Rows %s are identical in every column%s. If a row was entered ",
        "twice, delete the extra copy in your spreadsheet and load it again; if they are separate ",
        "plots that happen to have the same values, leave them."), sets[1], more),
        ids[sort(unlist(grp))])
    }
  }
  list(issues = issues, numeric = numeric_cols, labels = label_cols)
}

#' Apply the safe corrections found by check_data
#'
#' Makes only the corrections whose meaning is certain, entry by entry:
#' decimal commas become points, thousands separators are removed, a per cent
#' sign or a unit carried by every value in a column is dropped, entries such
#' as n/a or - are emptied, extra spaces in labels are removed, and empty rows
#' are deleted. A column becomes a column of numbers once every entry in it is
#' a number. Entries whose meaning is not certain, such as 12a, nil, or 1,250
#' where the column does not show which notation it uses, are left exactly as
#' they are, and labels that differ in capitals or punctuation are not merged.
#'
#' @param d A data frame, as loaded.
#'
#' @return A list with \code{data}, the corrected data frame (row names kept,
#'   so row numbers still match the data as loaded), and \code{log}, a
#'   character vector saying what was changed.
#'
#' @examples
#' d <- data.frame(Variety = c("V1", "V1", "V2", "V2"),
#'                 Yield = c("5,6", "6.1", "n/a", "7,2"))
#' fix_data(d)
#'
#' @export
fix_data <- function(d) {
  log <- character(0)
  ids <- row_ids(d)
  empty <- empty_rows(d)
  keep <- setdiff(seq_len(nrow(d)), empty)
  for (v in names(d)) {
    x <- d[[v]]
    if (is.numeric(x)) next
    a <- assess_column(x)
    k <- a$kind
    out <- a$raw
    say <- function(w, what) if (length(w))
      log <<- c(log, sprintf("'%s': %s (%s).", v, what, rows_text(ids[w])))
    if (a$role == "numbers") {
      ch <- intersect(which(!is.na(a$new)), keep)
      out[ch] <- a$new[ch]
      say(intersect(which(k == "comma"), ch), "decimal commas changed to points")
      say(intersect(which(k %in% c("thousands", "european")), ch), "thousands separators removed")
      say(intersect(which(k == "percent"), ch), "per cent signs dropped")
      say(intersect(which(k == "unit"), ch), sprintf("the unit '%s' dropped", a$units[1]))
      say(intersect(which(k == "ambiguous"), ch),
          if (identical(a$three, "comma")) "entries such as 1,250 read as decimals"
          else "entries such as 1,250 read as thousands")
      say(intersect(which(k == "number"), ch), "unusual minus signs or spaces tidied")
    }
    mk <- intersect(which(k == "mark"), keep)
    out[mk] <- NA
    say(mk, "entries meaning no value emptied")
    if (a$role %in% c("labels", "mixed")) {
      tidy <- label_tidy(a$raw)
      sp <- intersect(which(!is.na(out) & out != tidy & !k %in% c("blank", "mark")), keep)
      out[sp] <- tidy[sp]
      say(sp, "extra spaces removed from labels")
    }
    ## a column of numbers in which every entry is now certainly a number
    ## becomes one; the values come from the parsed entries, so nothing that
    ## reads as a number is lost in the conversion
    if (a$role == "numbers") {
      after <- read_entries(out[keep])
      if (all(after$kind %in% c("number", "blank")) && !length(a$dot3_rows)) {
        num <- rep(NA_real_, length(out)); num[keep] <- after$value
        out <- num
        log <- c(log, sprintf("'%s' is now a column of numbers.", v))
      } else if (length(intersect(which(!is.na(a$new) | k == "mark"), keep)))
        log <- c(log, sprintf(paste0("'%s' still has entries that are not certain numbers, so it ",
          "stays as text until they are corrected (see 'Needs you to decide')."), v))
    }
    if (is.numeric(out)) d[[v]] <- out
    else if (!identical(out, a$raw)) {
      d[[v]] <- if (is.factor(x)) {
        ## keep the order the factor's levels had, under their new spellings
        old <- vapply(levels(x), function(l) { i <- match(l, a$raw); if (is.na(i)) NA_character_ else out[i] }, "")
        factor(out, levels = unique(c(stats::na.omit(old), unique(stats::na.omit(out)))))
      } else out
    }
  }
  if (length(empty)) {
    log <- c(log, sprintf("%s had no values and %s removed; the other rows keep their numbers.",
      sub("^r", "R", rows_text(ids[empty])), pl(length(empty), "has been", "have been")))
    d <- d[-empty, , drop = FALSE]
    ## a level used only in a removed row would linger in a factor otherwise
    d[] <- lapply(d, function(z) if (is.factor(z)) droplevels(z) else z)
  }
  list(data = d, log = log)
}

## The data check as HTML for the Data tab: green when nothing needs the
## user, otherwise the problems grouped as what can be corrected, what needs
## the user and what is for information.
check_html <- function(chk, d) {
  is_ <- chk$issues
  lv <- vapply(is_, `[[`, character(1), "level")
  cols <- function(x) join_and(sprintf("<b>%s</b>", esc(x)))
  head_ <- paste0(sprintf("%d %s and %d %s.", nrow(d), pl(nrow(d), "row", "rows"),
                          ncol(d), pl(ncol(d), "column", "columns")),
                  if (length(chk$numeric)) paste0(" Read as numbers: ", cols(chk$numeric), ".") else "",
                  if (length(chk$labels)) paste0(" Read as labels: ", cols(chk$labels), ".") else "")
  if (!length(is_))
    return(paste0("<div class='sugbox'><b>Data check: no problems found.</b> ", head_, "</div>"))
  block <- function(level, title)
    if (any(lv == level)) paste0("<p><b>", title, "</b></p><ul>",
      paste0("<li>", esc(vapply(is_[lv == level], `[[`, character(1), "message")), "</li>",
             collapse = ""), "</ul>") else ""
  paste0("<div class='", if (any(lv %in% c("correct", "check"))) "warn" else "sugbox", "'>",
         "<b>Data check.</b> ", head_,
         block("correct", "Can be corrected for you"),
         block("check", "Needs you to decide"),
         block("note", "For information"),
         "</div>")
}

## Whether double quotes in some lines of data are real quoting or inch marks
## (12" pot). Real quoting always leaves an even number of quotes on a line;
## an inch mark leaves an odd number, and reading it as a quote would swallow
## the rest of the line and the next ones. So quotes are honoured only when
## every line has an even number of them.
quote_char <- function(lines) {
  n <- lengths(regmatches(lines, gregexpr("\"", lines, fixed = TRUE)))
  if (any(n %% 2 == 1)) "" else "\""
}

## Turn a column of text into numbers only when nothing is lost: labels such
## as 1.1 and 1.10, or 01 and 1, must not become the same number. Anything
## else stays as text for the data check to look at.
convert_lossless <- function(col) {
  if (!is.character(col)) return(col)
  conv <- utils::type.convert(col, as.is = TRUE, na.strings = c("NA", ""))
  if (!is.numeric(conv)) return(conv)
  s <- trimws(col); ok <- !is.na(col) & s != ""
  ## only plain numbers are converted: type.convert also reads R's own
  ## literals (0x10 as 16, Inf, NaN), which stay text for the data check
  if (!all(grepl("^[-+]?([0-9]+[.]?[0-9]*|[.][0-9]+)([eE][-+]?[0-9]+)?$", s[ok]))) return(col)
  if (any(!is.finite(conv[ok]))) return(col)
  if (length(unique(s[ok])) > length(unique(conv[ok]))) col else conv
}

## Read an uploaded CSV. The separator is the one (comma, semicolon or tab)
## that splits every line into the same number of fields, at least two; a
## comma file with unquoted decimal commas, which would be cut apart wrongly,
## is refused with a reason. An inch mark (12" pot) that opens a quoted field
## and swallows lines is read again without quoting. Text that looks like
## numbers is converted only when nothing is lost, so the data check sees
## decimal commas and no-value markers as typed.
read_upload <- function(path) {
  counts <- function(s, q) tryCatch({
    n <- utils::count.fields(path, sep = s, quote = q, comment.char = "", blank.lines.skip = TRUE)
    n[!is.na(n)] }, error = function(e) integer(0))
  pick <- function(q) {
    fits <- vapply(c(",", ";", "\t"), function(s) {
      n <- counts(s, q); if (length(n) && all(n == n[1]) && n[1] > 1) n[1] else 0L }, integer(1))
    if (any(fits > 0)) c(",", ";", "\t")[which.max(fits)] else NA_character_
  }
  quote <- quote_char(readLines(path, warn = FALSE))
  sep <- pick(quote)
  if (is.na(sep)) {
    one <- vapply(c(",", ";", "\t"), function(s) { n <- counts(s, ""); length(n) > 0 && all(n == 1) }, logical(1))
    if (!all(one))
      stop(paste0("The lines of this file do not all have the same number of values. This usually ",
                  "means numbers with decimal commas in a comma-separated file. Save it from Excel as ",
                  "'CSV (semicolon delimited)', or copy the cells and use the paste box."), call. = FALSE)
    sep <- ";"
  }
  d <- utils::read.csv(path, sep = sep, stringsAsFactors = FALSE, check.names = FALSE,
                       na.strings = c("NA", ""), strip.white = TRUE, row.names = NULL,
                       quote = quote, comment.char = "", colClasses = "character")
  d[] <- lapply(d, convert_lossless)
  names(d) <- make.names(names(d), unique = TRUE)
  d
}

## Rows left out of an analysis and why: one record for each row and column
## that had no usable value. `raw` is the data as supplied, `d` the same rows
## after the response was read as numbers and no-value markers in the factors
## were emptied, `keep` the columns the analysis needs.
excluded_rows <- function(raw, d, keep) {
  miss <- is.na(as.matrix(d[, keep, drop = FALSE]))
  drop <- which(rowSums(miss) > 0)
  if (!length(drop)) return(NULL)
  idx <- which(miss[drop, , drop = FALSE], arr.ind = TRUE)
  r <- drop[idx[, 1]]; cols <- keep[idx[, 2]]
  vals <- vapply(seq_along(r), function(j) {
    z <- raw[[cols[j]]][r[j]]
    if (is.na(z) && !(is.numeric(z) && is.nan(z))) "" else trimws(as.character(z)) }, "")
  out <- data.frame(row = row_ids(raw)[r], column = cols, kind = read_entries(vals)$kind,
                    value = vals, stringsAsFactors = FALSE, row.names = NULL)
  out[order(out$row), , drop = FALSE]
}

## "3 rows were left out of this analysis: Yield is written with a decimal
## comma in rows 1 and 4 ('6,5' and '7,2'); Yield is empty in row 9." Grouped
## by column and reason so a long list reads as a few sentences. `html`
## escapes the user's entries; `hint` adds what to do in the app.
excluded_text <- function(ex, html = FALSE, hint = FALSE) {
  if (is.null(ex) || !nrow(ex)) return("")
  n <- length(unique(ex$row))
  grp <- split(ex, paste(ex$column, ex$kind))
  grp <- grp[order(vapply(grp, function(g) min(g$row), numeric(1)))]
  parts <- vapply(grp, function(g) {
    v <- g$column[1]; rr <- rows_text(unique(g$row)); eg <- eg_text(g$value)
    switch(g$kind[1],
      blank = sprintf("%s is empty in %s", v, rr),
      mark = sprintf("%s is marked as having no value in %s (%s)", v, rr, eg),
      comma = sprintf("%s is written with a decimal comma in %s (%s)", v, rr, eg),
      ambiguous = sprintf("%s could be read two ways in %s (%s)", v, rr, eg),
      percent = sprintf("%s has a %% sign in %s (%s)", v, rr, eg),
      unit = sprintf("%s has a unit after the number in %s (%s)", v, rr, eg),
      thousands = , european = sprintf("%s has a thousands separator in %s (%s)", v, rr, eg),
      sprintf("%s is not a number in %s (%s)", v, rr, eg))
  }, "")
  out <- sprintf("%d %s left out of this analysis: %s.", n, pl(n, "row was", "rows were"),
                 paste(parts, collapse = "; "))
  ## what to do in the app, only where something can be done: decimal commas
  ## and separators are corrected by the button; entries that are not numbers,
  ## doubtful ones and partial units or % signs need the user
  if (hint) {
    fixable <- any(ex$kind %in% c("comma", "thousands", "european"))
    manual <- any(ex$kind %in% c("text", "ambiguous", "percent", "unit"))
    if (fixable)
      out <- paste(out, "To include the rows with decimal commas or thousands separators, press 'Apply the corrections' on the Data tab.")
    if (manual)
      out <- paste(out, sprintf("To include %s, correct those entries in the table on the Data tab, where the data check lists them.",
                                if (fixable) "the others" else "these rows"))
    if (fixable || manual) out <- paste(out, "Then run the analysis again.")
  }
  if (html) esc(out) else out
}

