                  "Split plot" = "SPLIT", "Strip plot" = "STRIP",
                  "Pooled over environments (RCBD)" = "POOLRCBD",
                  "Pooled over environments (CRD)" = "POOLCRD",
                  "Pooled factorial over environments (RCBD)" = "POOLFACT",
