                   "set of random deviates. They are not observations from a real experiment.")

## ---------------------------------------------------------- first guesses --
## Names that usually mean a column's role in a design, for a first guess at
## the mapping of data that are not one of the examples; the user can change
## every choice. Column names are compared without case or punctuation.
DESIGN_KEYS <- c("rep", "reps", "replication", "replicate", "replicationno", "repno", "r",
                 "block", "blocks", "blockno", "blk", "b", "row", "rowno", "col", "column",
                 "colno", "columnno")
ROLE_HINTS <- list(
  block = c("block", "blocks", "blockno", "blk", "b", "rep", "reps", "replication", "replicate", "r"),
  rep   = c("rep", "reps", "replication", "replicate", "replicationno", "repno", "r", "block", "blocks", "blk"),
  row   = c("row", "rows", "rowno"),
  col   = c("col", "column", "columns", "colno", "columnno"),
  env   = c("location", "locations", "loc", "site", "sites", "env", "environment", "season", "seasons",
            "year", "years", "yr"),
  treat = c("treatment", "treatments", "trt", "treat", "variety", "varieties", "genotype", "genotypes", "cultivar"))

## The first guess at a column for each role of the design: a column named
## for the role when there is one, else the next column that is not a
## measurement; the response is the last column of numbers that is a
## measurement (many different values, not named like an identifier or a
## design column). `roles` are the role names the design needs, in order.
guess_map <- function(d, roles, num = NULL) {
  cn <- names(d)
  num <- intersect(num %||% cn[vapply(d, is.numeric, logical(1))], cn)
  key <- gsub("[^a-z]", "", tolower(cn))
  named <- key %in% unlist(ROLE_HINTS, use.names = FALSE) | is_id_name(cn)
  many <- vapply(cn, function(v) {
    k <- length(unique(stats::na.omit(response_values(d[[v]]))))
    k > max(2, nrow(d) / 4)
  }, logical(1))
  meas <- cn[cn %in% num & !named & many]
  resp <- if (length(meas)) utils::tail(meas, 1) else if (length(num)) utils::tail(num, 1) else utils::tail(cn, 1)
  free <- setdiff(cn, resp)
  out <- list(resp = resp)
  for (r in roles) {
    hint <- ROLE_HINTS[[if (startsWith(r, "f") || r %in% c("main", "sub")) "treat" else r]]
    k <- key[match(free, cn)]
    pick <- if (r %in% c("block", "rep", "row", "col", "env")) free[k %in% hint][1] else NA_character_
    if (is.na(pick)) {
      cand <- setdiff(free, meas)
      pick <- if (length(cand)) cand[1] else free[1]
    }
    if (is.na(pick)) pick <- cn[1]
    out[[r]] <- pick
    free <- setdiff(free, pick)
  }
  out
}

## the roles each design needs, in the order the mapping shows them
design_roles <- function(design, nf = 2) {
  fs <- paste0("f", seq_len(nf))
  switch(design,
    CRD = "treat", RCBD = c("block", "treat"), LSD = c("row", "col", "treat"),
    FCRD = fs, FRCBD = c("block", fs),
    SPLIT = , STRIP = c("rep", "main", "sub"),
    POOLRCBD = c("env", "rep", "treat"), POOLCRD = c("env", "treat"),
    POOLFRCBD = c("env", "rep", fs), POOLFCRD = c("env", fs),
    character(0))
}

## what each role is called beside its selector
role_label <- function(role, design) {
  strip <- identical(design, "STRIP"); pooled <- startsWith(design, "POOL")
  if (grepl("^f[0-9]$", role)) return(paste(if (pooled) "Treatment factor" else "Factor", LETTERS[as.integer(substring(role, 2))]))
  switch(role,
    treat = "Treatment", block = "Block", row = "Row", col = "Column",
    rep = if (pooled) "Replication / block (within environment)" else "Replication",
    main = if (strip) "Factor A (horizontal strips)" else "Main-plot factor",
    sub = if (strip) "Factor B (vertical strips)" else "Sub-plot factor",
    env = "Environment (location / year / season)", role)
}

## a mapping of roles (resp, treat, block, f1, f2, ...) as analyze() takes it
roles_to_map <- function(vals) {
  m <- list(response = vals$resp)
  for (r in c("treat", "block", "row", "col", "rep", "main", "sub", "env"))
    if (!is.null(vals[[r]])) m[[r]] <- vals[[r]]
  fs <- unlist(vals[grep("^f[0-9]$", names(vals))])
  if (length(fs)) m$factors <- unname(fs)
  m
}

## the roles of a mapping as the selectors hold them (the inverse of roles_to_map)
map_to_roles <- function(map) {
  out <- list(resp = map$response)
  for (r in c("treat", "block", "row", "col", "rep", "main", "sub", "env"))
    if (!is.null(map[[r]])) out[[r]] <- map[[r]]
  for (i in seq_along(map$factors)) out[[paste0("f", i)]] <- map$factors[i]
  out
}

## ------------------------------------------------------------------ roles --
## What each column does in the analysis, in words, from the design and the
## column mapping. A column mapped to no role is not described as anything.
map_roles <- function(map, design = NULL) {
  if (is.null(map)) return(character(0))
  strip <- identical(design, "STRIP")
  in_env <- isTRUE(design %in% c("POOLRCBD", "POOLFRCBD"))
  lab <- c(response = "Response", treat = "Treatment factor", factors = "Treatment factor",
           block = "Block", rep = if (in_env) "Replication within environment" else "Replication",
           row = "Row (blocking)", col = "Column (blocking)", env = "Environment",
           main = if (strip) "Factor A (horizontal strips)" else "Main-plot factor",
           sub = if (strip) "Factor B (vertical strips)" else "Sub-plot factor")
  out <- character(0)
  for (k in intersect(names(lab), names(map))) {
    cols <- map[[k]]
    cols <- cols[!is.na(cols) & nzchar(cols)]
    out[cols] <- lab[[k]]
  }
  out
}

## ------------------------------------------------------------ quick summary --
## The numbers to look at before any analysis, for each response: how many
## values, how many missing, where they lie and how widely they spread. SE is
## the standard error of the mean of all the values together (SD / sqrt(n)),
## a measure of how precisely that one overall mean is known; it is not the
## SE(m) of a treatment mean, which comes from the analysis of variance. CV
## only where it means something: values that cannot be negative and a
## positive mean (describe_data() leaves it out otherwise).
quick_describe <- function(d, vars) {
  vars <- intersect(vars, names(d))
  if (!length(vars)) return(NULL)
  tab <- describe_data(d, vars)
  data.frame(Response = tab$Variable, n = tab$N, Missing = tab$Missing,
             Mean = tab$Mean, SD = tab$SD,
             SE = ifelse(tab$N >= 2, tab$SD / sqrt(tab$N), NA_real_),
             Median = tab$Median, Q1 = tab$Q1, Q3 = tab$Q3, Min = tab$Min, Max = tab$Max,
             CV = tab$CV, check.names = FALSE, stringsAsFactors = FALSE)
}

## the quick summary as a table, each response's figures to the decimals its
## values support (as the Exploration tab prints them)
quick_describe_html <- function(tab, d) {
  if (is.null(tab) || !nrow(tab)) return("")
  num <- c("Mean", "SD", "SE", "Median", "Q1", "Q3", "Min", "Max")
  body <- lapply(seq_len(nrow(tab)), function(i) {
    dg <- var_digits(response_values(d[[tab$Response[i]]]))
    c(esc(tab$Response[i]), as.character(tab$n[i]), as.character(tab$Missing[i]),
      vapply(num, function(k) dfmt(tab[[k]][i], if (k == "SE") dg + 1L else dg), ""),
      if (is.na(tab$CV[i])) "&ndash;" else fmt(tab$CV[i], 1))
  })
  head_ <- c("Response", "n", "Missing", "Mean", "SD", "SE of mean", "Median", "Q1", "Q3", "Min", "Max", "CV (%)")
  paste0(raw_table(head_, body, caption = "Quick descriptive statistics of the response variables", cls = "doe doe-quick"),
         "<div class='note'>n counts the values used and Missing the empty cells and entries that are not ",
         "plain numbers (missing values are never treated as zeros). SD is the standard deviation of the ",
         "values; SE of mean = SD / &radic;n is the precision of the overall mean of all of them, not the ",
         "standard error of a treatment mean, which the analysis of variance gives. Q1 and Q3 are the quartiles ",
         "(as Excel's QUARTILE.INC gives them). CV = 100 &times; SD / mean, shown only when no value is negative ",
         "and the mean is positive.</div>")
}

## -------------------------------------------------------- column structure --
## One row for every column of the data: the role it has in the analysis,
## how it is stored, what kind of variable it is, and how complete it is. The
## kind is not read from the storage alone: a column mapped as a treatment
## factor is categorical even when its labels are 1, 2, 3, and a column of
## whole numbers mapped to no role is reported as such rather than guessed to
## be a measurement.
data_structure <- function(d, map = NULL, design = NULL) {
  roles <- map_roles(map, design)
  n <- nrow(d)
  rows <- lapply(names(d), function(v) {
    x <- d[[v]]
    s <- trimws(as.character(x))
    miss <- is.na(x) | is.na(s) | s == "" | tolower(s) %in% MISSING_MARKS
    if (is.numeric(x)) miss <- miss | !is.finite(x)
    obs <- s[!miss]
    k <- length(unique(obs))
    storage <- if (is.factor(x)) "Factor" else if (is.integer(x)) "Integer" else if (is.numeric(x)) "Numeric"
               else if (is.logical(x)) "Logical" else if (inherits(x, "Date")) "Date"
               else if (is.character(x)) "Text" else class(x)[1]
    ent <- read_entries(x)
    nums <- ent$kind[!miss] %in% c("number", "comma", "thousands", "european")
    vals <- ent$value[!miss][nums]
    is_num <- length(obs) > 0 && mean(nums) >= 0.75
    whole <- is_num && length(vals) > 0 && all(abs(vals - round(vals)) < 1e-9)
    key <- gsub("[^a-z]", "", tolower(v))
    role <- if (v %in% names(roles)) roles[[v]]
            else if (key %in% DESIGN_KEYS) "Not used (named like a design column)"
            else if (is_id_name(v) || (k == length(obs) && length(obs) > 1 && !is_num) ||
                     (is_num && whole && k == length(obs) && length(obs) > 2 &&
                      all(diff(sort(vals)) == 1))) "Identifier (not used)"
            else "Not used"
    kind <- if (role == "Response") {
              if (!is_num) "Not numeric: cannot be analysed"
              else if (whole && all(vals >= 0)) "Integer / count" else "Continuous"
            } else if (v %in% names(roles)) "Categorical (design factor)"
            else if (startsWith(role, "Identifier")) "Identifier"
            else if (key %in% DESIGN_KEYS) "Categorical"
            else if (is_num && !whole) "Continuous"
            else if (is_num) "Integer (count or code)"
            else if (k <= max(1, length(obs) / 2)) "Categorical"
            else "Unclassified"
    bad <- if (is_num) sum(!nums) else 0L
    note <- c(if (bad) sprintf("%d %s not plain %s (see the data check)", bad,
                               pl(bad, "entry is", "entries are"), pl(bad, "number", "numbers")),
              if (role == "Response" && k <= 1 && length(obs)) "every value is the same",
              if (v %in% names(roles) && role != "Response" && k < 2) "only one level")
    data.frame(Variable = v, Role = role, Storage = storage, Type = kind, Total = n,
               Observed = length(obs), Missing = sum(miss), Missing_pct = if (n) 100 * sum(miss) / n else NA_real_,
               Distinct = k, Note = paste(note, collapse = "; "),
               check.names = FALSE, stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

data_structure_html <- function(tab) {
  if (is.null(tab) || !nrow(tab)) return("")
  body <- lapply(seq_len(nrow(tab)), function(i) c(
    esc(tab$Variable[i]), esc(tab$Role[i]), esc(tab$Storage[i]), esc(tab$Type[i]),
    as.character(tab$Total[i]), as.character(tab$Observed[i]), as.character(tab$Missing[i]),
    fmt(tab$Missing_pct[i], 1), as.character(tab$Distinct[i]), esc(tab$Note[i])))
  paste0(raw_table(c("Variable", "Assigned role", "Storage type", "Analytical type", "Total N", "Non-missing N",
                     "Missing N", "Missing (%)", "Distinct values", "Note"), body,
                   caption = "Data structure and quality: every column", cls = "doe doe-structure"),
         "<div class='note'>The role comes from the design and the columns chosen on the Data tab. The ",
         "analytical type follows the role, not the way the column is stored: a treatment coded 1, 2, 3 is ",
         "categorical. Missing counts empty cells and entries such as n/a or a dash; distinct values are ",
         "counted among the values present.</div>")
}

## -------------------------------------------------------------- screening --
## The screening of each response the analysis will use: the untransformed
## model for the chosen design, its residual checks and the adviser's
## suggestion. `fits` is a named list with, for each response, either the
## result of fit_base() or list(err = message).
screen_rows <- function(fits) {
  rows <- lapply(names(fits), function(v) {
    f <- fits[[v]]
    if (!is.null(f$err))
      return(data.frame(Response = v, Rows = NA_integer_, Normality = "", Variances = "", Slope = "",
                        BoxCox = "", CV = "", Suggestion = "", Note = f$err, ok = FALSE,
                        check.names = FALSE, stringsAsFactors = FALSE))
    a <- f$asm0; r <- f$base; al <- r$alpha
    verdict <- function(p) if (!is.finite(p)) "" else if (p < al) " &ndash; <b>departure</b>" else " &ndash; no departure shown"
    norm <- if (isTRUE(a$exact)) "not available: exact fit"
            else if (is.na(a$p_norm)) paste("not available:", esc(a$norm_why %||% "too few residuals"))
            else paste0("p = ", p_text(a$p_norm, al), verdict(a$p_norm))
    hov <- if (isTRUE(a$exact)) "not available: exact fit"
           else if (is.na(a$p_hov)) paste("not available:", esc(a$hov_why %||% "too few values"))
           else paste0(esc(a$hov_short), " p = ", p_text(a$p_hov, al), verdict(a$p_hov))
    slope <- if (is.na(a$slope)) "&ndash;"
             else paste0("b = ", fmt(a$slope, 2),
                         if (is.na(a$slope_p)) " (cannot be tested)" else paste0(" (p = ", p_text(a$slope_p, al), ")"))
    bc <- if (is.null(a$bc)) "&ndash;"
          else if (abs(a$lambda) >= 2 - 1e-9) sprintf("beyond %s", fmt(a$lambda, 2))
          else sprintf("%s (%s%% CI %s to %s)", fmt(a$lambda, 2), pct(a$bc$level), fmt(a$bc$ci[1], 2), fmt(a$bc$ci[2], 2))
    cv <- if (length(r$cv) == 1) fmt(r$cv, 2)
          else paste(sprintf("%s %s", sub(" [(]%[)]$", "", names(r$cv)), fmt(r$cv, 2)), collapse = "; ")
    sug <- paste0(TRANS[[f$sug$method]]$lab, if (isTRUE(f$sug$optional)) " (optional)" else "")
    data.frame(Response = v, Rows = nrow(r$data), Normality = norm, Variances = hov, Slope = slope,
               BoxCox = bc, CV = cv, Suggestion = sug, Note = f$sug$why, ok = TRUE,
               check.names = FALSE, stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

screening_html <- function(rows, alpha) {
  if (is.null(rows) || !nrow(rows)) return("")
  good <- rows[rows$ok, , drop = FALSE]; bad <- rows[!rows$ok, , drop = FALSE]
  tab <- if (nrow(good)) raw_table(
    c("Response", "Rows analysed", "Normality of residuals (Shapiro-Wilk)", "Equal variances",
      "Mean-variance slope", "Box-Cox &lambda;", "CV (%)", "Suggested transformation"),
    lapply(seq_len(nrow(good)), function(i) c(esc(good$Response[i]), as.character(good$Rows[i]),
      good$Normality[i], good$Variances[i], good$Slope[i], good$BoxCox[i], good$CV[i], esc(good$Suggestion[i]))),
    caption = "Quick screening of the selected responses", cls = "doe doe-screen") else ""
  why <- if (nrow(good)) paste0("<ul class='slx-why'>", paste0("<li><b>", esc(good$Response), ":</b> ",
                                                                esc(good$Note), "</li>", collapse = ""), "</ul>") else ""
  errs <- if (nrow(bad)) paste0("<div class='warn'><b>Not screened.</b><ul>", paste0("<li><b>", esc(bad$Response),
                                ":</b> ", esc(bad$Note), "</li>", collapse = ""), "</ul></div>") else ""
  paste0(tab, why, errs,
         "<div class='note'>A first look, from the model for the design chosen above and before any ",
         "transformation: the normality check uses the model's residuals, not the raw values, and the ",
         "equal-variance check compares the treatment groups (on the residuals when the design has blocks). ",
         sprintf("Each verdict is at the %s%% level. ", pct(alpha)),
         "The Assumptions tab gives the full checks with their plots, and the choice of transformation.</div>")
}

## ---------------------------------------------------------- analyze.R ----
###############################################################################
##  MAIN ANALYSIS ENGINE
###############################################################################
#' Analyse one response from a designed experiment
#'
#' Fits the analysis of variance for a single response variable and returns the
#' means, standard errors and critical differences for every legitimate
#' comparison the design allows.
#'
#' The error term is chosen to match the design. A split plot is fitted with
#' \code{Error(rep/main)} and a strip plot with \code{Error(rep/(A+B))}, so the
#' main-plot and sub-plot comparisons are each tested against their own error;
#' the two mixed comparisons use a weighted \emph{t}. In a pooled (combined)
#' analysis over environments, each treatment effect is tested against its own
#' interaction with the environment, and each environment by treatment
#' interaction against the pooled error.
#'
#' Unequal replication is handled exactly in the designs with a single error
#' term (CRD, RCBD, Latin square and the factorials): each mean gets its own
#' standard error and each pair of means its own standard error of a difference
#' and critical difference. When blocks are incomplete or factorial cells are
#' unequal, the means are adjusted (least-squares) means and every term is
#' tested adjusted for all the others (Type III). Designs with several error
#' strata (split plot, strip plot and the pooled analyses) can only be analysed
#' exactly when they are complete; with a plot missing \code{analyze()} stops
#' and says which combinations are missing.
#'
#' @param d A data frame in long format: one row per plot, with columns for the
#'   design factors and the response. Text factor columns are put in natural
#'   order (D0, D60, D120; T1, T2, ..., T10), with a label carrying no number,
#'   such as Control, placed first; a column that is already a factor keeps its
#'   levels, so supply a factor to fix an order such as Vegetative, Flowering,
#'   Maturity.
#' @param design The design code. One of the values of \code{\link{DESIGNS}},
#'   for example \code{"RCBD"}, \code{"SPLIT"} or \code{"POOLFRCBD"}.
#' @param map A named list mapping roles to column names of \code{d}. Always
#'   needs \code{response}. Then, by design: \code{treat} (CRD, RCBD, LSD);
#'   \code{block} (RCBD, factorial RCBD); \code{row}, \code{col} (LSD);
#'   \code{factors}, a character vector of two to four column names (factorial);
#'   \code{rep}, \code{main}, \code{sub} (split and strip plots); \code{env}
#'   together with \code{treat} or \code{factors}, and \code{rep} for an RCBD
#'   base (pooled designs).
#' @param alpha The significance level. It sets the critical differences, the
#'   grouping letters and the significance of every F-test. Defaults to 0.05.
#'
#' @return A list with, among others:
#'   \describe{
#'     \item{\code{anova}}{The analysis of variance table.}
#'     \item{\code{effects}}{One entry per effect. Each holds \code{means}, the
#'       table of means with columns \code{Mean}, \code{N}, \code{SD}, \code{SE}
#'       (the standard error of that mean), the grouping letters and, when the
#'       means are adjusted, \code{Raw_mean}; \code{sed_mat} and \code{cd_mat},
#'       the standard error of the difference and the critical difference for
#'       every pair of means; \code{sem}, \code{sed} and \code{cd}, single
#'       values that are \code{NA} when replication is unequal and they differ
#'       from mean to mean (\code{equal_rep} is then \code{FALSE}, and
#'       \code{se_range}, \code{sed_range} and \code{cd_range} give the range);
#'       \code{mse} and \code{df}, the error mean square and degrees of freedom
#'       the effect is tested against; \code{p}, \code{F} and \code{alpha}. The
#'       interaction of a split plot, strip plot or pooled analysis also has
#'       \code{slice}, the factor within whose levels its means are compared:
#'       its \code{SE}, \code{sed} and \code{cd} apply to those comparisons,
#'       \code{sed_mat} and \code{cd_mat} are \code{NA} across levels of
#'       \code{slice}, and \code{extra} gives the standard errors and critical
#'       differences of the other comparisons.}
#'     \item{\code{mse}, \code{dfe}}{The error mean square and its degrees of
#'       freedom.}
#'     \item{\code{balanced}}{Whether every cell of the design holds the same
#'       number of observations.}
#'     \item{\code{cv}, \code{grand}, \code{resid}, \code{lm}}{The coefficient of
#'       variation, grand mean, residuals and the fitted linear model.}
#'   }
#'
#' @seealso \code{\link{run_all}} to analyse several responses at once, and
#'   \code{\link{build_report}} to render the result.
#'
#' @examples
#' d <- demo_data("RCBD")
#' res <- analyze(d, "RCBD", list(response = "Yield", treat = "Variety",
#'                                block = "Block"))
#' res$anova
#' res$effects[["Variety"]]$means
#'
#' @export
analyze <- function(d, design, map, alpha = 0.05) {
  if (!is.numeric(alpha) || length(alpha) != 1L || is.na(alpha) ||
      alpha <= 0 || alpha >= 0.5)
    stop("The significance level must be a single number between 0 and 0.5, such as 0.05.")
  resp <- map$response
  raw <- d                                  # as supplied, for saying why rows were left out
  ## the response is read the way the data check reads it, so an entry the
  ## check calls "not a number" (0x10, 5,6, 45%) is left out here too, and a
  ## number typed with an unusual minus sign is still read
  d[[resp]] <- response_values(d[[resp]])
  ## Inf or NaN (a division by zero) is not a measurement: the row is left
  ## out, and excluded_rows() names the entry
  d[[resp]][!is.finite(d[[resp]])] <- NA

  facs <- switch(design,
    CRD = map$treat, RCBD = map$treat, LSD = map$treat,
    FCRD = map$factors, FRCBD = map$factors,
    SPLIT = c(map$main, map$sub), STRIP = c(map$main, map$sub),
    POOLRCBD = c(map$env, map$treat), POOLCRD = c(map$env, map$treat),
    POOLFRCBD = c(map$env, map$factors), POOLFCRD = c(map$env, map$factors))
  blks <- switch(design,
    CRD = character(0), RCBD = map$block, LSD = c(map$row, map$col),
    FCRD = character(0), FRCBD = map$block, SPLIT = map$rep, STRIP = map$rep,
    POOLRCBD = map$rep, POOLCRD = character(0),
    POOLFRCBD = map$rep, POOLFCRD = character(0))

  ## the tables of means add columns with these names, so a design factor
  ## called N (for nitrogen, say) would be overwritten by the counts
  clash <- intersect(c(facs, blks), RESERVED_COLS)
  if (length(clash))
    stop(sprintf(paste0("A column used as a design factor is called %s, a name DOEpro ",
      "uses in its tables of means. Please rename it (for example 'Nitrogen' rather ",
      "than 'N') and run the analysis again."), join_and(sprintf("'%s'", clash))),
      call. = FALSE)
  keep <- unique(c(resp, facs, blks))
  ## an empty label, or one such as "-" or "n/a" typed for no value, is a
  ## missing factor, not a treatment or block of its own
  for (v in c(facs, blks)) {
    s <- trimws(as.character(d[[v]]))
    gone <- is.na(s) | s == "" | tolower(s) %in% MISSING_MARKS
    ## emptied in place, so a factor keeps the level order it was given and a
    ## numeric column stays numeric
    if (any(gone)) { x <- d[[v]]; x[gone] <- NA; d[[v]] <- x }
  }
  ## rows without a usable response or factor are left out, and recorded with
  ## the reason, so the user is told rather than finding fewer plots
  excluded <- excluded_rows(raw, d, keep)
  d <- d[stats::complete.cases(d[, keep, drop = FALSE]), keep, drop = FALSE]
  why <- function() if (is.null(excluded)) "" else paste0(" ", excluded_text(excluded))
  if (nrow(d) < 3)
    stop(paste0(if (nrow(d) == 0) "No rows can be analysed." else
                  sprintf("Only %d %s can be analysed; at least 3 are needed.", nrow(d),
                          pl(nrow(d), "row", "rows")), why()), call. = FALSE)
  ## levels in natural order, so tables and plots run D0, D60, D120 and
  ## T1, T2, ..., T10 instead of alphabetically
  ## numeric codes in numeric order, labelled as written (100000, not 1e+05)
  for (v in c(facs, blks)) {
    x <- d[[v]]
    d[[v]] <- if (is.numeric(x)) { lab <- num_text(x); factor(lab, levels = unique(lab[order(x)])) }
              else factor(x, levels = natural_levels(x))
  }

  ## a layout refused because rows were left out says so first: correcting
  ## those entries may be all that is needed, before anything is deleted
  lay <- tryCatch(check_layout(d, design, map, facs, blks), error = function(e) {
    if (is.null(excluded)) stop(conditionMessage(e), call. = FALSE)
    stop(paste0(excluded_text(excluded), " With those rows left out, the layout is ",
                "incomplete. Correct those entries first if you can. ", conditionMessage(e)),
         call. = FALSE)
  })
  grand <- mean(d[[resp]])
  res <- list(design = design, resp = resp, data = d, facs = facs, blks = blks,
              alpha = alpha, grand = grand, balanced = lay$balanced,
              reps = lay$reps, n_range = lay$n_range, excluded = excluded)

  ## ------------------------------------------------- classic / factorial ----
  if (design %in% c("CRD", "RCBD", "LSD", "FCRD", "FRCBD")) {
    rhs <- paste(c(blks, paste(facs, collapse = "*")), collapse = " + ")
    form <- stats::as.formula(paste(resp, "~", rhs))
    fit <- stats::aov(form, data = d)
    an  <- tidy_aov(fit)
    mse <- an$MS[an$Source == "Residuals"]
    dfe <- an$Df[an$Source == "Residuals"]
    if (!length(dfe) || dfe < 1)
      stop(paste0("There are too few rows to estimate the experimental error: each treatment ",
                  "needs to appear more than once.", why()), call. = FALSE)
    lmfit <- stats::lm(form, data = d)
    if (!lay$balanced) an <- type3_anova(an, form, d, c(blks, facs))

    effs <- list()
    for (k in seq_along(facs)) {
      for (v in utils::combn(facs, k, simplify = FALSE)) {
        lab <- paste(v, collapse = ":")
        row <- an[an$Source == lab, ]
        effs[[lab]] <- new_effect(d, resp, v, mse, dfe,
                                  if (nrow(row)) row$p[1] else NA,
                                  if (nrow(row)) row$F[1] else NA, alpha,
                                  label = paste(v, collapse = " x "),
                                  fit = if (lay$balanced) NULL else lmfit)
      }
    }
    res$anova <- add_total(an, d[[resp]])
    ## with one treatment factor and no blocks there is nothing to adjust for:
    ## the means are the plain averages and the sums of squares still add up
    res$adjusted_ss <- !lay$balanced && length(c(blks, facs)) > 1
    res$mse <- mse; res$dfe <- dfe
    res$cv <- c("CV (%)" = 100 * sqrt(mse) / grand)
    res$effects <- effs
    res$lm <- lmfit
  }

  ## ----------------------------------------------------------- split plot ---
  if (design == "SPLIT") {
    A <- map$main; B <- map$sub; R <- map$rep
    a <- nlevels(d[[A]]); b <- nlevels(d[[B]]); r <- nlevels(d[[R]])
    f <- stats::as.formula(sprintf("%s ~ %s*%s + Error(%s/%s)", resp, A, B, R, A))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_a <- paste0("Error: ", R, ":", A)
    s_w <- st[grepl("Within", st)][1]
    if (!s_a %in% st) stop("Could not identify the main-plot error stratum.")
    Ea <- strat_res(tab, s_a); Eb <- strat_res(tab, s_w)
    if (is.na(Ea$ms) || is.na(Eb$ms) || Ea$df < 1 || Eb$df < 1)
      stop("Split-plot needs at least 2 replications and 2 levels of each factor.")

    get <- function(stratum, src) {
      x <- tab[tab$Stratum == stratum & tab$Source == src, ]
      if (!nrow(x)) return(data.frame(Df = NA, SS = NA, MS = NA, F = NA, p = NA))
      x[, c("Df", "SS", "MS", "F", "p")]
    }
    rep_row <- strat_res(tab, st[1])
    rA <- get(s_a, A); rB <- get(s_w, B); rAB <- get(s_w, paste0(A, ":", B))
    an <- rbind(
      data.frame(Source = "Replication", Df = rep_row$df, SS = rep_row$ss,
                 MS = rep_row$ms, F = NA, p = NA),
      data.frame(Source = A, rA),
      data.frame(Source = "Error (a)", Df = Ea$df, SS = Ea$ss, MS = Ea$ms, F = NA, p = NA),
      data.frame(Source = B, rB),
      data.frame(Source = paste(A, "x", B), rAB),
      data.frame(Source = "Error (b)", Df = Eb$df, SS = Eb$ss, MS = Eb$ms, F = NA, p = NA))
    names(an) <- c("Source", "Df", "SS", "MS", "F", "p")
    an <- add_total(an, d[[resp]])

    ta <- stats::qt(1 - alpha / 2, Ea$df); tb <- stats::qt(1 - alpha / 2, Eb$df)

    eA <- new_effect(d, resp, A, Ea$ms, Ea$df, rA$p, rA$F, alpha, label = A)
    eB <- new_effect(d, resp, B, Eb$ms, Eb$df, rB$p, rB$F, alpha, label = B)

    ## interaction: two different comparisons
    m <- eff_means(d, resp, c(A, B))
    sed_b <- sqrt(2 * Eb$ms / r)                                   # B within same A
    sed_a <- sqrt(2 * ((b - 1) * Eb$ms + Ea$ms) / (r * b))         # A at same B
    tw  <- t_weighted((b - 1) * Eb$ms, tb, Ea$ms, ta)
    cd_b <- tb * sed_b; cd_a <- tw * sed_a
    m$Letter_within_MP <- ave_letters(m, A, m$Mean, cd_b)
    m$Letter_within_SP <- ave_letters(m, B, m$Mean, cd_a)
    cdl <- cd_name(alpha)
    eAB <- slice_effect(m, c(A, B), slice = A, label = paste(A, "x", B),
      se = sqrt(Eb$ms / r), sed = sed_b, tcrit = tb, mse = Eb$ms, df = Eb$df,
      alpha = alpha, p = rAB$p, Fv = rAB$F,
      extra = stats::setNames(list(sed_b, cd_b, sed_a, cd_a), c(
        "SE(d): two sub-plot means at the same main plot",
        paste0(cdl, ": two sub-plot means at the same main plot"),
        "SE(d): two main-plot means at the same sub plot",
        paste0(cdl, ": two main-plot means at the same sub plot"))),
      extra_p = c(NA, rAB$p, NA, rAB$p),
      ## the C.D.s and letters only when the interaction's F-test allows them
      notes = if (isTRUE(rAB$p < alpha)) paste0("Letters 'within MP' compare sub-plot means inside one main plot (",
        cdl, " = ", fmt(cd_b), "). Letters 'within SP' compare main-plot means at one ",
        "sub-plot level (", cdl, " = ", fmt(cd_a), ", weighted t = ", fmt(tw, 2), ").") else "")

    res$anova <- an
    res$mse <- Eb$ms; res$dfe <- Eb$df
    res$cv <- c("CV(a) (%)" = 100 * sqrt(Ea$ms) / grand,
                "CV(b) (%)" = 100 * sqrt(Eb$ms) / grand)
    res$effects <- stats::setNames(list(eA, eB, eAB), c(A, B, paste0(A, ":", B)))
    res$lm <- stats::lm(stats::as.formula(
      sprintf("%s ~ %s + %s*%s + %s:%s", resp, R, A, B, R, A)), data = d)
    res$errors <- list(`Error (a)` = Ea, `Error (b)` = Eb)
  }

  ## ----------------------------------------------------------- strip plot ---
  if (design == "STRIP") {
    A <- map$main; B <- map$sub; R <- map$rep
    a <- nlevels(d[[A]]); b <- nlevels(d[[B]]); r <- nlevels(d[[R]])
    f <- stats::as.formula(sprintf("%s ~ %s*%s + Error(%s/(%s+%s))", resp, A, B, R, A, B))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_a <- paste0("Error: ", R, ":", A)
    s_b <- paste0("Error: ", R, ":", B)
    s_w <- st[grepl("Within", st)][1]
    if (!all(c(s_a, s_b) %in% st)) stop("Could not identify the strip-plot error strata.")
    Ea <- strat_res(tab, s_a); Eb <- strat_res(tab, s_b); Ec <- strat_res(tab, s_w)
    if (any(is.na(c(Ea$ms, Eb$ms, Ec$ms))))
      stop("Strip plot needs >= 2 replications and >= 2 levels of each factor.")

    get <- function(stratum, src) {
      x <- tab[tab$Stratum == stratum & tab$Source == src, ]
      if (!nrow(x)) return(data.frame(Df = NA, SS = NA, MS = NA, F = NA, p = NA))
      x[, c("Df", "SS", "MS", "F", "p")]
    }
    rep_row <- strat_res(tab, st[1])
    rA <- get(s_a, A); rB <- get(s_b, B); rAB <- get(s_w, paste0(A, ":", B))
    an <- rbind(
      data.frame(Source = "Replication", Df = rep_row$df, SS = rep_row$ss,
                 MS = rep_row$ms, F = NA, p = NA),
      data.frame(Source = A, rA),
      data.frame(Source = "Error (a)", Df = Ea$df, SS = Ea$ss, MS = Ea$ms, F = NA, p = NA),
      data.frame(Source = B, rB),
      data.frame(Source = "Error (b)", Df = Eb$df, SS = Eb$ss, MS = Eb$ms, F = NA, p = NA),
      data.frame(Source = paste(A, "x", B), rAB),
      data.frame(Source = "Error (c)", Df = Ec$df, SS = Ec$ss, MS = Ec$ms, F = NA, p = NA))
    names(an) <- c("Source", "Df", "SS", "MS", "F", "p")
    an <- add_total(an, d[[resp]])

    ta <- stats::qt(1 - alpha / 2, Ea$df); tb <- stats::qt(1 - alpha / 2, Eb$df)
    tc <- stats::qt(1 - alpha / 2, Ec$df)

    eA <- new_effect(d, resp, A, Ea$ms, Ea$df, rA$p, rA$F, alpha, label = A)
    eB <- new_effect(d, resp, B, Eb$ms, Eb$df, rB$p, rB$F, alpha, label = B)

    m <- eff_means(d, resp, c(A, B))
    sed_a_at_b <- sqrt(2 * ((b - 1) * Ec$ms + Ea$ms) / (r * b))
    sed_b_at_a <- sqrt(2 * ((a - 1) * Ec$ms + Eb$ms) / (r * a))
    tw_a <- t_weighted((b - 1) * Ec$ms, tc, Ea$ms, ta)
    tw_b <- t_weighted((a - 1) * Ec$ms, tc, Eb$ms, tb)
    cd_a_at_b <- tw_a * sed_a_at_b; cd_b_at_a <- tw_b * sed_b_at_a
    m$Letter_within_A <- ave_letters(m, A, m$Mean, cd_b_at_a)
    m$Letter_within_B <- ave_letters(m, B, m$Mean, cd_a_at_b)
    ## B means at one level of A: their SE(d) mixes Error (b) and Error (c), so
    ## tests that need degrees of freedom use Satterthwaite's approximation
    w <- c((a - 1) * Ec$ms, Eb$ms); wdf <- c(Ec$df, Eb$df)
    df_s <- sum(w)^2 / sum(w^2 / wdf)
    cdl <- cd_name(alpha)
    eAB <- slice_effect(m, c(A, B), slice = A, label = paste(A, "x", B),
      se = sed_b_at_a / sqrt(2), sed = sed_b_at_a, tcrit = tw_b,
      mse = sum(w) / a, df = df_s, alpha = alpha, p = rAB$p, Fv = rAB$F,
      extra = stats::setNames(list(sed_a_at_b, cd_a_at_b, sed_b_at_a, cd_b_at_a), c(
        sprintf("SE(d): two %s means at the same level of %s", A, B),
        sprintf("%s: two %s means at the same level of %s", cdl, A, B),
        sprintf("SE(d): two %s means at the same level of %s", B, A),
        sprintf("%s: two %s means at the same level of %s", cdl, B, A))),
      extra_p = c(NA, rAB$p, NA, rAB$p),
      notes = if (isTRUE(rAB$p < alpha)) paste0("The strip-plot interaction uses a weighted t. Letters 'within ", A,
        "' compare ", B, " means at a fixed ", A, "; letters 'within ", B, "' compare ",
        A, " means at a fixed ", B, ".") else "",
      t_mix = list(w = w, df = wdf),
      error_desc = sprintf(paste0("Comparisons of %s means at the same level of %s ",
        "combine Error (b) and Error (c). The critical difference uses the weighted t ",
        "of Gomez &amp; Gomez; tests that need degrees of freedom use Satterthwaite's ",
        "approximation (%s df)."), B, A, fmt(df_s, 1)))

    res$anova <- an
    res$mse <- Ec$ms; res$dfe <- Ec$df
    res$cv <- c("CV(a) (%)" = 100 * sqrt(Ea$ms) / grand,
                "CV(b) (%)" = 100 * sqrt(Eb$ms) / grand,
                "CV(c) (%)" = 100 * sqrt(Ec$ms) / grand)
    res$effects <- stats::setNames(list(eA, eB, eAB), c(A, B, paste0(A, ":", B)))
    res$lm <- stats::lm(stats::as.formula(
      sprintf("%s ~ %s + %s*%s + %s:%s + %s:%s", resp, R, A, B, R, A, R, B)), data = d)
    res$errors <- list(`Error (a)` = Ea, `Error (b)` = Eb, `Error (c)` = Ec)
  }

  ## ----------------------------------------- pooled / combined over envs ----
  if (design %in% c("POOLRCBD", "POOLCRD")) {
    E <- map$env; Tf <- map$treat; R <- if (design == "POOLRCBD") map$rep else NULL
    e <- nlevels(d[[E]]); t <- nlevels(d[[Tf]])
    if (e < 2) stop("Pooled analysis needs at least two environments.")
    if (t < 2) stop("Pooled analysis needs at least two treatments.")
    r <- lay$reps                             # replications in every environment

    ## homogeneity of error variances across environments (Bartlett) -----------
    per_env <- lapply(levels(d[[E]]), function(lv) {
      di <- d[d[[E]] == lv, , drop = FALSE]
      form <- if (design == "POOLRCBD") sprintf("%s ~ %s + %s", resp, R, Tf)
              else sprintf("%s ~ %s", resp, Tf)
      a <- tryCatch(tidy_aov(stats::aov(stats::as.formula(form), data = droplevels(di))),
                    error = function(err) NULL)
      if (is.null(a)) return(c(df = NA, ss = NA))
      c(df = a$Df[a$Source == "Residuals"], ss = a$SS[a$Source == "Residuals"])
    })
    edf <- vapply(per_env, `[`, numeric(1), "df")
    ess <- vapply(per_env, `[`, numeric(1), "ss")
    hom <- bartlett_ms(edf, ess / edf)

    ## combined ANOVA via nested Error strata ---------------------------------
    f <- if (design == "POOLRCBD")
      stats::as.formula(sprintf("%s ~ %s*%s + Error(%s/%s)", resp, E, Tf, E, R))
    else stats::as.formula(sprintf("%s ~ %s*%s + Error(%s)", resp, E, Tf, E))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_top <- paste0("Error: ", E)
    s_w   <- st[grepl("Within", st)][1]

    get <- function(stratum, src) {
      x <- tab[tab$Stratum == stratum & tab$Source == src, ]
      if (!nrow(x)) return(data.frame(Df = NA, SS = NA, MS = NA, F = NA, p = NA))
      x[, c("Df", "SS", "MS", "F", "p")]
    }
    Erow <- get(s_top, E)                     # Environment (e-1)
    Trow <- get(s_w, Tf)                      # Treatment (t-1)
    ETrow <- get(s_w, paste0(E, ":", Tf))     # E x T
    Eerr <- strat_res(tab, s_w)               # pooled error

    if (design == "POOLRCBD") {
      s_re <- paste0("Error: ", E, ":", R)
      RE <- strat_res(tab, s_re)              # replications within environment
      err_for_env <- RE                       # E tested against R(E)
    } else {
      RE <- NULL
      err_for_env <- Eerr                     # CRD: E tested against pooled error
    }

    ## recompute the F-tests with the CORRECT error terms ---------------------
    fp <- function(ms, dfn, msE, dfd) {
      if (any(is.na(c(ms, msE))) || msE <= 0) return(c(F = NA, p = NA))
      Fv <- ms / msE
      c(F = Fv, p = stats::pf(Fv, dfn, dfd, lower.tail = FALSE))
    }
    Fe  <- fp(Erow$MS,  Erow$Df,  err_for_env$ms, err_for_env$df)
    Ft  <- fp(Trow$MS,  Trow$Df,  ETrow$MS,       ETrow$Df)
    Fet <- fp(ETrow$MS, ETrow$Df, Eerr$ms,        Eerr$df)
    Fre <- if (!is.null(RE)) fp(RE$ms, RE$df, Eerr$ms, Eerr$df) else c(F = NA, p = NA)

    ## ANOVA table ------------------------------------------------------------
    rows <- list(data.frame(Source = paste0("Environment (", E, ")"),
                            Df = Erow$Df, SS = Erow$SS, MS = Erow$MS,
                            F = Fe["F"], p = Fe["p"]))
    if (!is.null(RE))
      rows <- c(rows, list(data.frame(Source = "Replication within environment",
                            Df = RE$df, SS = RE$ss, MS = RE$ms, F = Fre["F"], p = Fre["p"])))
    rows <- c(rows,
      list(data.frame(Source = paste0("Treatment (", Tf, ")"),
                      Df = Trow$Df, SS = Trow$SS, MS = Trow$MS, F = Ft["F"], p = Ft["p"]),
           data.frame(Source = paste0(E, " x ", Tf),
                      Df = ETrow$Df, SS = ETrow$SS, MS = ETrow$MS, F = Fet["F"], p = Fet["p"]),
           data.frame(Source = "Pooled error", Df = Eerr$df, SS = Eerr$ss,
                      MS = Eerr$ms, F = NA, p = NA)))
    an <- do.call(rbind, lapply(rows, function(z) { names(z) <- c("Source","Df","SS","MS","F","p"); z }))
    an <- add_total(an, d[[resp]])
    rownames(an) <- NULL

    ## effects with the correct error term for each comparison ----------------
    eEnv <- new_effect(d, resp, E, err_for_env$ms, err_for_env$df, unname(Fe["p"]),
                       unname(Fe["F"]), alpha, label = paste0("Environment (", E, ")"))
    eT   <- new_effect(d, resp, Tf, ETrow$MS, ETrow$Df, unname(Ft["p"]), unname(Ft["F"]),
                       alpha, label = paste0("Treatment (", Tf, ") - over environments"))

    ## E x T cell means: compare treatments within an environment (pooled error)
    m <- eff_means(d, resp, c(E, Tf))
    t_we   <- stats::qt(1 - alpha / 2, Eerr$df)
    sed_we <- sqrt(2 * Eerr$ms / r)                    # two treatments, same environment
    sed_to <- sqrt(2 * ETrow$MS / (e * r))             # two treatment means over environments
    cd_we  <- t_we * sed_we
    m$Letter_within_env <- ave_letters(m, E, m$Mean, cd_we)
    cdl <- cd_name(alpha)
    eET <- slice_effect(m, c(E, Tf), slice = E, label = paste0(E, " x ", Tf),
      se = sqrt(Eerr$ms / r), sed = sed_we, tcrit = t_we, mse = Eerr$ms, df = Eerr$df,
      alpha = alpha, p = unname(Fet["p"]), Fv = unname(Fet["F"]),
      extra = stats::setNames(list(sed_we, cd_we, sed_to,
                                   stats::qt(1 - alpha / 2, ETrow$Df) * sed_to), c(
        "SE(d): two treatments in the same environment",
        paste0(cdl, ": two treatments in the same environment"),
        "SE(d): two treatment means over all environments",
        paste0(cdl, ": two treatment means over all environments"))),
      extra_p = c(NA, unname(Fet["p"]), NA, unname(Ft["p"])),
      notes = gxe_note(Fet["p"], alpha, E, Tf, cd_we, cdl),
      env = E, is_gxe = TRUE)

    an[["F"]] <- as.numeric(an[["F"]]); an[["p"]] <- as.numeric(an[["p"]])
    res$anova <- an
    res$mse <- Eerr$ms; res$dfe <- Eerr$df
    res$cv  <- c("CV (%)" = 100 * sqrt(Eerr$ms) / grand)
    res$effects <- stats::setNames(list(eEnv, eT, eET), c(E, Tf, paste0(E, ":", Tf)))
    lm_rhs <- if (design == "POOLRCBD") sprintf("%s + %s:%s + %s*%s", E, E, R, E, Tf)
              else sprintf("%s*%s", E, Tf)
    res$lm <- stats::lm(stats::as.formula(paste(resp, "~", lm_rhs)), data = d)
    res$errors <- list(`Pooled error` = Eerr,
                       `Rep within env` = if (!is.null(RE)) RE else NULL)
    res$homogeneity <- hom
    res$pooled <- TRUE
    res$env <- E
  }

  ## ------------------------------ factorial pooled / combined over envs ------
  if (design %in% c("POOLFRCBD", "POOLFCRD")) {
    E <- map$env; fs <- map$factors; R <- if (design == "POOLFRCBD") map$rep else NULL
    e <- nlevels(d[[E]]); k <- length(fs)
    if (e < 2) stop("Pooled analysis needs at least two environments.")
    if (k < 2) stop("Factorial pooled analysis needs at least two treatment factors.")
    r <- lay$reps                             # replications in every environment

    ## homogeneity of the per-environment error variances (Bartlett) ----------
    per_env <- lapply(levels(d[[E]]), function(lv) {
      di <- droplevels(d[d[[E]] == lv, , drop = FALSE])
      rhs <- paste(fs, collapse = "*")
      form <- if (design == "POOLFRCBD") sprintf("%s ~ %s + %s", resp, R, rhs)
              else sprintf("%s ~ %s", resp, rhs)
      a <- tryCatch(tidy_aov(stats::aov(stats::as.formula(form), data = di)),
                    error = function(err) NULL)
      if (is.null(a)) return(c(df = NA, ss = NA))
      c(df = a$Df[a$Source == "Residuals"], ss = a$SS[a$Source == "Residuals"])
    })
    edf <- vapply(per_env, `[`, numeric(1), "df")
    ess <- vapply(per_env, `[`, numeric(1), "ss")
    hom <- bartlett_ms(edf, ess / edf)

    ## combined ANOVA: E crossed with the full treatment factorial -------------
    trt_rhs <- paste(fs, collapse = "*")
    f <- if (design == "POOLFRCBD")
      stats::as.formula(sprintf("%s ~ %s*(%s) + Error(%s/%s)", resp, E, trt_rhs, E, R))
    else stats::as.formula(sprintf("%s ~ %s*(%s) + Error(%s)", resp, E, trt_rhs, E))
    fit <- stats::aov(f, data = d)
    tab <- tidy_aovlist(fit)
    st  <- unique(tab$Stratum)
    s_w   <- st[grepl("Within", st)][1]
    s_top <- paste0("Error: ", E)

    ## match a source row by the *set* of its factor components ----------------
    find_src <- function(comps) {
      rows <- tab[tab$Stratum == s_w & tab$Source != "Residuals", , drop = FALSE]
      cs <- sort(comps)
      for (i in seq_len(nrow(rows)))
        if (identical(sort(strsplit(rows$Source[i], ":")[[1]]), cs)) return(rows[i, ])
      NULL
    }
    err <- strat_res(tab, s_w)                       # pooled error

    Erow <- tab[tab$Stratum == s_top & tab$Source == E, , drop = FALSE]
    if (design == "POOLFRCBD") {
      RE <- strat_res(tab, paste0("Error: ", E, ":", R)); err_env <- RE
    } else { RE <- NULL; err_env <- err }

    fp <- function(ms, dfn, msE, dfd) {
      if (any(is.na(c(ms, msE))) || msE <= 0) return(c(F = NA, p = NA))
      Fv <- ms / msE; c(F = Fv, p = stats::pf(Fv, dfn, dfd, lower.tail = FALSE))
    }
    Fe  <- fp(Erow$MS[1], Erow$Df[1], err_env$ms, err_env$df)
    Fre <- if (!is.null(RE)) fp(RE$ms, RE$df, err$ms, err$df) else c(F = NA, p = NA)

    ## every treatment effect (main effects + all interactions) ---------------
    subsets <- unlist(lapply(1:k, function(mm) utils::combn(fs, mm, simplify = FALSE)),
                      recursive = FALSE)
    trt_block <- list(); ext_block <- list(); effects <- list()
    ms_et <- c(); df_et <- c(); p_et <- c(); inter <- list()
    for (S in subsets) {
      Trow  <- find_src(S)
      ETrow <- find_src(c(E, S))
      if (is.null(Trow) || is.null(ETrow)) next
      Ft  <- fp(Trow$MS,  Trow$Df,  ETrow$MS, ETrow$Df)     # treatment vs E x treatment
      Fet <- fp(ETrow$MS, ETrow$Df, err$ms,   err$df)       # E x treatment vs pooled error
      lbl <- paste(S, collapse = " x ")
      trt_block[[length(trt_block) + 1]] <- data.frame(
        Source = lbl, Df = Trow$Df, SS = Trow$SS, MS = Trow$MS, F = Ft["F"], p = Ft["p"])
      ext_block[[length(ext_block) + 1]] <- data.frame(
        Source = paste0(E, " x ", lbl), Df = ETrow$Df, SS = ETrow$SS, MS = ETrow$MS,
        F = Fet["F"], p = Fet["p"])
      sk <- paste(S, collapse = ":")
      ms_et[sk] <- ETrow$MS; df_et[sk] <- ETrow$Df; p_et[paste0(E, " x ", lbl)] <- Fet["p"]
      if (length(S) == 1)
        effects[[sk]] <- new_effect(d, resp, S, ETrow$MS, ETrow$Df, unname(Ft["p"]),
                                    unname(Ft["F"]), alpha, label = lbl)
      else {
        inter[[sk]] <- list(S = S, p = unname(Ft["p"]), F = unname(Ft["F"]),
                                                  ms = ETrow$MS, df = ETrow$Df, lbl = lbl)
      }
    }
    ## an interaction's means need every E x V mean square, so they come after
    nlev <- vapply(fs, function(f) nlevels(d[[f]]), numeric(1))
    for (sk in names(inter)) {
      z <- inter[[sk]]
      effects[[sk]] <- pool_effect(d, resp, z$S, nlev, ms_et, df_et, e, r, alpha, z$p, z$F,
                                   z$lbl, z$ms, z$df)
    }
    effects <- effects[vapply(subsets, paste, "", collapse = ":")]
    effects <- effects[!vapply(effects, is.null, logical(1))]

    ## assemble the ANOVA table -----------------------------------------------
    anrows <- list(data.frame(Source = paste0("Environment (", E, ")"),
                              Df = Erow$Df[1], SS = Erow$SS[1], MS = Erow$MS[1],
                              F = Fe["F"], p = Fe["p"]))
    if (!is.null(RE))
      anrows <- c(anrows, list(data.frame(Source = "Replication within environment",
                              Df = RE$df, SS = RE$ss, MS = RE$ms, F = Fre["F"], p = Fre["p"])))
    anrows <- c(anrows, trt_block, ext_block,
                list(data.frame(Source = "Pooled error", Df = err$df, SS = err$ss,
                                MS = err$ms, F = NA, p = NA)))
    an <- do.call(rbind, lapply(anrows, function(z) {
      names(z) <- c("Source","Df","SS","MS","F","p"); z }))
    an <- add_total(an, d[[resp]])
    an[["F"]] <- as.numeric(an[["F"]]); an[["p"]] <- as.numeric(an[["p"]])
    rownames(an) <- NULL

    ## Environment effect, and the E x (full treatment) stability table --------
    eEnv <- new_effect(d, resp, E, err_env$ms, err_env$df, unname(Fe["p"]),
                       unname(Fe["F"]), alpha, label = paste0("Environment (", E, ")"))
    ETfull <- find_src(c(E, fs))
    Ffull <- if (!is.null(ETfull)) fp(ETfull$MS, ETfull$Df, err$ms, err$df) else c(F = NA, p = NA)
    m <- eff_means(d, resp, c(E, fs))
    t_we   <- stats::qt(1 - alpha / 2, err$df)
    sed_we <- sqrt(2 * err$ms / r)
    cd_we  <- t_we * sed_we
    m$Letter_within_env <- ave_letters(m, E, m$Mean, cd_we)
    eETfull <- slice_effect(m, c(E, fs), slice = E,
      label = paste0(E, " x ", paste(fs, collapse = " x ")),
      se = sqrt(err$ms / r), sed = sed_we, tcrit = t_we, mse = err$ms, df = err$df,
      alpha = alpha, p = unname(Ffull["p"]), Fv = unname(Ffull["F"]), extra = NULL,
      notes = gxe_note(Ffull["p"], alpha, E, "treatment", cd_we, cd_name(alpha), factorial = TRUE,
                       lower = p_et[setdiff(names(p_et), paste0(E, " x ", paste(fs, collapse = " x ")))],
                       fs = fs),
      env = E, is_gxe = TRUE)

    res$effects <- c(effects, stats::setNames(list(eEnv), E),
                     stats::setNames(list(eETfull), paste0(E, ":", paste(fs, collapse = ":"))))
    res$anova <- an
    res$mse <- err$ms; res$dfe <- err$df
    res$cv  <- c("CV (%)" = 100 * sqrt(err$ms) / grand)
    res$facs <- fs                                   # means section loops treatment factors
    lm_rhs <- if (design == "POOLFRCBD")
      sprintf("%s + %s:%s + %s*(%s)", E, E, R, E, trt_rhs) else sprintf("%s*(%s)", E, trt_rhs)
    res$lm <- stats::lm(stats::as.formula(paste(resp, "~", lm_rhs)), data = d)
    res$errors <- list(`Pooled error` = err,
                       `Rep within env` = if (!is.null(RE)) RE else NULL)
    res$homogeneity <- hom
    res$pooled <- TRUE
    res$env <- E
  }
  res$resid  <- stats::residuals(res$lm)
  res$fitted <- stats::fitted(res$lm)
  res$X      <- stats::model.matrix(res$lm)   # for the Box-Cox profile
  res
}

## "C.D. (5%)", at whatever level was chosen
cd_name <- function(alpha) sprintf("C.D. (%s%%)", pct(alpha))

## The note under a pooled analysis's environment x treatment table. A
## non-significant interaction is reported as insufficient evidence, not as
## proof that the treatments behave alike everywhere. In a factorial the table
## tests the environment's interaction with the full treatment combination;
## its interactions with single factors and smaller combinations are rows of
## the ANOVA of their own (`lower`, their p-values named by row), and one that
## is significant is named, so the note never says the pooled means summarise
## treatment differences that the ANOVA finds changing between environments.
gxe_note <- function(p, alpha, E, what, cd, cdl, factorial = FALSE, lower = NULL, fs = NULL) {
  full <- if (factorial && length(fs)) paste(fs, collapse = " x ") else what
  if (!is.na(p) && p < alpha)
    return(paste0("The ", E, " x ", full, " interaction is significant at the ", pct(alpha),
      "% level: ", if (factorial) "the treatment combinations are" else "treatment performance is",
      " shown separately for each environment below. ",
      "Letters compare means within one environment only (pooled error, ", cdl, " = ",
      fmt(cd), ")."))
  if (!factorial)
    return(paste0("The ", E, " x ", what, " interaction is <b>not significant</b> at the ",
      pct(alpha), "% level (NS). There is insufficient evidence that the differences ",
      "between treatments change from one environment to another, so the pooled tables ",
      "above summarise them and the individual environment cells are not compared."))
  low <- lower[!is.na(lower) & lower < alpha]
  terms <- sub(paste0("^", E, " x "), "", names(low))
  diffs <- ifelse(grepl(" x ", terms, fixed = TRUE), paste("the", terms, "interaction"),
                  paste("the", terms, "differences"))
  paste0("The ", E, " x ", full, " interaction is <b>not significant</b> at the ",
    pct(alpha), "% level (NS): there is insufficient evidence that the ", full,
    " interaction changes from one environment to another, so the individual environment ",
    "cells are not compared.",
    if (length(low))
      paste0(" ", join_and(names(low)), if (length(low) == 1) " is" else " are",
        " significant at the ", pct(alpha), "% level, however: there is evidence that ",
        join_and(diffs), if (length(low) == 1 && grepl(" x ", terms, fixed = TRUE)) " changes" else " change",
        " from one environment to another, so the pooled means of ",
        join_and(unique(unlist(strsplit(terms, " x ", fixed = TRUE)))),
        " average over environments that behave differently.")
    else paste0(" Nor is any interaction of ", E, " with a single factor or a smaller ",
                "combination significant, so the pooled tables above summarise the ",
                "treatment differences."))
}

## columns the tables of means add, which a design factor must not be called
RESERVED_COLS <- c("Mean", "N", "SD", "SE", "Raw_mean", "Mean_bt", ".se",
                   "Letter", "Letter_within_MP", "Letter_within_SP",
                   "Letter_within_A", "Letter_within_B", "Letter_within_env")

## Is the layout one DOEpro can analyse exactly, and is it balanced? Designs
## with a single error term (CRD, RCBD, Latin square, the factorials) cope with
## unequal replication through adjusted means, as long as every treatment
## combination was observed. Designs with several error strata (split plot,
## strip plot, the pooled analyses) do not: with a plot missing the strata are
## no longer orthogonal, aov() moves treatment sums of squares into the
## replication strata where they silently vanish, and an exact analysis needs a
## mixed model fitted by REML, which base R does not provide. Those designs
## must be complete; the message says what is missing instead of printing a
## wrong ANOVA.
check_layout <- function(d, design, map, facs, blks) {
  pooled <- design %in% c("POOLRCBD", "POOLCRD", "POOLFRCBD", "POOLFCRD")
  trt <- if (pooled) setdiff(facs, map$env) else facs
  one <- c(facs, blks)[vapply(c(facs, blks), function(v) nlevels(d[[v]]) < 2, logical(1))]
  if (length(one))
    stop(sprintf(paste0("%s %s only one level in the complete rows of data, so there is ",
      "nothing to compare. Check that the right column is mapped, and that the response ",
      "is not missing for every other level."), join_and(sprintf("'%s'", one)),
      if (length(one) == 1) "has" else "have"), call. = FALSE)
  cells <- table(d[trt])
  if (length(trt) > 1 && any(cells == 0)) {
    empty <- as.data.frame(cells, stringsAsFactors = FALSE)
    empty <- empty[empty$Freq == 0, trt, drop = FALSE]
    stop(sprintf(paste0("Every combination of %s needs at least one observation, but ",
      "there are none for %s. Without them the main effects cannot be separated from ",
      "the interaction. Check the data, or leave out the factor with the gap."),
      join_and(trt), list_cells(empty)), call. = FALSE)
  }

  if (design %in% c("SPLIT", "STRIP")) {
    v <- c(map$rep, map$main, map$sub)
    tab <- as.data.frame(table(d[v]), stringsAsFactors = FALSE)
    miss <- tab[tab$Freq == 0, v, drop = FALSE]
    dup  <- tab[tab$Freq > 1, v, drop = FALSE]
    if (nrow(miss) || nrow(dup))
      stop(paste0(if (design == "SPLIT") "A split-plot" else "A strip-plot",
        " analysis needs exactly one observation for every combination of ",
        join_and(v), ". ",
        if (nrow(miss)) sprintf("Missing: %s. ", list_cells(miss)) else "",
        if (nrow(dup)) sprintf("More than one row: %s. ", list_cells(dup)) else "",
        "With a plot missing or repeated, the design's separate error terms can no ",
        "longer be estimated exactly, and DOEpro does not estimate missing plots. ",
        "Remove the incomplete replication and analyse the complete ones",
        if (nrow(dup)) ", and average repeated measurements of one plot into a single value" else "",
        "."), call. = FALSE)
    return(list(balanced = TRUE, reps = nlevels(d[[map$rep]]),
                n_range = rep(nlevels(d[[map$rep]]), 2)))
  }

  if (design %in% c("POOLRCBD", "POOLFRCBD")) {
    E <- map$env; R <- map$rep
    probs <- character(0); nrep <- integer(0)
    for (lv in levels(d[[E]])) {
      di <- d[d[[E]] == lv, , drop = FALSE]
      di[[R]] <- droplevels(di[[R]])
      tab <- as.data.frame(table(di[c(R, trt)]), stringsAsFactors = FALSE)
      miss <- tab[tab$Freq == 0, c(R, trt), drop = FALSE]
      dup  <- tab[tab$Freq > 1, c(R, trt), drop = FALSE]
      if (nrow(miss)) probs <- c(probs, sprintf("in %s, %s %s missing", lv, list_cells(miss),
                                                if (nrow(miss) == 1) "is" else "are"))
      if (nrow(dup)) probs <- c(probs, sprintf("in %s, %s %s more than one row", lv,
                                               list_cells(dup), if (nrow(dup) == 1) "has" else "have"))
      nrep[[lv]] <- nlevels(di[[R]])
    }
    if (length(unique(nrep)) > 1)
      probs <- c(probs, paste("the number of replications differs between environments (",
        paste(sprintf("%s %d", names(nrep), nrep), collapse = ", "), ")", sep = ""))
    if (length(probs))
      stop(paste0("A combined analysis over environments needs a complete RCBD in every ",
        "environment, with the same number of replications in each. Here ",
        paste(head_more(probs, 3), collapse = "; "), ". With incomplete or unequal replication the ",
        "treatments cannot be tested exactly against their interaction with the ",
        "environment, so DOEpro stops rather than print approximate results. Remove ",
        "the incomplete replication(s), or analyse each environment on its own as an ",
        "RCBD, which does handle a missing plot."), call. = FALSE)
    if (nrep[[1]] < 2)
      stop(paste0("A combined analysis needs at least two replications in every environment, to ",
        "estimate the pooled error; here each environment has one. With one replication, analyse the ",
        "data as ", if (design == "POOLFRCBD") "a factorial RCBD" else "an RCBD",
        " with the environment as the block: the treatments are then tested against their interaction ",
        "with the environment, as the combined analysis would test them."), call. = FALSE)
    return(list(balanced = TRUE, reps = nrep[[1]], n_range = rep(nrep[[1]], 2)))
  }

  if (design %in% c("POOLCRD", "POOLFCRD")) {
    v <- c(map$env, trt)
    tab <- as.data.frame(table(d[v]), stringsAsFactors = FALSE)
    if (length(unique(tab$Freq)) > 1) {
      common <- as.integer(names(which.max(table(tab$Freq))))
      odd <- tab[tab$Freq != common, , drop = FALSE]
      lab <- sprintf("%s has %s", do.call(paste, c(lapply(odd[v], as.character), sep = " x ")),
                     ifelse(odd$Freq == 0, "none", as.character(odd$Freq)))
      stop(sprintf(paste0("A combined analysis over environments needs the same number of ",
        "observations in every environment x treatment cell. Most cells have %d, but %s. ",
        "With unequal numbers the treatments cannot be tested exactly against their ",
        "interaction with the environment, so DOEpro stops rather than print approximate ",
        "results. Analyse each environment on its own as a CRD, which does handle unequal ",
        "replication."), common, join_and(head_more(lab))), call. = FALSE)
    }
    if (tab$Freq[1] < 2)
      stop(paste0("A combined analysis needs at least two observations in every environment x treatment ",
        "cell, to estimate the pooled error; here each cell has one. With one value for each treatment in ",
        "each environment (environment means, for instance), analyse the data as ",
        if (design == "POOLFCRD") "a factorial RCBD" else "an RCBD",
        " with the environment as the block: the treatments are then tested against their interaction ",
        "with the environment, as the combined analysis would test them."), call. = FALSE)
    return(list(balanced = TRUE, reps = tab$Freq[1], n_range = rep(tab$Freq[1], 2)))
  }

  ## single error term: balanced when every cell of the full layout, blocks
  ## included, holds the same number of plots. An RCBD whose treatments are each
  ## present three times but in different blocks is not balanced: its plain
  ## means are pulled by the block effects.
  full <- if (design == "LSD")
    list(table(d[c(map$row, map$col)]), table(d[c(map$row, trt)]), table(d[c(map$col, trt)]))
  else list(table(d[c(blks, trt)]))
  balanced <- all(vapply(full, function(x) all(x == x[1]) && x[1] > 0, logical(1)))
  if (design == "LSD") balanced <- balanced && all(full[[1]] == 1L)
  list(balanced = balanced, reps = if (balanced) as.vector(cells)[1] else NA,
       n_range = range(cells))
}

## "R2 x I2 x V3, R3 x I1 x V2 and 4 more", from rows of factor levels
list_cells <- function(cells)
  join_and(head_more(do.call(paste, c(lapply(cells, as.character), sep = " x "))))

## at most five items, then "and N more"
head_more <- function(x, k = 5)
  if (length(x) > k) c(x[seq_len(k)], sprintf("%d more", length(x) - k)) else x

## "a", "a and b", "a, b and c"
join_and <- function(x)
  if (length(x) < 2) x else paste(paste(x[-length(x)], collapse = ", "), "and", x[length(x)])

## A Total row that is the total sum of squares of the data, not the sum of the
## rows above it, so that nothing an error stratum dropped can go unnoticed.
add_total <- function(an, y) {
  rbind(an, data.frame(Source = "Total", Df = length(y) - 1, SS = sum((y - mean(y))^2),
                       MS = NA, F = NA, p = NA, check.names = FALSE))
}

## With unequal replication the sequential (Type I) sums of squares depend on
## the order of the terms and test hypotheses about weighted means. Replace each
## term's row with its Type III test: the term dropped from the full model fitted
## with sum-to-zero contrasts. That tests equality of the adjusted means the
## tables report, so the F-test that gates the letters and the means it gates
## are about the same thing. The rows then no longer add up to the total.
type3_anova <- function(an, form, d, fvars) {
  ctr <- stats::setNames(rep(list("contr.sum"), length(fvars)), fvars)
  fit <- stats::lm(form, data = d, contrasts = ctr)
  tl <- attr(stats::terms(fit), "term.labels")
  dr <- stats::drop1(fit, scope = tl, test = "F")
  for (x in tl) {
    i <- an$Source == x
    if (!any(i)) next
    an$SS[i] <- dr[x, "Sum of Sq"]
    an$MS[i] <- dr[x, "Sum of Sq"] / an$Df[i]
    an$F[i]  <- dr[x, "F value"]
    an$p[i]  <- dr[x, "Pr(>F)"]
  }
  an
}

## letters computed separately inside each level of `by`
ave_letters <- function(m, by, mu, cd) {
  out <- character(nrow(m))
  for (lv in unique(m[[by]])) {
    idx <- which(m[[by]] == lv)
    out[idx] <- cld_lsd(mu[idx], cd)
  }
  out
}

## every column that may carry compact-letter groupings
LETTER_COLS <- c("Letter", "Letter_within_MP", "Letter_within_SP",
                 "Letter_within_A", "Letter_within_B", "Letter_within_env")

## Protected mean separation. Returns the effect's table of means with the
## grouping letters blanked whenever the effect's F-test is not significant at
## the chosen level. This keeps the letters in step with the "C.D. = NS" in the
## footers: letters are shown only when the F-test justifies pairwise
## comparison, so an a-e sequence can never sit beneath a non-significant F.
gate_letters <- function(e) {
  m <- e$means
  if (!effect_sig(e))
    for (col in intersect(LETTER_COLS, names(m))) m[[col]] <- rep("", nrow(m))
  m
}

## is the effect significant at the chosen level (so its letters should be shown)?
effect_sig <- function(e) !is.na(e$p) && e$p < e$alpha

## does a table of means carry any non-empty grouping letter?
has_groups <- function(m) {
  cols <- intersect(LETTER_COLS, names(m))
  length(cols) > 0 && any(nzchar(unlist(m[cols])))
}

## ---------------------------------------------------------- assumptions.R ----
###############################################################################
##  ASSUMPTIONS  &  TRANSFORMATIONS
###############################################################################
## Levene's test, median-centred (Brown-Forsythe): a one-way ANOVA on the
## absolute deviations from the cell medians. In a cell with an odd number of
## values the median is one of them, so one deviation is always zero; when
## every cell has three values that caps F at 4, and the test could never find
## unequal variances among four or fewer treatments. When every cell used is
## of odd size, each therefore loses that one zero (Hines and O'Hara Hines,
## 2000, Biometrics 56: 451-454), which by simulation holds the 5% level for
## normal, skewed and count data with three or five values per cell. When
## sizes are mixed (a missing plot among cells of four) the zero stays:
## removing it from the odd cells alone makes them look more spread out than
## the even ones, and the test then calls equal variances unequal too often,
## while the plain test holds its level there. `zeros_removed` counts the
## cells that lost a zero.
## A cell needs three values to take part. With two, both values lie equally far from their median, so
## nothing varies within the cell: a design with two replications gave an
## enormous F and a false verdict of unequal variances, and keeping two-value
## cells beside larger ones (as car::leveneTest does) adds error degrees of
## freedom with no variation in them, which by simulation calls equal
## variances unequal 13-45% of the time at the 5% level. Such cells are left
## out and named in `left_out`; when fewer than two cells remain, or the
## deviations do not vary within any cell, the test is not run and `why`
## gives the reason as a plain clause.
levene_test <- function(y, g) {
  ok <- !is.na(y) & !is.na(g)
  y <- y[ok]; g <- droplevels(factor(g[ok]))
  n <- table(g)
  out <- list(F = NA_real_, p = NA_real_, df1 = NA_real_, df2 = NA_real_,
              cells = sum(n >= 3), dropped = sum(n < 3), left_out = names(n)[n < 3],
              zeros_removed = 0L, why = NULL)
  if (out$cells < 2) {
    out$why <- if (out$cells == 0) "no cell has three or more values" else "only one cell has three or more values"
    return(out)
  }
  keep <- g %in% names(n)[n >= 3]
  constant <- all(tapply(y, g, function(v) length(unique(v)) == 1))
  y <- y[keep]; g <- droplevels(g[keep])
  z <- abs(y - stats::ave(y, g, FUN = stats::median))
  if (all(table(g) %% 2 == 1)) {
    sz <- unlist(lapply(split(seq_along(z), g), function(i) i[which(z[i] == 0)[1]]), use.names = FALSE)
    z <- z[-sz]; g <- droplevels(g[-sz]); out$zeros_removed <- length(sz)
  }
  tss <- sum((z - mean(z))^2)
  rss <- sum((z - stats::ave(z, g))^2)
  if (tss == 0 || rss <= 1e-10 * tss) {
    out$why <- if (constant) "every cell's values are identical"
               else if (all(z == 0)) "the values are identical within every cell of three or more"
               else if (out$zeros_removed > 0)
                 "with the median's own zero set aside, the other deviations from the median are equal within every cell"
               else "the deviations from the cell medians do not vary within any cell"
    return(out)
  }
  df1 <- nlevels(g) - 1; df2 <- length(z) - nlevels(g)
  Fv <- ((tss - rss) / df1) / (rss / df2)
  out[c("F", "p", "df1", "df2")] <- list(Fv, stats::pf(Fv, df1, df2, lower.tail = FALSE), df1, df2)
  out
}

## Bartlett's test of equal variances across the cells. A cell needs two
## values for a variance, so cells of one value are left out; a variance of
## zero (every value in a cell the same) has no logarithm, so the test is not
## run and `why` says so.
bartlett_cells <- function(y, g) {
  ok <- !is.na(y) & !is.na(g)
  y <- y[ok]; g <- droplevels(factor(g[ok]))
  n <- table(g)
  out <- list(statistic = NA_real_, p.value = NA_real_, cells = sum(n >= 2),
              dropped = sum(n < 2), why = NULL)
  if (out$cells < 2) {
    out$why <- "fewer than two cells have two or more values"
    return(out)
  }
  keep <- g %in% names(n)[n >= 2]
  y <- y[keep]; g <- droplevels(g[keep])
  s2 <- tapply(y, g, stats::var)
  if (any(s2 == 0)) {
    out$why <- if (all(s2 == 0)) "every cell's values are identical"
               else "the values in some cells are all the same, so those cells have no variance"
    return(out)
  }
  b <- stats::bartlett.test(y, g)
  out$statistic <- unname(b$statistic); out$p.value <- b$p.value
  out
}

## An exact fit: every observation equals its fitted value, so the residuals
## are only the rounding left by the arithmetic. There is then no error
## variation to test, transform or plot, and treating the rounding as
## residuals would give verdicts about nothing. Residuals are judged against
## the spread of the values (within a billionth of it), with a floor for the
## rounding that the values' size leaves (1000 times the machine precision of
## the largest), as the regression judges them. Judging against the size
## alone called a response near 2e9 that scatters by 1 an exact fit.
exact_fit <- function(res) {
  y <- res$data[[res$resp]]
  size <- max(abs(y), na.rm = TRUE)
  spread <- max(abs(y - mean(y, na.rm = TRUE)), na.rm = TRUE)
  r <- res$resid
  !length(r) || !is.finite(size) || spread == 0 ||
    all(abs(r) <= max(1e-9 * spread, 1e3 * .Machine$double.eps * size), na.rm = TRUE)
}

## Box-Cox log-likelihood profile.  For a positive response y and design matrix X,
##   z(lambda) = (y^lambda - 1) / (lambda * gm^(lambda-1)),   z(0) = gm * log(y)
## with gm the geometric mean of y, and  l(lambda) = -n/2 * log(RSS(z)/n).
## Computed directly, so it never depends on re-evaluating a stored model call.
## The confidence interval is at `level`, which the analysis sets to 1 - alpha.
boxcox_profile <- function(y, X, level, lambda = seq(-2, 2, 0.02)) {
  if (any(!is.finite(y)) || any(y <= 0) || is.null(X)) return(NULL)
  n <- length(y); gm <- exp(mean(log(y))); qrx <- qr(X)
  ll <- vapply(lambda, function(l) {
    z <- if (abs(l) < 1e-9) gm * log(y) else (y^l - 1) / (l * gm^(l - 1))
    rss <- sum(qr.resid(qrx, z)^2)
    if (!is.finite(rss) || rss <= 0) return(NA_real_)
    -n / 2 * log(rss / n)
  }, numeric(1))
  if (all(is.na(ll))) return(NULL)
  best <- lambda[which.max(ll)]
  ## confidence interval: lambda values within qchisq(level, 1) / 2 of the
  ## maximum log-likelihood
  inside <- lambda[!is.na(ll) & ll > max(ll, na.rm = TRUE) - 0.5 * stats::qchisq(level, 1)]
  list(x = lambda, y = ll, lambda = best, ci = range(inside), level = level)
}

## The cells that should share one error variance: the treatment
## combinations, and in a pooled analysis the treatment combinations within
## each environment, so that a treatment-by-environment pattern in the means
## is not read as a difference in variance (a pooled factorial's res$facs
## leaves the environment out).
hov_cells <- function(res) interaction(res$data[unique(c(res$env, res$facs))], drop = TRUE)

## The values the equal-variance checks compare. In a design with blocks
## (rows and columns, replications) each value still carries its block's
## effect, which the error variance does not include: compared raw, the
## tests held only 0.1-1.5% at the 5% level and found a treatment with three
## times the spread 3% of the time (RCBD, 5 x 5, simulated). The residuals,
## recentred on their cell's mean, vary within a cell as the error does:
## Levene's held 2-5% and Bartlett's 1.5-4%, and they found that treatment
## 18% and 33% of the time. Without blocks these are the values themselves.
hov_values <- function(res, cells) {
  y <- res$data[[res$resp]]
  if (!length(res$blks)) return(y)
  res$resid + stats::ave(y, cells)
}

## The assumption tests are judged at the analysis's own significance level, so
## a user who chose 1% is not told about departures at 5%.
check_assumptions <- function(res) {
  alpha <- res$alpha
  r <- res$resid
  d <- res$data; resp <- res$resp
  cells <- hov_cells(res)
  yv <- hov_values(res, cells)
  exact <- exact_fit(res)

  ## With one error degree of freedom the residuals are one fixed pattern,
  ## set by the layout, scaled up or down: in a 2 x 2 RCBD Shapiro-Wilk gives
  ## p = 0.024 whatever the data, a verdict about the layout, not the errors.
  one_df <- isTRUE(res$dfe < 2)
  sw <- if (!exact && !one_df && length(r) >= 3 && length(r) <= 5000) stats::shapiro.test(r) else NULL
  norm_why <- if (exact) "the model fits every value exactly, so the residuals are all zero"
              else if (one_df) "with one error degree of freedom the residuals take the same pattern whatever the data, so their shape says nothing about normality"
              else if (is.null(sw)) "Shapiro-Wilk needs between 3 and 5000 residuals" else NULL
  lev  <- levene_test(yv, cells)
  bart <- bartlett_cells(yv, cells)
  if (exact) {
    why <- "the model fits every value exactly"
    lev[c("F", "p")] <- NA_real_; lev$why <- why
    bart[c("statistic", "p.value")] <- NA_real_; bart$why <- why
  }
  ## The equal-variance verdict comes from the test that covers every
  ## treatment: Levene's, which does not assume normality, when every cell has
  ## three or more values; otherwise Bartlett's, which needs only two but
  ## assumes normality; and Levene's on the cells it can use only when
  ## Bartlett's cannot be run. `hov_label` names the test as the text uses it.
  lev_full <- is.finite(lev$p) && lev$dropped == 0
  hov_test <- if (lev_full) "Levene" else if (is.finite(bart$p.value)) "Bartlett"
              else if (is.finite(lev$p)) "Levene" else NA_character_
  p_hov <- if (identical(hov_test, "Levene")) lev$p else if (identical(hov_test, "Bartlett")) bart$p.value else NA_real_
  left <- join_and(head_more(lev$left_out, 6))
  hov_label <- if (identical(hov_test, "Levene") && lev_full) "Levene's test"
    else if (identical(hov_test, "Levene")) sprintf("Levene's test on the cells with three or more values (%s left out)", left)
    else if (identical(hov_test, "Bartlett")) sprintf("Bartlett's test (%s; Bartlett's assumes the values are normal)",
      if (is.finite(lev$p)) sprintf("Levene's test leaves out %s, which %s fewer than three values", left,
                                    if (lev$dropped == 1) "has" else "have")
      else sprintf("Levene's test could not be run: %s", lev$why))
    else NA_character_
  hov_short <- if (identical(hov_test, "Levene") && lev_full) "Levene's"
               else if (identical(hov_test, "Levene")) "Levene's, on some cells" else if (identical(hov_test, "Bartlett")) "Bartlett's"
               else NA_character_
  ## why equal variances could not be tested at all
  hov_why <- if (!is.na(hov_test)) NULL
    else if (identical(lev$why, bart$why)) lev$why
    else sprintf("for Levene's test, %s; for Bartlett's test, %s", lev$why, bart$why)

  ## mean-variance relationship -> Taylor's power law slope, from each
  ## cell's own values even in a blocked design. Residuals share the block
  ## means, which carry every treatment's noise into every cell, so their
  ## slope came out near 0.3 where it should be 2 (lognormal, blocks acting
  ## in proportion) and 0.6 where it should be 1 (counts, no blocks), in
  ## 6 x 4 RCBDs simulated; the values themselves gave 2.0 and 1.0.
  mv <- data.frame(m = tapply(d[[resp]], cells, mean),
                   v = tapply(d[[resp]], cells, stats::var))
  mv <- mv[stats::complete.cases(mv) & mv$m > 0 & mv$v > 0, ]
  ## with an exact fit the cell variances are block (or row and column)
  ## effects, not error, so they say nothing about the error variance
  if (exact) mv <- mv[0, ]
  slope <- if (nrow(mv) >= 3)
    unname(stats::coef(stats::lm(log(v) ~ log(m), data = mv))[2]) else NA_real_
  ## the slope's own p-value: with two values per cell each variance rests on
  ## one degree of freedom, and a slope from such variances is mostly noise
  slope_p <- if (nrow(mv) >= 4)
    tryCatch(suppressWarnings(summary(stats::lm(log(v) ~ log(m), data = mv))$coefficients[2, 4]),
             error = function(e) NA_real_)
    else NA_real_

  bc <- if (exact) NULL else tryCatch(boxcox_profile(d[[resp]], res$X, level = 1 - alpha),
                                      error = function(e) NULL)

  ## named by the row numbers of the data table, which differ from positions
  ## among the analysed rows once any row has been left out
  outliers <- if (exact) integer(0) else rd_far_rows(res)

  list(alpha = alpha, exact = exact, strata = isTRUE(res$design %in% c("SPLIT", "STRIP")),
       on_residuals = length(res$blks) > 0,
       shapiro = sw, norm_why = norm_why,
       levene = lev, bartlett = bart, hov_test = hov_test, hov_label = hov_label, hov_short = hov_short,
       hov_why = hov_why, slope = slope, slope_p = slope_p,
       bc = bc, lambda = if (is.null(bc)) NA_real_ else bc$lambda,
       mv = mv, outliers = outliers,
       p_norm = if (is.null(sw)) NA_real_ else sw$p.value,
       p_hov  = p_hov)
}

## What the checks of normality and equal variances found, for the sentence
## that opens a recommendation: only the tests that could be run are named.
checks_text <- function(asm, alpha) {
  lvl <- paste0(pct(alpha), "%")
  norm <- !is.na(asm$p_norm); hov <- !is.na(asm$p_hov)
  hov_name <- sprintf("the test of equal variances (%s)", asm$hov_short)
  if (norm && hov) sprintf("Neither the normality test nor %s finds a significant departure at the %s level", hov_name, lvl)
  else if (norm) sprintf("The normality test finds no significant departure at the %s level, and equal variances could not be tested (%s)",
                         lvl, asm$hov_why %||% "too few values")
  else if (hov) sprintf("%s finds no significant departure at the %s level, and normality could not be tested (%s)",
                        paste0(toupper(substr(hov_name, 1, 1)), substring(hov_name, 2)), lvl,
                        asm$norm_why %||% "too few residuals")
  else ""
}

suggest_transform <- function(res, asm, dtype = "auto") {
  y <- res$data[[res$resp]]
  y <- y[!is.na(y)]
  pn <- asm$p_norm; ph <- asm$p_hov; b <- asm$slope; lam <- asm$lambda

  nm <- if (!is.null(res$orig_resp)) res$orig_resp else res$resp
  has_frac    <- any(abs(y - round(y)) > 1e-8)
  ## a 0-100 (or 0-1) range alone does NOT make a variable a percentage (or a
  ## proportion): most yields and heights live there too, and a height in
  ## metres lies between 0 and 1, so auto-detection also needs the name to say so
  pct_name <- grepl("perc|pct|%|proportion|fraction|incid|sever|infest|germinat|surviv|mortal|infect|damage",
                    tolower(nm))
  in_unit <- min(y) >= 0 && max(y) <= 1 && has_frac
  looks_prop  <- in_unit && pct_name
  looks_count <- min(y) >= 0 && !has_frac
  in_pct_range <- min(y) >= 0 && max(y) <= 100 && !in_unit
  looks_pct   <- in_pct_range && pct_name
  count_slope <- !is.na(b) && b >= 0.5 && b < 1.5

  ## an exact fit leaves nothing unexplained for a transformation to correct
  if (isTRUE(asm$exact))
    return(list(method = "none", optional = FALSE,
      why = paste("The model fits every value exactly, so there is no unexplained variation:",
                  "no transformation can help, and none is needed.")))

  ok <- (is.na(pn) || pn >= res$alpha) && (is.na(ph) || ph >= res$alpha)
  ## Equal variances are tested in full only when the verdict covers every
  ## cell; Levene's on some cells alone leaves the others untested.
  hov_full <- !is.na(ph) && !(identical(asm$hov_test, "Levene") && isTRUE(asm$levene$dropped > 0))
  ## An assumption that could not be tested has not been passed: then a rise
  ## of the variance with the mean decides instead, but only when the slope
  ## is itself significant at the chosen level, since a slope from variances
  ## of two values each is mostly noise.
  slope_evidence <- !is.na(b) && b >= 0.5 && isTRUE(asm$slope_p < res$alpha)
  if (ok && !hov_full && slope_evidence) ok <- FALSE
  all_tested <- !is.na(pn) && hov_full
  ## What may point to a particular transformation once a check has failed:
  ## the mean-variance slope when the variances were found unequal or the
  ## slope is itself significant, and the Box-Cox profile when its interval
  ## leaves out 1 and its peak lies inside the range searched. A departure
  ## from normality caused by one stray value is not a reason to transform.
  hov_fail <- !is.na(ph) && ph < res$alpha
  b_ok <- !is.na(b) && (hov_fail || isTRUE(asm$slope_p < res$alpha))
  bc_ok <- !is.na(lam) && !is.null(asm$bc) && abs(lam) < 2 - 1e-9 &&
    !(asm$bc$ci[1] <= 1 && asm$bc$ci[2] >= 1)
  ## only a transformation defined for every value is suggested
  pick <- function(method, why, optional = FALSE) {
    if (trans_defined(method, y)) return(list(method = method, optional = optional, why = why))
    list(method = "none", optional = FALSE,
         why = paste(why, sprintf(paste("However, %s is not defined for some of the values here (zero or",
                                        "negative ones), so it cannot be applied; no transformation is suggested."),
                                  TRANS[[method]]$lab)))
  }

  ## When the diagnostics are satisfactory we still name the conventional
  ## transformation for data that are plainly counts or percentages, flagged as
  ## optional - agronomic convention transforms them, the diagnostics do not
  ## demand it, and the analyst should decide knowingly. The opening sentence
  ## names only the checks that could be run.
  if (ok && dtype == "auto") {
    fine <- checks_text(asm, res$alpha)
    so <- if (all_tested) paste0(fine, ", so no transformation is strictly required.")
          else if (nzchar(fine)) paste0(fine, "; the checks that could be run give no reason for a transformation.")
          else "Neither normality nor equal variances could be tested, so the checks give no reason for a transformation."
    if (looks_prop)
      return(pick("arcsine01", optional = TRUE,
        paste(so, sprintf("'%s' lies between 0 and 1 and is named as a proportion, however, and convention is to analyse proportions on the angular (arcsine square-root) scale.", nm))))
    ## only a slope that is itself significant shows the variance rising
    ## with the mean; otherwise the claim would rest on noise
    if (looks_count && count_slope && slope_evidence)
      return(pick(if (min(y) < 1) "sqrt0.5" else "sqrt", optional = TRUE,
        sprintf("%s The response is nevertheless integer-valued with variance proportional to the mean (Taylor slope b = %.2f) - i.e. count data, for which the square root is conventional.", so, b)))
    if (looks_pct)
      return(pick("arcsine", optional = TRUE,
        sprintf("%s '%s' is bounded by 0 and 100 and named as a percentage, for which the angular (arcsine square-root) transformation is conventional.", so, nm)))
    return(list(method = "none", optional = FALSE,
      why = if (all_tested) paste0(fine, " - no transformation is needed.")
            else if (nzchar(fine)) paste0(fine, "; the checks that could be run give no reason for a transformation.")
            else "Neither normality nor equal variances could be tested, so there is no evidence for or against a transformation."))
  }

  ## user-declared data type wins over any guessing
  if (dtype == "percent")
    return(pick(if (max(y) <= 1) "arcsine01" else "arcsine",
      "You declared the response to be a percentage/proportion, so the angular (arcsine square-root) transformation applies."))
  if (dtype == "count")
    return(pick(if (min(y) < 1) "sqrt0.5" else "sqrt",
      "You declared the response to be a count, so the square-root transformation applies (sqrt(y+0.5) when zeros are present)."))

  if (looks_prop)
    return(pick("arcsine01",
      sprintf("'%s' lies between 0 and 1, is not integer and is named as a proportion, so the angular (arcsine square-root) transformation applies.", nm)))

  if (looks_count && count_slope && b_ok)
    return(pick(if (min(y) < 1) "sqrt0.5" else "sqrt",
      sprintf("The response is integer-valued and the variance rises in proportion to the mean (Taylor slope b = %.2f) - the classic signature of count data, so the square root is indicated.", b)))

  if (looks_pct && !(looks_count && count_slope && b_ok))
    return(pick("arcsine",
      sprintf("'%s' is bounded between 0 and 100 and its name suggests a percentage, so the angular (arcsine square-root) transformation applies.", nm)))

  if (b_ok) {
    if (b >= 0.5 && b < 1.5)
      return(pick(if (min(y) < 1) "sqrt0.5" else "sqrt",
        sprintf("Variance rises roughly in proportion to the mean (Taylor slope b = %.2f) - square root is indicated.", b)))
    if (b >= 1.5 && b < 2.5)
      return(pick(if (min(y) <= 0) "log1" else "log",
        sprintf("Variance rises with the square of the mean (b = %.2f) - the logarithmic transformation is indicated.", b)))
    if (b >= 2.5)
      return(pick("reciprocal",
        sprintf("Variance rises faster than the square of the mean (b = %.2f) - the reciprocal transformation is indicated.", b)))
  }
  if (bc_ok) {
    m <- if (abs(lam) < 0.15) "log" else if (abs(lam - 0.5) < 0.2) "sqrt" else
         if (abs(lam + 1) < 0.25) "reciprocal" else "boxcox"
    return(pick(m, sprintf("The Box-Cox profile peaks at lambda = %.2f, and its interval leaves out 1 (no transformation).", lam)))
  }
  hint <- if (in_pct_range && !pct_name)
    " Note: your response lies between 0 and 100. If it really is a percentage, set 'Nature of the response' to 'Percentage / proportion' and the angular transformation will be applied." else ""
  stray <- if (!is.na(pn) && pn < res$alpha && length(asm$outliers))
    sprintf(paste(" The residuals depart from normality, but neither the spread of the treatments nor the Box-Cox",
                  "profile points to a transformation; the possible %s (%s) may be the cause, so check %s first."),
            pl(length(asm$outliers), "outlier", "outliers"), rows_text(asm$outliers),
            pl(length(asm$outliers), "it", "them"))
    else ""
  list(method = "none",
       why = paste0("No clear transformation is indicated.", stray,
                    " If normality is badly violated, consider a non-parametric test (Kruskal-Wallis / Friedman).", hint))
}

## Is transformation `m` defined for every value of y?
trans_defined <- function(m, y) {
  y <- y[!is.na(y)]
  switch(m, none = TRUE, log = all(y > 0), log1 = all(y > -1), sqrt = all(y >= 0),
         sqrt0.5 = all(y >= -0.5), arcsine = all(y >= 0 & y <= 100), arcsine01 = all(y >= 0 & y <= 1),
         reciprocal = all(y != 0), boxcox = all(y > 0), TRUE)
}

#' The transformations DOEpro offers
#'
#' A named list of the variance-stabilising transformations. Each entry holds a
#' label (\code{lab}), the transformation (\code{f}) and its inverse
#' (\code{inv}), which is what lets DOEpro report means on the original scale of
#' measurement alongside the transformed ones.
#'
#' @format A named list of length 9. The names are the keys used in the
#'   \code{trans} argument of \code{\link{run_all}}: \code{"none"},
#'   \code{"log"}, \code{"log1"}, \code{"sqrt"}, \code{"sqrt0.5"},
#'   \code{"arcsine"}, \code{"arcsine01"}, \code{"reciprocal"} and
#'   \code{"boxcox"}.
#'
#' @return A named list of length 9. Each element is itself a list with
#'   \code{lab}, the label shown in the application; \code{f}, a function
#'   applying the transformation; and \code{b}, a function applying its
#'   inverse, which is what allows means to be reported on the original scale
#'   of measurement.
#'
#' @examples
#' names(TRANS)
#' vapply(TRANS, `[[`, character(1), "lab")
#'
#' @export
TRANS <- list(
  none       = list(lab = "None",                       f = function(y, l) y,
                    b = function(z, l) z),
  log        = list(lab = "log(y)",                     f = function(y, l) log(y),
                    b = function(z, l) exp(z)),
  log1       = list(lab = "log(y + 1)",                 f = function(y, l) log(y + 1),
                    b = function(z, l) exp(z) - 1),
  sqrt       = list(lab = "sqrt(y)",                    f = function(y, l) sqrt(y),
                    b = function(z, l) z^2),
  sqrt0.5    = list(lab = "sqrt(y + 0.5)",              f = function(y, l) sqrt(y + 0.5),
                    b = function(z, l) z^2 - 0.5),
  arcsine    = list(lab = "arcsine sqrt(y/100), degrees",
                    f = function(y, l) asin(sqrt(y / 100)) * 180 / pi,
                    b = function(z, l) (sin(z * pi / 180))^2 * 100),
  arcsine01  = list(lab = "arcsine sqrt(y), degrees",
                    f = function(y, l) asin(sqrt(y)) * 180 / pi,
                    b = function(z, l) (sin(z * pi / 180))^2),
  reciprocal = list(lab = "1 / y",                      f = function(y, l) 1 / y,
                    b = function(z, l) 1 / z),
  boxcox     = list(lab = "Box-Cox (optimal lambda)",
                    f = function(y, l) if (abs(l) < 1e-6) log(y) else (y^l - 1) / l,
                    b = function(z, l) if (abs(l) < 1e-6) exp(z) else (z * l + 1)^(1 / l))
)

## ---------------------------------------------------------- tables_detail.R ----
###############################################################################
##  INTEGRATED MEAN TABLES  (every effect, in detail)
###############################################################################
## two-way table with marginal means
two_way <- function(d, resp, f1, f2) {
  tb <- tapply(d[[resp]], list(d[[f1]], d[[f2]]), mean)
  tb <- cbind(tb, `Mean` = rowMeans(tb, na.rm = TRUE))
  tb <- rbind(tb, `Mean` = colMeans(tb, na.rm = TRUE))
  out <- data.frame(rownames(tb), tb, check.names = FALSE)
  names(out)[1] <- f1
  out
}

## SE(m), SE(d) and, when the comparison is the C.D., the C.D. under a table
## of means. With unequal replication they differ from mean to mean, and the
## range is given instead of one figure.
effect_footer <- function(e, cv = NULL, cmp = comparison()) {
  ## a split, strip or pooled interaction's single figures hold only for means
  ## at the same level of its slicing factor; the others follow in e$extra
  within <- if (is.null(e$slice)) "" else sprintf(" (within the same %s)", esc(e$slice))
  rows <- c(
    sprintf("<tr><td>SEm &plusmn;%s</td><td>%s</td></tr>", within, err_text(e, "sem", 3)),
    sprintf("<tr><td>SEd%s</td><td>%s</td></tr>", within, err_text(e, "sed", 3)),
    if (identical(cmp$kind, "cd"))
      sprintf("<tr><td>%s%s</td><td>%s</td></tr>", cd_name(e$alpha), within, cd_or_ns(e, 3)))
  if (!is.null(cv)) rows <- c(rows, sprintf("<tr><td>CV (%%)</td><td>%s</td></tr>",
                                            paste(fmt(cv, 2), collapse = " / ")))
  paste0("<table class='doe foot'>", paste(rows, collapse = ""), "</table>")
}

## compact matrix of f1 x f2 cell means (from an effect's table of means)
## with the letters, if any, as superscripts, plus marginal means. The
## margins and the corner are averages of the cell means, so they agree with
## the adjusted margins when replication is unequal; with a transformation
## they are shown like the cells, back-transformed with the transformed value
## in parentheses (`btf` is the back-transformation).
two_way_lettered <- function(m, f1, f2, lets, tr_on, digits, caption, btf = NULL) {
  l1 <- levels(factor(m[[f1]])); l2 <- levels(factor(m[[f2]]))
  disp <- if (tr_on && "Mean_bt" %in% names(m)) m$Mean_bt else m$Mean
  ix <- cbind(match(as.character(m[[f1]]), l1), match(as.character(m[[f2]]), l2))
  cD <- matrix(NA_real_, length(l1), length(l2))
  cR <- cD; lg <- matrix("", length(l1), length(l2))
  cD[ix] <- disp; cR[ix] <- m$Mean
  if (length(lets)) lg[ix] <- lets
  rmean <- rowMeans(cR, na.rm = TRUE); cmean <- colMeans(cR, na.rm = TRUE)
  marg <- function(x) if (tr_on && is.function(btf))
    paste0(fmt(btf(x), digits), " (", fmt(x, digits), ")") else fmt(x, digits)
  body <- lapply(seq_along(l1), function(i)
    c(esc(l1[i]),
      vapply(seq_along(l2), function(j)
        paste0(fmt(cD[i, j], digits),
               if (tr_on) paste0(" (", fmt(cR[i, j], digits), ")") else "",
               sup(lg[i, j])), character(1)),
      marg(rmean[i])))
  body[[length(body) + 1L]] <- c("<b>Mean</b>", marg(cmean), marg(mean(cR, na.rm = TRUE)))
  raw_table(c(paste(esc(f1), "&#92;", esc(f2)), vapply(l2, esc, ""), "Mean"), body, caption = caption)
}

## the note under a table whose letters restart in each level of a factor
slice_note <- function(e) {
  if (is.null(e$slice)) return("")
  sprintf(paste0("<p class='note'>Letters compare %s means within the same level of %s ",
                 "only; the same letter in two levels of %s means nothing.</p>"),
          esc(paste(setdiff(e$vars, e$slice), collapse = " x ")), esc(e$slice), esc(e$slice))
}

## The environment x treatment table of a pooled analysis: with a significant
## interaction, each environment's treatments, compared within that
## environment against the pooled error, by the comparison chosen. A
## two-factor treatment structure is shown as a matrix, otherwise as a
## ranked table.
gxe_env_tables <- function(e, lets, digits, cmp) {
  E <- e$env; tf <- setdiff(e$vars, E)
  m <- e$means; m$.let <- lets
  out <- vapply(levels(factor(m[[E]])), function(lv) {
    mi <- m[as.character(m[[E]]) == lv, , drop = FALSE]
    cap <- sprintf("<b>%s</b> &mdash; %s means%s", esc(lv), esc(paste(tf, collapse = " x ")),
                   if (identical(cmp$kind, "letters")) sprintf(" (letters compare cells within %s)", esc(lv)) else "")
    if (length(tf) == 2) {
      two_way_lettered(mi, tf[1], tf[2], mi$.let, FALSE, digits, cap)
    } else {
      mm <- mi[order(-mi$Mean), c(tf, "Mean"), drop = FALSE]
      if (identical(cmp$kind, "letters")) mm$Letters <- mi$.let[order(-mi$Mean)]
      df_html(mm, caption = cap)
    }
  }, character(1))
  paste0("<div class='ms-env-wrap'>", paste(out, collapse = ""), "</div>")
}

## What sits under an environment x treatment table: the verdict and, when
## the interaction is significant, how the cells are compared, by the
## comparison chosen
gxe_cmp_note <- function(res, e, cmp) {
  a <- e$alpha; E <- e$env; tf <- paste(setdiff(e$vars, E), collapse = " x ")
  if (!effect_sig(e))
    return(sprintf(paste("The %s x %s interaction is not significant at the %s%% level: there is insufficient evidence",
                         "that the treatment differences change from one environment to another, so the individual",
                         "environment cells are not compared."), esc(E), esc(tf), pct(a)))
  how <- switch(cmp$kind,
    cd = sprintf("Two cells in the same environment differ significantly when their difference is larger than the %s within an environment, %s (pooled error).",
                 cd_name(a), fmt(e$cd)),
    letters = sprintf("Letters, by %s, compare cells within one environment only (pooled error).", CMP_NAME[[cmp$method]]),
    "Choose a comparison method to compare the cells within each environment.")
  sprintf("The %s x %s interaction is significant at the %s%% level, so the cells are shown separately for each environment. %s",
          esc(E), esc(tf), pct(a), how)
}

## Every effect of one response in detail, as the comparison chosen shows
## it. With `readings`, each table is followed by a reading of what it shows.
integrated_means_html <- function(res, digits = 2, readings = FALSE, cmp = comparison()) {
  h <- c(sprintf("<p><b>Response:</b> %s &nbsp; | &nbsp; <b>Grand mean:</b> %s &nbsp; | &nbsp; <b>%s</b></p>",
                 esc(res$resp), fmt(res$grand),
                 paste(sprintf("%s = %s", names(res$cv), fmt(res$cv, 2)), collapse = " | ")))

  tr <- res$trans %||% "none"
  tr_on <- !identical(tr, "none")
  btf <- if (tr_on) function(z) TRANS[[tr]]$b(z, res$lambda) else NULL
  fit <- list(final = res, trans = tr, lambda = res$lambda, header = res$resp)
  ## the unadjusted average, which with a transformation is on that scale too
  raw_lab <- if (tr_on) "Unadjusted mean (transformed scale)" else "Unadjusted mean"
  relabel <- function(x) sub("^Raw_mean$", raw_lab, sub("^Mean_bt$", "Back-transformed", sub("^N$", "n", x)))

  for (nm in names(res$effects)) {
    e <- res$effects[[nm]]
    ttl <- sprintf("Table of means: <b>%s</b> &nbsp;(F = %s, %s, %s)",
                   esc(e$label), fmt(e$F, 2), p_eq(e$p, e$alpha), star(e$p, e$alpha))
    unequal <- !isTRUE(e$equal_rep)
    L <- cmp_letters(res, nm, cmp)
    lets <- if (identical(cmp$kind, "letters")) L$letters else rep("", nrow(e$means))
    m <- e$means
    foot <- ""; extra <- ""; note <- character(0)

    if (isTRUE(e$is_gxe)) {
      inner <- if (effect_sig(e)) gxe_env_tables(e, lets, digits, cmp) else ""
      body <- paste0("<div class='ms-detail-name'>", ttl, "</div>",
                     "<p class='note'>", gxe_cmp_note(res, e, cmp), "</p>", inner)

    } else if (length(e$vars) == 1) {
      ## with unequal replication each mean carries its own SE, and an adjusted
      ## mean is shown beside the raw average it was adjusted from
      cols <- intersect(c(e$vars, "Mean", "Raw_mean", "Mean_bt", "N", if (unequal) "SE"), names(m))
      mm <- m[, cols, drop = FALSE]
      if (any(nzchar(lets))) mm$Letters <- lets
      names(mm) <- relabel(names(mm))
      body <- df_html(mm, caption = ttl)
      foot <- effect_footer(e, res$cv, cmp)

    } else if (length(e$vars) == 2) {
      body <- paste0(two_way_lettered(m, e$vars[1], e$vars[2], lets, tr_on, digits, ttl, btf),
                     if (any(nzchar(lets))) slice_note(effect_by(e, L$x$by)) else "")
      foot <- effect_footer(e, res$cv, cmp)

    } else {
      ## a table of three or more factors: one row per combination
      cols <- c(e$vars, "Mean", intersect(c("Raw_mean", "Mean_bt"), names(m)), if (unequal) c("N", "SE"))
      ord <- do.call(order, unname(as.list(m[e$vars])))
      mm <- m[ord, cols, drop = FALSE]
      if (any(nzchar(lets))) mm$Letters <- lets[ord]
      names(mm) <- relabel(names(mm))
      body <- df_html(mm, caption = ttl)
      foot <- effect_footer(e, res$cv, cmp)
    }

    ## the other comparisons of a split, strip or pooled interaction: each
    ## SE(d), and each C.D. when the comparison is the C.D., shown only where
    ## its own F-test is significant
    xt <- cmp_extra(e, cmp)
    if (length(xt))
      extra <- paste0("<table class='doe foot'>",
        paste0(sprintf("<tr><td>%s</td><td>%s</td></tr>", esc(names(xt)), xt), collapse = ""),
        "</table>")
    if (!isTRUE(e$is_gxe)) {
      ## the adjusted-means note from the analysis; notes about letters and
      ## C.D.s are written here, to match what the table shows
      if (!is.null(m$Raw_mean) && is.null(e$slice) && is.null(e$mix)) note <- c(note, e$notes[1])
      if (!is.null(e$mix))
        note <- c(note, paste0("The environment is random, so the difference between two of these means carries the ",
                               "environment's interaction with each factor in which they differ: each kind of comparison ",
                               "has its own SE(d)", if (identical(cmp$kind, "cd")) " and C.D. (from Gomez and Gomez's weighted t)" else "",
                               ", listed above."))
      note <- c(note, cmp_letters_note(cmp, e, L))
    }
    note_html <- if (length(note)) paste0("<p class='note'>", paste(note, collapse = " "), "</p>") else ""
    rd <- if (readings) rd_html(cmp_detail_text(fit, nm, cmp, digits, L)) else ""
    h <- c(h, "<div class='block'>", body, foot, extra, note_html, rd, "</div>")
  }
  HTML(paste(h, collapse = "\n"))
}

## The reading under a detailed table, which prints one-factor and
## many-factor tables to three decimals, two-way tables to `digits`, and
## every C.D. to three. An environment x treatment table carries its own note.
cmp_detail_text <- function(fit, effect, cmp, digits = 2, L = NULL) {
  r <- fit$final; e <- r$effects[[effect]]
  if (isTRUE(e$is_gxe)) return("")
  if (exact_fit(r)) return(RD_EXACT)
  if (length(e$vars) == 1) cmp_means_text(fit, effect, cmp, 3, L)
  else if (length(e$vars) == 2) cmp_twoway_text(fit, e$vars[1], e$vars[2], cmp, digits, L, cd_digits = 3)
  else multi_text(e, 3, fit$trans)
}

## ---------------------------------------------------------- posthoc.R ----
###############################################################################
##  POST-HOC
###############################################################################
## Post-hoc multiple comparisons, computed from the effect's own error term and
## from each pair's own standard error of a difference, taken from the effect's
## SE(d) matrix. With equal replication every pair has the same SE(d) and these
## are the textbook procedures. With unequal replication Tukey's HSD becomes the
## Tukey-Kramer procedure, the LSD, Bonferroni and Scheffe tests stay exact,
## and the two multiple-range tests use Kramer's (1956) pairwise adjustment;
## the output says which. Interaction effects of split plots, strip plots and
## pooled analyses are compared within one level of their slicing factor, the
## only comparisons that share one error term. Dunnett's test compares every
## mean with a control instead of every pair (R/dunnett.R).
PH_METHODS <- c("LSD (Fisher's protected)", "LSD (Bonferroni-adjusted)",
                "Tukey HSD", "Duncan's DMRT", "Student-Newman-Keuls", "Scheffe", "Dunnett")

## The reciprocal reverses the order of the values: the highest 1/y is the
## lowest value as entered, and "higher than the control" means lower.
## (Every other transformation offered, Box-Cox included, keeps the order.)
rev_note <- function(res) {
  if (!identical(res$trans, "reciprocal")) return("")
  v <- res$orig_resp %||% res$resp
  sprintf(paste("The comparisons are of 1 / %s, whose order is the reverse of %s as entered: a higher mean here",
                "is a lower %s, so 'higher' and 'lower' in this output refer to 1 / %s."), v, v, v, v)
}

## what each method is called wherever it is shown to the user
PH_LABELS <- c(
  "LSD (Fisher's protected)"  = "Least significant difference (LSD), Fisher's protected",
  "LSD (Bonferroni-adjusted)" = "Least significant difference (LSD), Bonferroni-adjusted",
  "Tukey HSD"                 = "Tukey's honestly significant difference (HSD)",
  "Duncan's DMRT"             = "Duncan's multiple range test (DMRT)",
  "Student-Newman-Keuls"      = "Student-Newman-Keuls (SNK) test",
  "Scheffe"                   = "Scheffe's test",
  "Dunnett"                   = "Dunnett's test (each treatment against a control)")

## `control` (a level as dunnett_levels() lists it) and `alternative`
## ("two.sided", "greater" or "less") are used by Dunnett's test only.
## `by` names a factor of an interaction within whose levels its means are
## compared (simple effects): the levels of the other factors at each level
## of `by`. In a design with one error term every pair shares that error, so
## any factor may be chosen; a split, strip or pooled interaction is always
## compared within its slicing factor, the only comparisons with one error.
posthoc <- function(res, effect, method, alpha = res$alpha, control = NULL, alternative = "two.sided",
                    by = NULL) {
  e <- res$effects[[effect]]
  if (is.null(e)) stop("Unknown effect.")
  if (!method %in% PH_METHODS) stop("Unknown method")
  e <- effect_by(e, by)
  m <- e$means
  lab <- apply(m[e$vars], 1, paste, collapse = " : ")
  fams <- if (is.null(e$slice)) list(seq_len(nrow(m)))
          else unname(split(seq_len(nrow(m)), factor(m[[e$slice]], levels = unique(m[[e$slice]]))))
  fams <- fams[lengths(fams) >= 2]
  if (!length(fams)) stop("This effect has fewer than two means.")
  rn <- rev_note(res)
  if (method == "Dunnett") {
    x <- posthoc_notes(posthoc_dunnett(e, fams, alpha, control, alternative), e, method, alpha)
    if (nzchar(rn)) x$note <- c(x$note, rn)
    return(x)
  }
  df <- e$df
  ## a pooled factorial's interaction: each pair has its own SE(d) and its
  ## own (Satterthwaite) degrees of freedom
  mixed <- !is.null(e$mix)
  dfm <- if (mixed) mix_df(e) else NULL
  if (mixed) df <- min(dfm[row(dfm) != col(dfm)])
  ranged <- method %in% c("Student-Newman-Keuls", "Duncan's DMRT")
  if (method %in% c("Tukey HSD", "Student-Newman-Keuls", "Duncan's DMRT") && df < 2)
    stop(sprintf(paste0("%s needs at least 2 error degrees of freedom; this effect has %s. ",
                        "Use the LSD, Bonferroni or Scheffe test, or add replication."),
                 PH_LABELS[[method]], df_text(df)))
  kmax <- max(lengths(fams))
  ## the studentized range for p means spanned (p = 2..kmax), divided by
  ## sqrt(2) so that it multiplies a standard error of a difference; computed
  ## once per span, not once per pair
  ranges_for <- function(df) {
    q <- vapply(2:kmax, function(p) {
      pr <- if (method == "Student-Newman-Keuls") 1 - alpha else (1 - alpha)^(p - 1)
      q_tukey(pr, p, df)
    }, numeric(1))
    ## Duncan's ranges must not shrink as more means are spanned; with few error
    ## df the raw quantiles at his protection levels do, so they are held level
    if (method == "Duncan's DMRT") q <- cummax(q)
    c(Inf, q / sqrt(2))
  }
  qv <- if (ranged && !mixed) ranges_for(df) else NULL
  ## per pair, a quantile computed once for each distinct df
  by_df <- function(D, f) {
    u <- unique(as.vector(D)); vals <- lapply(u, f)
    function(i) vals[[match(D[i], u)]]
  }

  run <- function(ix) {
    mu <- m$Mean[ix]; k <- length(mu)
    S <- e$sed_mat[ix, ix, drop = FALSE]            # rows of sed_mat follow e$means
    nC <- k * (k - 1) / 2
    ## the number of means spanned by a pair, counting every mean between the
    ## two values; tied means then share the wider, more cautious range
    ## whatever order their levels happen to be in
    span <- outer(seq_len(k), seq_len(k), Vectorize(function(i, j)
      sum(mu >= min(mu[i], mu[j]) & mu <= max(mu[i], mu[j]))))
    mult <- if (!mixed) switch(method,
      "LSD (Fisher's protected)"  = matrix(t_crit(e, alpha), k, k),
      "LSD (Bonferroni-adjusted)" = matrix(stats::qt(1 - alpha / (2 * nC), df), k, k),
      "Tukey HSD"                 = matrix(q_tukey(1 - alpha, k, df) / sqrt(2), k, k),
      "Scheffe"                   = matrix(sqrt((k - 1) * stats::qf(1 - alpha, k - 1, df)), k, k),
      matrix(qv[span], k, k))
    else {
      D <- dfm[ix, ix, drop = FALSE]
      switch(method,
        "LSD (Fisher's protected)"  = mix_t(e, alpha)[ix, ix, drop = FALSE],
        "LSD (Bonferroni-adjusted)" = mix_t(e, alpha / nC)[ix, ix, drop = FALSE],
        "Tukey HSD"                 = { g <- by_df(D, function(v) q_tukey(1 - alpha, k, v) / sqrt(2))
                                        matrix(vapply(seq_along(D), g, 0), k, k) },
        "Scheffe"                   = matrix(sqrt((k - 1) * stats::qf(1 - alpha, k - 1, D)), k, k),
        { g <- by_df(D, ranges_for)
          matrix(vapply(seq_along(D), function(i) g(i)[span[i]], 0), k, k) })
    }
    crit <- mult * S
    raw <- abs(outer(mu, mu, "-")) > crit
    diag(raw) <- FALSE
    sig <- if (ranged) step_down(mu, raw) else raw
    lets <- cld_from_sig(mu, sig)

    o <- order(-mu)
    ij <- which(upper.tri(diag(k)), arr.ind = TRUE)
    ij <- ij[order(ij[, 1], ij[, 2]), , drop = FALSE]
    ij <- cbind(o[ij[, 1]], o[ij[, 2]])                 # larger mean first
    pairs <- data.frame(
      Comparison = paste(lab[ix][ij[, 1]], "vs", lab[ix][ij[, 2]]),
      Difference = mu[ij[, 1]] - mu[ij[, 2]],
      SEd = S[ij],
      `Critical value` = mult[ij],
      `Critical difference` = crit[ij],
      Significant = ifelse(sig[ij], "Yes",
                    ifelse(raw[ij], "No (inside a non-significant range)", "No")),
      check.names = FALSE, stringsAsFactors = FALSE)
    list(lets = lets, pairs = pairs, k = k, crit = crit[upper.tri(crit)], sig = sig)
  }
  out <- lapply(fams, run)

  within <- if (is.null(e$slice)) NULL else
    vapply(fams, function(ix) as.character(m[[e$slice]][ix[1]]), character(1))
  ## each family's means and the pairs this test declares, for the reading;
  ## the labels name only the levels that vary within the family
  vary <- setdiff(e$vars, e$slice)
  families <- lapply(seq_along(fams), function(f) {
    ix <- fams[[f]]
    list(lab = apply(m[ix, vary, drop = FALSE], 1, function(z) paste(trimws(z), collapse = " : ")),
         mu = m$Mean[ix], sig = out[[f]]$sig, within = if (is.null(within)) NULL else within[f])
  })
  groups <- do.call(rbind, lapply(seq_along(fams), function(f) {
    ix <- fams[[f]]
    g <- data.frame(Treatment = lab[ix], Mean = m$Mean[ix], row.names = NULL, check.names = FALSE)
    if (!is.null(m$Raw_mean)) g$`Unadjusted mean` <- m$Raw_mean[ix]
    g <- cbind(g, n = m$N[ix], SE = m$SE[ix], Group = out[[f]]$lets)
    if (!is.null(within)) g <- cbind(Within = within[f], g)
    g[order(-g$Mean), ]
  }))
  rownames(groups) <- NULL
  pairs <- do.call(rbind, lapply(seq_along(fams), function(f) {
    p <- out[[f]]$pairs
    if (!is.null(within)) p <- cbind(Within = within[f], p)
    p
  }))

  ## one critical difference for the whole family only if one really applies
  crit_all <- unlist(lapply(out, `[[`, "crit"))
  equal <- isTRUE(e$equal_rep)
  one_cd <- !ranged && diff(range(crit_all)) <= 1e-9 * max(abs(crit_all))
  ranges <- if (ranged && equal)
    data.frame(`Means apart (p)` = 2:kmax, `Critical range` = qv[2:kmax] * e$sed,
               check.names = FALSE)
  else NULL

  kramer <- !equal && !mixed && (method == "Tukey HSD" || ranged)
  shown <- if (mixed && method != "LSD (Fisher's protected)")
             paste(PH_LABELS[[method]], "with each pair's own SE(d) and degrees of freedom")
           else if (method == "Tukey HSD" && !equal)
             "Tukey-Kramer procedure (Tukey's HSD for unequal replication)"
           else if (kramer) paste(PH_LABELS[[method]], "with Kramer's adjustment for unequal replication")
           else PH_LABELS[[method]]
  k_txt <- if (is.null(within)) as.character(nrow(m))
           else sprintf("%s within each level of %s", paste(unique(vapply(out, `[[`, numeric(1), "k")),
                                                         collapse = " or "), e$slice)
  st <- data.frame(
    Item  = c("Effect", "Method", "Error mean square", "Error df",
              "SE of a mean (SEm)", "SE of a difference (SEd)",
              "Number of means (k)", "Significance level",
              if (one_cd) "Critical difference (C.D.)" else "Critical difference"),
    Value = c(e$label, shown,
              if (mixed) "varies by pair - see the notes" else fmt(e$mse, 4),
              if (mixed) df_label(e) else df_text(df),
              err_text(e, "sem", 3, html = FALSE), err_text(e, "sed", 3, html = FALSE),
              k_txt, p_lab(alpha),
              if (one_cd) fmt(crit_all[1])
              else if (ranged && equal) "varies with p - see the table of critical ranges"
              else "varies by pair - see the pairwise comparisons"),
    check.names = FALSE)

  f_sig <- !is.na(e$p) && e$p < alpha
  note <- c(
    if (!f_sig)
      sprintf(paste0("The F-test for %s is not significant at the %s%% level, so, as ",
                     "everywhere else in DOEpro, no letters are shown and no pair is ",
                     "declared different."), e$label, pct(alpha)),
    if (!is.null(e$slice))
      sprintf(paste0("Means are compared within each level of %s%s. Letters restart in each level, ",
                     "so the same letter in two levels of %s means nothing."), e$slice,
              if (isTRUE(e$by_chosen)) " (simple effects), as chosen"
              else ": these are the only comparisons that share one error term", e$slice),
    if (!is.null(e$error_desc)) e$error_desc,
    if (method == "Tukey HSD" && !equal && !mixed)
      paste0("Replication is unequal, so this is the Tukey-Kramer procedure: Tukey's ",
             "studentized range applied to each pair's own standard error of a difference."),
    if (ranged && !equal && !mixed)
      paste0("Replication is unequal, so each pair uses its own standard error of a ",
             "difference (Kramer, 1956). agricolae and SAS use the harmonic mean of the ",
             "replications instead, so their critical ranges will differ slightly."),
    if (ranged)
      paste0("As a multiple-range test this is a step-down procedure: two means inside a ",
             "range that is not significant are not declared different, even if their own ",
             "difference exceeds its critical range."),
    if (method %in% c("Tukey HSD", "Student-Newman-Keuls", "Duncan's DMRT"))
      paste0("The critical value in the pairwise table is the studentized range q divided ",
             "by &radic;2, so that critical difference = critical value &times; SEd. Tables of ",
             "q list it before that division."),
    ## notes written for the tables of means describe that table's letters and
    ## level, so they are repeated here only when they apply to this output
    if (is.null(e$slice) && is.null(e$mix) && isTRUE(all.equal(alpha, e$alpha))) e$notes,
    if (!isTRUE(all.equal(alpha, e$alpha)))
      sprintf(paste0("These comparisons are at the %s%% level, while the analysis and its ",
                     "tables of means are at the %s%% level."), pct(alpha), pct(e$alpha)))
  note <- c(note, rn)
  note <- note[nzchar(note)]

  ## the letters in the order of the effect's table of means, for the
  ## tables and plots that show them beside the means
  lets_row <- character(nrow(m))
  for (f in seq_along(fams)) lets_row[fams[[f]]] <- out[[f]]$lets

  list(groups = groups, stats = st, ranges = ranges, pairs = pairs,
       note = if (length(note)) note else NULL, f_sig = f_sig, alpha = alpha,
       method = PH_LABELS[[method]], families = families, letters = lets_row, by = e$slice)
}

## What the user sees and exports: the procedure's letters and verdicts only
## when the effect's F-test is significant, as for every other table in
## DOEpro. posthoc() itself keeps them, as an effect keeps its letters.
gate_posthoc <- function(x) {
  if (isTRUE(x$f_sig)) return(x)
  if ("Group" %in% names(x$groups)) x$groups$Group <- ""
  if (!is.null(x$letters)) x$letters[] <- ""
  if ("Versus the control" %in% names(x$groups))
    x$groups$`Versus the control`[x$groups$`Versus the control` != "Control"] <- ""
  x$pairs$Significant <- sprintf("Not declared (F-test not significant at %s%%)", pct(x$alpha))
  x
}

## Multiple-range tests are step-down procedures: once a range of means is
## declared homogeneous, no pair inside it may be declared different. Working
## from the widest range inwards, a pair stays significant only if both ranges
## one step wider than it were significant, and therefore every range around it.
## With tied means the enclosing ranges are taken by value, not by position: a
## pair keeps its own test and is gated by every range that strictly encloses
## its two values, so the result does not depend on the order in which tied
## levels happen to sit. Without ties this is the recursion above unchanged.
step_down <- function(mu, sig) {
  k <- length(mu); o <- order(mu, decreasing = TRUE)
  s <- sig[o, o, drop = FALSE]; v <- mu[o]
  out <- matrix(FALSE, k, k)
  for (w in rev(seq_len(k - 1))) for (i in seq_len(k - w)) {
    j <- i + w
    out[i, j] <- s[i, j] && (i == 1 || out[i - 1, j]) && (j == k || out[i, j + 1])
  }
  first <- vapply(v, function(x) min(which(v == x)), integer(1))  # start of each tie block
  last  <- vapply(v, function(x) max(which(v == x)), integer(1))  # end of each tie block
  fin <- matrix(FALSE, k, k)
  for (i in seq_len(k - 1)) for (j in (i + 1):k) {
    ## a range reaching above the larger value, or below the smaller one
    above <- first[i] == 1 || out[first[i] - 1, first[j]]
    below <- last[j] == k || out[last[i], last[j] + 1]
    fin[i, j] <- s[i, j] && above && below
  }
  fin <- fin | t(fin)
  res <- matrix(FALSE, k, k)
  res[o, o] <- fin
  res
}

## An interaction effect whose means are to be compared within the levels of
## factor `by` (simple effects). Only a design with one error term allows a
## free choice; an effect with its own slicing factor keeps it.
effect_by <- function(e, by) {
  if (length(by) == 1L && !is.na(by) && nzchar(by) && is.null(e$slice) && is.null(e$mix) &&
      by %in% e$vars && length(e$vars) >= 2) {
    e$slice <- by
    e$by_chosen <- TRUE
  }
  e
}

## qtukey() fails to converge for the long ranges Duncan's test needs once about
## twenty means are compared (it returns NaN); inverting ptukey() does not
q_tukey <- function(pr, p, df) {
  q <- suppressWarnings(stats::qtukey(pr, p, df))
  if (is.finite(q)) return(q)
  f <- function(x) stats::ptukey(x, p, df) - pr
  if (!is.finite(f(1e-3)) || !is.finite(f(100)))
    stop(sprintf(paste0("The studentized range cannot be computed for %d means on %s ",
                        "error degrees of freedom. Use the LSD, Bonferroni or Scheffe test."),
                 p, df_text(df)), call. = FALSE)
  stats::uniroot(f, c(1e-3, 100), tol = 1e-12)$root
}

## degrees of freedom: whole numbers as they are, Satterthwaite's to one decimal
df_text <- function(df) if (abs(df - round(df)) < 1e-8) as.character(round(df)) else fmt(df, 1)

## ---------------------------------------------------------- dunnett.R ----
###############################################################################
##  DUNNETT'S TEST
###############################################################################
## Dunnett's test compares each treatment with one control and nothing else.
## Its critical value is the quantile of the largest |t| (or the largest t,
## for one side) among those comparisons, which share the control's mean and
## the error mean square: a multivariate t whose correlations follow from
## the standard errors of the differences.
##
## When every correlation is lambda_i * lambda_j, which holds whenever the
## means are independent (equal or unequal replication) and in a blocked
## design with one missing plot, the comparisons can be written
##     t_i = (lambda_i Z0 + sqrt(1 - lambda_i^2) E_i) / S,
## with Z0 and the E_i independent standard normals and S^2 a chi-square over
## its degrees of freedom, so the probability is a two-dimensional integral
## over Z0 and S (Dunnett, 1955). It is done here by trapezoid rules on the
## whole line, over log S and over Z0, which converge geometrically for such
## smooth, fast-decaying integrands: with one comparison the value is
## Student's t to within 2e-10 from 1 to 5000 degrees of freedom, and
## Dunnett's tables are reproduced to their last decimal. Correlations not of
## that form (two or more missing plots in a blocked design) are given the
## nearest form of it, and the output says that this is an approximation; in
## a test with two missing plots it was within 0.002 of a simulation of the
## exact value.

## the integration grid for `df` error degrees of freedom: points (s, z)
## and their weights, without the points whose weights together come to
## less than 1e-14, which cannot move the probability by more than that
DUNNETT_GRIDS <- new.env(parent = emptyenv())
dunnett_grid <- function(df) {
  key <- format(df, digits = 15)
  if (!is.null(DUNNETT_GRIDS[[key]])) return(DUNNETT_GRIDS[[key]])
  ns <- if (df < 3) 400 else 80; nz <- 81; L <- 8.5
  lo <- 0.5 * log(stats::qchisq(1e-15, df) / df)
  hi <- 0.5 * log(stats::qchisq(1e-15, df, lower.tail = FALSE) / df)
  t <- seq(lo, hi, length.out = ns); ht <- t[2] - t[1]
  ## the density of log S, for S^2 = chi-square / df
  ws <- ht * exp(log(2) + (df / 2) * log(df / 2) - lgamma(df / 2) + df * t - df * exp(2 * t) / 2)
  z <- seq(-L, L, length.out = nz); wz <- (z[2] - z[1]) * stats::dnorm(z)
  w <- as.vector(outer(wz, ws))
  o <- order(w); small <- cumsum(w[o]) < 1e-14
  keep <- setdiff(seq_along(w), o[small])
  g <- list(s = rep(exp(t), each = nz)[keep], z = rep(z, times = ns)[keep], w = w[keep])
  DUNNETT_GRIDS[[key]] <- g
  g
}

## P(every comparison within c), for comparisons with loadings `lam`, each
## of the distinct loadings evaluated once and raised to its count
dunnett_prob <- function(c, lam, cnt, two_sided, g) {
  cs <- c * g$s; p_all <- 1
  for (j in seq_along(lam)) {
    sq <- sqrt(1 - lam[j]^2)
    p <- stats::pnorm((cs - lam[j] * g$z) / sq)
    if (two_sided) p <- p - stats::pnorm((-cs - lam[j] * g$z) / sq)
    p_all <- p_all * if (cnt[j] == 1) p else p^cnt[j]
  }
  sum(g$w * p_all)
}

## The correlations between the comparisons of every mean with the control
## `ctrl`, from the standard errors of the differences S: two comparisons
## share the control, and Cov = (S_i0^2 + S_j0^2 - S_ij^2) / 2.
dunnett_cor <- function(S, ctrl) {
  o <- setdiff(seq_len(nrow(S)), ctrl)
  a <- S[o, ctrl]
  R <- (outer(a^2, a^2, "+") - S[o, o, drop = FALSE]^2) / (2 * outer(a, a))
  diag(R) <- 1
  unname(R)
}

## The loadings of the nearest one-factor form lambda_i lambda_j to the
## correlations R, and how far R departs from it
dunnett_lambda <- function(R) {
  k <- nrow(R)
  if (k == 1) return(list(lambda = sqrt(0.5), departure = 0))
  off <- R; diag(off) <- 0
  lam <- sqrt(pmax(rowSums(off) / (k - 1), 1e-6))
  for (it in seq_len(500)) {
    M <- R; diag(M) <- lam^2
    ev <- eigen(M, symmetric = TRUE)
    new <- sqrt(max(ev$values[1], 0)) * abs(ev$vectors[, 1])
    done <- max(abs(new - lam)) < 1e-14
    lam <- new
    if (done) break
  }
  P <- outer(lam, lam); diag(P) <- 1
  list(lambda = pmin(lam, 1 - 1e-9), departure = max(abs(P - R)))
}

## Dunnett's critical value for comparisons with correlations R on df error
## degrees of freedom, at level alpha, two-sided or one-sided. It lies
## between one comparison's t and Bonferroni's t, whatever the correlations.
dunnett_crit <- function(R, df, alpha, two_sided = TRUE) {
  k <- nrow(R); a1 <- if (two_sided) alpha / 2 else alpha
  if (k == 1) return(list(value = stats::qt(1 - a1, df), exact = TRUE, departure = 0, equal = TRUE))
  fit <- dunnett_lambda(R)
  u <- table(round(fit$lambda, 12))
  lam <- as.numeric(names(u)); cnt <- as.integer(u)
  g <- dunnett_grid(df)
  lo <- stats::qt(1 - a1, df) * 0.999; hi <- stats::qt(1 - a1 / k, df) * 1.001
  root <- stats::uniroot(function(c) dunnett_prob(c, lam, cnt, two_sided, g) - (1 - alpha),
                         c(lo, hi), tol = 1e-9)$root
  list(value = root, exact = fit$departure <= 1e-8, departure = fit$departure,
       equal = length(lam) == 1)
}

## the levels a control can be chosen from: those that vary within one
## family of comparisons (for a sliced interaction, the levels of the other
## factor), in the order of the tables
dunnett_levels <- function(e) {
  vary <- setdiff(e$vars, e$slice)
  unique(apply(e$means[vary], 1, function(z) paste(trimws(z), collapse = " : ")))
}

DUNNETT_ALT <- c(two.sided = "two-sided: does each treatment differ from the control?",
                 greater = "one-sided: is each treatment higher than the control?",
                 less = "one-sided: is each treatment lower than the control?")

## Dunnett's test for effect `e`, in the shape of the other procedures'
## results: the means with each one's verdict against the control, every
## comparison with the control, and the parameters. `fams` are the families
## of means compared together (all of them, or one level of the slicing
## factor at a time).
posthoc_dunnett <- function(e, fams, alpha, control, alternative = "two.sided") {
  if (!alternative %in% names(DUNNETT_ALT)) stop("Unknown alternative.")
  ## the comparisons of a pooled factorial's interaction means with a control
  ## combine different error mean squares, so they have different degrees of
  ## freedom and correlations far from the form the exact calculation needs
  if (!is.null(e$mix))
    stop(sprintf(paste0("Dunnett's test is not available for the %s means of a pooled factorial: their ",
      "comparisons with a control combine different error terms, so Dunnett's critical value cannot be ",
      "computed exactly. Compare them with the control using the LSD or the Bonferroni-adjusted LSD, which ",
      "give each pair its own SE(d), or use Dunnett's test on a main effect."), e$label), call. = FALSE)
  m <- e$means
  vary <- setdiff(e$vars, e$slice)
  lab_vary <- apply(m[vary], 1, function(z) paste(trimws(z), collapse = " : "))
  lab_all <- apply(m[e$vars], 1, paste, collapse = " : ")
  ## as in the app, the first level is the control unless another is named:
  ## a level with no number (Control, Check) sorts first
  if (is.null(control)) control <- dunnett_levels(e)[1]
  if (!control %in% lab_vary)
    stop(sprintf("Choose the control from the levels of %s.", paste(vary, collapse = " x ")))
  two <- alternative == "two.sided"
  within <- if (is.null(e$slice)) NULL else
    vapply(fams, function(ix) as.character(m[[e$slice]][ix[1]]), character(1))
  word <- function(d, sig) if (!sig) switch(alternative, two.sided = "Not significantly different",
                                            greater = "Not significantly higher", less = "Not significantly lower")
                           else if (d > 0) "Significantly higher" else "Significantly lower"
  out <- lapply(seq_along(fams), function(f) {
    ix <- fams[[f]]
    c0 <- ix[lab_vary[ix] == control]
    if (length(c0) != 1) stop(sprintf("The control %s is not in every family of comparisons.", control))
    oth <- setdiff(ix, c0)
    S <- e$sed_mat[c(c0, oth), c(c0, oth), drop = FALSE]
    crit <- dunnett_crit(dunnett_cor(S, 1), e$df, alpha, two)
    d <- m$Mean[oth] - m$Mean[c0]
    sed <- S[-1, 1]
    cd <- crit$value * sed
    sig <- switch(alternative, two.sided = abs(d) > cd, greater = d > cd, less = -d > cd)
    pairs <- data.frame(
      Comparison = paste(lab_all[oth], "vs", lab_all[c0]),
      Difference = d, SEd = sed, `Critical value` = rep(crit$value, length(oth)),
      `Critical difference` = cd, Significant = ifelse(sig, "Yes", "No"),
      check.names = FALSE, stringsAsFactors = FALSE)
    verdict <- vapply(seq_along(oth), function(i) word(d[i], sig[i]), "")
    ord <- oth[order(-m$Mean[oth])]
    g <- data.frame(Treatment = lab_all[c(c0, ord)], Mean = m$Mean[c(c0, ord)],
                    row.names = NULL, check.names = FALSE)
    if (!is.null(m$Raw_mean)) g$`Unadjusted mean` <- m$Raw_mean[c(c0, ord)]
    g <- cbind(g, n = m$N[c(c0, ord)], SE = m$SE[c(c0, ord)],
               `Versus the control` = c("Control", verdict[match(ord, oth)]))
    if (!is.null(within)) { g <- cbind(Within = within[f], g); pairs <- cbind(Within = within[f], pairs) }
    list(groups = g, pairs = pairs, crit = crit, k = length(oth),
         family = list(lab = lab_vary[ix], mu = m$Mean[ix], ctrl = match(c0, ix),
                       d = d, sig = sig, others = match(oth, ix),
                       within = if (is.null(within)) NULL else within[f]))
  })
  groups <- do.call(rbind, lapply(out, `[[`, "groups")); rownames(groups) <- NULL
  pairs <- do.call(rbind, lapply(out, `[[`, "pairs")); rownames(pairs) <- NULL
  crits <- lapply(out, `[[`, "crit")
  cvals <- vapply(crits, `[[`, 0, "value")
  exact <- all(vapply(crits, `[[`, TRUE, "exact"))
  departure <- max(vapply(crits, `[[`, 0, "departure"))
  one_cd <- diff(range(pairs$`Critical difference`)) <= 1e-9 * max(abs(pairs$`Critical difference`))
  st <- data.frame(
    Item = c("Effect", "Method", "Control", "Error mean square", "Error df", "SE of a mean (SEm)",
             "SE of a difference (SEd)", "Comparisons with the control", "Significance level",
             "Critical value (multivariate t)", if (one_cd) "Critical difference (C.D.)" else "Critical difference"),
    Value = c(e$label, paste("Dunnett's test,", DUNNETT_ALT[[alternative]]), control,
              fmt(e$mse, 4), df_text(e$df),
              err_text(e, "sem", 3, html = FALSE), err_text(e, "sed", 3, html = FALSE),
              if (is.null(within)) as.character(out[[1]]$k)
              else sprintf("%d within each level of %s", out[[1]]$k, e$slice),
              p_lab(alpha),
              if (diff(range(cvals)) <= 1e-9 * max(cvals)) fmt(cvals[1]) else sprintf("%s to %s", fmt(min(cvals)), fmt(max(cvals))),
              if (one_cd) fmt(pairs$`Critical difference`[1]) else "varies by comparison - see the comparisons"),
    check.names = FALSE)
  how <- if (!exact)
    sprintf(paste("The missing plots make the correlations between the comparisons slightly uneven: they depart by up to %s",
                  "from the form the exact calculation needs, so the critical value is computed for the nearest correlations",
                  "of that form. This is an approximation; in a test with two missing plots it was within 0.002 of a",
                  "simulation of the exact value."), fmt(departure, 3))
    else if (all(vapply(crits, `[[`, TRUE, "equal")))
      "The comparisons share the control's mean, so they are correlated; the critical value is the quantile of their joint (multivariate t) distribution, computed exactly."
    else "The comparisons share the control's mean, so they are correlated, unequally since the standard errors differ; the critical value is the quantile of their joint (multivariate t) distribution, computed exactly for these correlations."
  list(groups = groups, pairs = pairs, stats = st, how = how, exact = exact, departure = departure,
       crit = cvals, families = lapply(out, `[[`, "family"), alternative = alternative, control = control)
}

## The notes under Dunnett's test, and the result in the shape posthoc()
## returns for every procedure
posthoc_notes <- function(d, e, method, alpha) {
  f_sig <- !is.na(e$p) && e$p < alpha
  note <- c(
    if (!f_sig)
      sprintf(paste0("The F-test for %s is not significant at the %s%% level, so, as everywhere else in DOEpro, ",
                     "no treatment is declared different from the control."), e$label, pct(alpha)),
    if (!is.null(e$slice))
      sprintf("Means are compared with the control within each level of %s%s.", e$slice,
              if (isTRUE(e$by_chosen)) " (simple effects), as chosen"
              else ": these are the only comparisons that share one error term"),
    if (!is.null(e$error_desc)) e$error_desc,
    d$how,
    switch(d$alternative,
      greater = paste("One-sided: only a treatment higher than the control can be declared; one lower than the",
                      "control, however far, is reported as not significantly higher."),
      less = paste("One-sided: only a treatment lower than the control can be declared; one higher than the",
                   "control, however far, is reported as not significantly lower."),
      NULL),
    if (!isTRUE(all.equal(alpha, e$alpha)))
      sprintf(paste0("These comparisons are at the %s%% level, while the analysis and its ",
                     "tables of means are at the %s%% level."), pct(alpha), pct(e$alpha)))
  list(groups = d$groups, stats = d$stats, ranges = NULL, pairs = d$pairs,
       note = note, f_sig = f_sig, alpha = alpha, method = PH_LABELS[[method]], families = d$families,
       dunnett = list(alternative = d$alternative, control = d$control, crit = d$crit,
                      exact = d$exact, departure = d$departure))
}

## ---------------------------------------------------------- comparisons.R ----
###############################################################################
##  MEANS AND COMPARISONS
###############################################################################
## What a table of means shows follows the comparison chosen, and only it:
##   - the means alone, with SE(m) and SE(d) at the foot;
##   - the critical difference (C.D., Fisher's protected LSD) at the foot,
##     and no letters;
##   - superscript letters from a multiple-comparison procedure (Tukey's
##     HSD, Duncan's, Student-Newman-Keuls, Scheffe's, the Bonferroni-
##     adjusted LSD), and no C.D.;
##   - Dunnett's test against a control, as a table of comparisons.
## A C.D. and letters are never shown together: they come from different
## procedures, and printing both invites reading one by the other's rule.
## The calculations stay in the engine (analyze(), posthoc()); this file
## decides what is shown. Letters and verdicts appear only when the effect's
## F-test is significant at the chosen level, as everywhere in DOEpro.

## the choices, as the Means & Comparisons tab offers them
CMP_CHOICES <- c(
  "Means only (no comparisons)" = "none",
  "Critical difference, C.D. (Fisher's protected LSD)" = "LSD (Fisher's protected)",
  "Tukey's HSD (letters)" = "Tukey HSD",
  "Duncan's multiple range test, DMRT (letters)" = "Duncan's DMRT",
  "Student-Newman-Keuls test, SNK (letters)" = "Student-Newman-Keuls",
  "Scheffe's test (letters)" = "Scheffe",
  "Bonferroni-adjusted LSD (letters)" = "LSD (Bonferroni-adjusted)",
  "Dunnett's test (each treatment against a control)" = "Dunnett")

## each procedure as running text names it
CMP_NAME <- c(
  "none" = "no comparison",
  "LSD (Fisher's protected)" = "Fisher's protected LSD",
  "Tukey HSD" = "Tukey's HSD",
  "Duncan's DMRT" = "Duncan's multiple range test (DMRT)",
  "Student-Newman-Keuls" = "the Student-Newman-Keuls (SNK) test",
  "Scheffe" = "Scheffe's test",
  "LSD (Bonferroni-adjusted)" = "the Bonferroni-adjusted LSD",
  "Dunnett" = "Dunnett's test")

## what the tables show for a procedure: "none", "cd", "letters" or "dunnett"
cmp_kind <- function(method) {
  if (is.null(method) || !nzchar(method) || identical(method, "none")) "none"
  else if (identical(method, "LSD (Fisher's protected)")) "cd"
  else if (identical(method, "Dunnett")) "dunnett"
  else "letters"
}

#' The comparison shown with the tables of means
#'
#' Describes how the tables of means of \code{\link{build_report}} (and of the
#' application) compare the means: not at all, by the critical difference
#' (Fisher's protected LSD), by the letters of a multiple-comparison
#' procedure, or by Dunnett's test against a control. Letters and a critical
#' difference are never shown together.
#'
#' @param method \code{"none"} for the means alone, or one of the
#'   multiple-comparison procedures: \code{"LSD (Fisher's protected)"} (shown as the
#'   C.D.), \code{"LSD (Bonferroni-adjusted)"}, \code{"Tukey HSD"},
#'   \code{"Duncan's DMRT"}, \code{"Student-Newman-Keuls"}, \code{"Scheffe"}
#'   (shown as letters) or \code{"Dunnett"}.
#' @param control For Dunnett's test, the control level; the first level when
#'   \code{NULL}.
#' @param alternative For Dunnett's test: \code{"two.sided"}, \code{"greater"}
#'   or \code{"less"}.
#' @param effect For Dunnett's test, the effect whose levels include the
#'   control; the first main effect when \code{NULL}.
#'
#' @return A list with the method, what the tables show (\code{kind}) and the
#'   settings of Dunnett's test.
#'
#' @examples
#' rr <- run_all(demo_data("CRD"), "CRD", list(treat = "Treatment"), "Yield")
#' html <- build_report(rr, comparison = comparison("Tukey HSD"))
#'
#' @export
comparison <- function(method = "none", control = NULL, alternative = "two.sided", effect = NULL) {
  method <- if (is.null(method) || !nzchar(method)) "none" else method
  if (!method %in% c("none", PH_METHODS))
    stop(sprintf("Unknown comparison '%s'. Use \"none\" or one of: %s.", method,
                 paste(sprintf("\"%s\"", PH_METHODS), collapse = ", ")), call. = FALSE)
  list(method = method, kind = cmp_kind(method), control = control,
       alternative = alternative %||% "two.sided", effect = effect)
}

## The letters of `effect` by the chosen procedure, in the order of its table
## of means: empty when the procedure gives no letters or the F-test is not
## significant. `x` is the procedure's result, for the readings; `err` says
## why letters could not be worked out (Tukey's test with one error degree
## of freedom, for instance).
cmp_letters <- function(res, effect, cmp, by = NULL) {
  e <- res$effects[[effect]]
  out <- list(letters = rep("", nrow(e$means)), x = NULL, err = NULL)
  if (!identical(cmp$kind, "letters")) return(out)
  x <- tryCatch(posthoc(res, effect, cmp$method, e$alpha, by = by), error = function(err) err)
  if (inherits(x, "error")) { out$err <- conditionMessage(x); return(out) }
  x <- gate_posthoc(x)
  out$letters <- x$letters
  out$x <- x
  out
}

## a mean as a table prints it: back-transformed with the transformed value
## in parentheses when there is a transformation, and its letter, if any
cmp_cell <- function(mu, letter = "", digits = 2, mu_bt = NULL) {
  letter[is.na(letter)] <- ""
  if (is.null(mu_bt)) paste0(fmt(mu, digits), sup(letter))
  else paste0(fmt(mu_bt, digits), " (", fmt(mu, digits), ")", sup(letter))
}

## what a table's caption says it shows
cmp_caption <- function(cmp, alpha, any_tr = FALSE) {
  what <- switch(cmp$kind,
    none = "means",
    cd = "means, with the critical difference (C.D.) at the foot",
    letters = sprintf("means, with letters from %s at the %s%% level", CMP_NAME[[cmp$method]], pct(alpha)),
    dunnett = "means (the comparisons with the control follow)")
  paste0(" &mdash; ", what,
         if (any_tr) "; for a transformed response, the back-transformed mean with the transformed value in parentheses" else "")
}

## The rows at the foot of a table of means: SE(m) and SE(d) always, the
## C.D. only when the comparison is the C.D., and the CV. `within` qualifies
## the single figures of an interaction compared within one factor's levels.
cmp_foot_rows <- function(e, cmp, digits, cv_text = NULL, within = "") {
  c(list(c(paste0("SE(m) &plusmn;", within), err_text(e, "sem", digits)),
         c(paste0("SE(d) &plusmn;", within), err_text(e, "sed", digits))),
    if (identical(cmp$kind, "cd")) list(c(paste0(cd_name(e$alpha), within), cd_or_ns(e, digits))),
    if (!is.null(cv_text)) list(c("C.V. (%)", cv_text)))
}

## An effect's further comparisons (split, strip and pooled interactions):
## each SE(d) always, each C.D. only when the comparison is the C.D.
cmp_extra <- function(e, cmp, digits = 3) {
  xt <- extra_text(e, digits)
  if (!length(xt) || identical(cmp$kind, "cd")) return(xt)
  xt[startsWith(names(xt), "SE(d)")]
}

## The note under a table of means: what its letters compare, and why a
## response has none
cmp_letters_note <- function(cmp, e, L, header = NULL) {
  if (!identical(cmp$kind, "letters")) return(character(0))
  who <- if (is.null(header)) "" else sprintf(" for %s", header)
  if (!is.null(L$err))
    return(sprintf("%s cannot be applied%s: %s", cap1(CMP_NAME[[cmp$method]]), who, L$err))
  if (!effect_sig(e))
    return(sprintf("No letters%s: the F-test for %s is not significant at the %s%% level.", who, e$label, pct(e$alpha)))
  character(0)
}

## the letters' rule, at the foot of the section
cmp_rule <- function(cmp, alpha) {
  switch(cmp$kind,
    none = paste("No comparison is made: the F-test says whether the means differ at all, and a comparison",
                 "method, chosen above, says which differ."),
    cd = sprintf(paste("Two means differ significantly at the %s%% level when their difference is larger than the C.D.",
                       "(Fisher's protected LSD); NS means the F-test is not significant at that level, so no C.D. is given."),
                 pct(alpha)),
    letters = sprintf(paste("Means sharing a letter do not differ significantly by %s at the %s%% level. Letters are given",
                            "only where the F-test is significant at that level."), CMP_NAME[[cmp$method]], pct(alpha)),
    dunnett = sprintf("Each treatment is compared with the control by Dunnett's test at the %s%% level; the comparisons follow the tables.",
                      pct(alpha)))
}

## ------------------------------------------------------------ readings ----

## The reading of a table of means without comparisons: the highest and
## lowest mean as printed and the F-test's verdict
means_only_text <- function(e, digits = 2, tr = "none", cmp = comparison()) {
  a <- e$alpha; lvl <- rd_lvl(a); v <- paste(e$vars, collapse = " x ")
  lab <- apply(e$means[e$vars], 1, function(z) paste(trimws(z), collapse = " x "))
  k <- length(lab); shown <- rd_shown(e, tr); pr <- fmt(shown, digits)
  top <- at_extreme(pr, max); bot <- at_extreme(pr, min)
  ends <- if (length(top) == k) sprintf("All %d %s means print as %s.", k, v, pr[1])
    else if (k == 2) sprintf("%s has the higher mean (%s) and %s the lower (%s).", lab[top], pr[top], lab[bot], pr[bot])
    else sprintf("%s %s the highest mean (%s) and %s %s the lowest (%s).", join_and(lab[top]),
                 pl(length(top), "has", "share"), pr[top[1]], join_and(lab[bot]), pl(length(bot), "has", "share"), pr[bot[1]])
  if (is.na(e$p)) return(ends)
  verdict <- if (effect_sig(e))
    sprintf("The F-test for %s is %s: there is evidence that the %s means are not all equal.%s", e$label, rd_sig(e$p, a), v,
            switch(cmp$kind, none = " Choose a comparison method to see which of them differ.",
                   dunnett = " Dunnett's comparisons with the control follow.", ""))
  else sprintf("The F-test for %s is %s: there is insufficient evidence that the %s means differ%s.", e$label, rd_sig(e$p, a), v,
               if (identical(cmp$kind, "letters")) ", so no letters are given" else "")
  paste(ends, verdict)
}

## The reading of a one-factor table of means, as the comparison chosen
## judges it: the C.D. reading, the procedure's own verdicts, or the means
## and the F-test alone. A significant interaction involving the factor is
## pointed out.
cmp_means_text <- function(fit, effect, cmp, digits = 2, L = NULL) {
  r <- fit$final; e <- r$effects[[effect]]; tr <- fit$trans
  if (exact_fit(r)) return(RD_EXACT)
  note <- rd_avg_note(r, e$vars)
  body <- switch(cmp$kind,
    cd = means_body(e, digits, tr),
    letters = {
      L <- L %||% cmp_letters(r, effect, cmp)
      if (!is.null(L$err)) paste(means_only_text(e, digits, tr, comparison()),
                                 sprintf("%s cannot be applied here: %s", cap1(CMP_NAME[[cmp$method]]), L$err))
      else if (!effect_sig(e)) means_only_text(e, digits, tr, cmp)
      else posthoc_groups_text(L$x, e, tr, digits = digits)
    },
    means_only_text(e, digits, tr, cmp))
  if (nzchar(note)) paste(body, note) else body
}

## The reading of a two-way table of means: the interaction's pattern, then
## how the cells are compared under the procedure chosen
cmp_twoway_text <- function(fit, f1, f2, cmp, digits = 2, L = NULL, cd_digits = digits) {
  r <- fit$final; key <- paste0(f1, ":", f2); e <- r$effects[[key]]; tr <- fit$trans
  if (is.null(e) || is.na(e$p)) return("")
  if (cmp$kind == "cd") return(twoway_text(r, e, f1, f2, digits, tr, cd_digits))
  base <- twoway_text(r, e, f1, f2, digits, tr, cd_digits, rule = "")
  if (exact_fit(r) || !effect_sig(e) || cmp$kind != "letters") return(base)
  L <- L %||% cmp_letters(r, key, cmp)
  if (!is.null(L$err)) return(paste(base, sprintf("%s cannot be applied here: %s", cap1(CMP_NAME[[cmp$method]]), L$err)))
  paste(base, posthoc_groups_text(L$x, e, tr, digits = digits))
}

## ------------------------------------------------- comparisons of an effect --

## The comparisons of one effect of one response by the procedure chosen,
## as HTML: the error term, the means with their verdicts, the procedure's
## parameters and every comparison, each followed by its reading. `by` is
## the factor within whose levels an interaction is compared (simple effects).
cmp_effect_html <- function(fit, effect, cmp, by = NULL) {
  r <- fit$final; e <- r$effects[[effect]]
  if (is.null(e)) return("")
  head <- sprintf("<h4 class='slx-resp'>%s</h4>", esc(fit$header))
  if (identical(cmp$kind, "none"))
    return(paste0(head, "<div class='note'>Choose a comparison method above to compare these means.</div>"))
  x <- tryCatch(posthoc(r, effect, cmp$method, e$alpha, control = cmp$control,
                        alternative = cmp$alternative %||% "two.sided", by = by),
                error = function(err) list(err = conditionMessage(err)))
  if (!is.null(x$err)) return(paste0(head, "<div class='err'>", esc(x$err), "</div>"))
  x <- gate_posthoc(x)
  eb <- effect_by(e, by)
  exact <- exact_fit(r)
  err_box <- if (is.null(e$mix)) sprintf(
      "Comparisons use the error term of <b>%s</b>: error mean square %s on %s degrees of freedom, at the %s%% significance level.",
      esc(e$label), fmt(e$mse, 4), df_text(e$df), pct(e$alpha))
    else sprintf(paste("Comparisons of <b>%s</b> means use, for each pair, the environment interactions of the factors",
                       "in which the two differ, with Satterthwaite's degrees of freedom for each pair, at the %s%% significance level."),
                 esc(e$label), pct(e$alpha))
  g <- x$groups
  if (cmp$kind == "cd") g$Group <- NULL
  names(g)[names(g) == "Group"] <- "Letters"
  lsd <- if (isTRUE(x$f_sig) && cmp$method != "LSD (Fisher's protected)")
    tryCatch(posthoc(r, effect, "LSD (Fisher's protected)", e$alpha, by = by), error = function(err) NULL)
  ranges <- if (is.null(x$ranges)) "" else paste0(
    df_html(x$ranges, caption = "Critical ranges"),
    "<div class='note'>p is the number of means spanned by the comparison once the means are ranked in order.</div>")
  paste0(head,
    sprintf("<div class='box'><b>What the test does.</b> %s<br>%s</div>", esc(PH_WHAT[[cmp$method]]), err_box),
    if (length(x$note)) paste0("<div class='warn'>", paste(x$note, collapse = "<br><br>"), "</div>") else "",
    df_html(g, caption = if (cmp$kind == "dunnett") "Each treatment against the control" else "The means, highest first"),
    rd_html(posthoc_groups_text(x, eb, fit$trans, exact), "What the comparisons show."),
    "<details class='slx-fold'><summary>Every comparison, and the test's parameters</summary>",
    df_html(x$stats, caption = "Test parameters"), ranges,
    df_html(x$pairs, caption = if (cmp$kind == "dunnett") "Comparisons with the control" else "Every pair of means"),
    rd_html(posthoc_pairs_text(x, eb, cmp$method, lsd, exact)),
    "</details>")
}

## --------------------------------------------------------------- exports ----

## One row per mean of every effect, for the CSV of the Means tab. The
## columns follow the comparison chosen: the C.D. only with the C.D., the
## letters only with a letter procedure. SEm is that mean's own standard
## error (for a split, strip or pooled interaction, the SE(m) for comparing
## means within one level of its slicing factor); SEd and the C.D. are given
## only when one value applies to every pair they describe.
means_csv <- function(rr, cmp = comparison()) {
  out <- do.call(rbind, lapply(names(rr$fits), function(nm) {
    fit <- rr$fits[[nm]]; r <- fit$final
    do.call(rbind, lapply(names(r$effects), function(en) {
      e <- r$effects[[en]]; m <- e$means
      L <- cmp_letters(r, en, cmp)
      xt <- cmp_extra(e, cmp)
      note <- c(
        if (is.na(e$sed)) "SEd differs between pairs of means; the comparisons on the Means & Comparisons tab list each pair."
        else if (!isTRUE(e$equal_rep)) "SEm differs between means.",
        if (!is.null(e$slice))
          sprintf("SEd%s apply to means at the same level of %s. %s", if (cmp$kind == "cd") " and CD" else "", e$slice,
                  paste(sprintf("%s = %s", names(xt), xt), collapse = "; ")),
        cmp_letters_note(cmp, e, L))
      out <- data.frame(
        Response = nm, Transformation = TRANS[[fit$trans]]$lab, Effect = e$label,
        Level = apply(m[e$vars], 1, paste, collapse = " x "),
        Mean = m$Mean,
        Unadjusted_mean = if ("Raw_mean" %in% names(m)) m$Raw_mean else NA_real_,
        Back_transformed = if ("Mean_bt" %in% names(m)) m$Mean_bt else NA_real_,
        N = m$N, SD = m$SD, SEm = m$SE, SEd = e$sed,
        alpha = e$alpha, p_value = e$p, Comparison = if (cmp$kind == "none") "None" else CMP_NAME[[cmp$method]],
        row.names = NULL, check.names = FALSE, stringsAsFactors = FALSE)
      if (cmp$kind == "cd") out$CD <- if (effect_sig(e)) e$cd else NA_real_
      if (cmp$kind == "letters") out$Letters <- L$letters
      out$Note <- paste(note, collapse = " ")
      out
    }))
  }))
  rownames(out) <- NULL
  out
}

## ---------------------------------------------------------- plots.R ----
###############################################################################
##  PLOTS
###############################################################################
## One look for every plot in the app: white ground, light horizontal guides,
## the brand's navy for text and its blue for single series, and a palette
## that colour-blind readers can tell apart for groups. Colour is kept for
## what it means: red marks rows the checks pick out, nothing else.
SLX_BLUE <- "#3B7DD8"
SLX_NAVY <- "#14284B"
SLX_FILL <- "#BBD3F2"
SLX_RED  <- "#C0392B"
## Okabe and Ito's colour-blind-safe palette, starting with blues
SLX_PAL <- c("#0072B2", "#E69F00", "#009E73", "#CC79A7", "#56B4E9", "#D55E00", "#6B6B6B", "#F0E442")

## the colours for k groups: the palette while it lasts, evenly spaced hues after
slx_pal <- function(k) if (k <= length(SLX_PAL)) SLX_PAL[seq_len(k)] else grDevices::hcl.colors(k, "Dark 3")

## The heat maps of coefficients and loadings: red below 0, the brand's blues
## above, through clear tints, so a middling value reads as a light red or
## blue rather than a grey. Deeper colour is always further from 0.
SLX_DIVERGE <- c("#B93A2E", "#EE9A8E", "#F7F7F7", "#9CC3FF", "#3B7DD8", "#1F5FC4")
scale_fill_diverge <- function(limits, name, ...)
  scale_fill_gradientn(colours = SLX_DIVERGE, values = c(0, 0.3, 0.5, 0.68, 0.86, 1),
                       limits = limits, name = name, ...)

theme_doe <- function(base_size = 13) {
  theme_minimal(base_size = base_size) +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major = element_line(colour = "#E8EDF5", linewidth = 0.45),
          axis.line = element_line(colour = "#9AA9C0", linewidth = 0.45),
          axis.ticks = element_line(colour = "#9AA9C0", linewidth = 0.45),
          axis.text = element_text(colour = "#3D4B63"),
          axis.title = element_text(colour = "#1C2B4A"),
          legend.position = "bottom",
          legend.title = element_text(colour = "#1C2B4A", face = "bold", size = rel(0.85)),
          legend.text = element_text(colour = "#3D4B63", size = rel(0.85)),
          plot.title = element_text(face = "bold", size = rel(1.02), colour = SLX_NAVY, margin = margin(b = 4)),
          plot.subtitle = element_text(colour = "#5B6B86", size = rel(0.85), margin = margin(b = 6)),
          plot.caption = element_text(colour = "#5B6B86", size = rel(0.68), hjust = 0, lineheight = 1.15),
          plot.title.position = "plot", plot.caption.position = "plot",
          strip.text = element_text(face = "bold", colour = SLX_NAVY),
          plot.background = element_rect(fill = "white", colour = NA),
          panel.background = element_rect(fill = "white", colour = NA),
          plot.margin = margin(10, 14, 8, 10))
}

## when the response was transformed, say so on the plot
scale_note <- function(res) {
  if (is.null(res$trans) || identical(res$trans, "none")) return(NULL)
  paste("Transformed scale:", TRANS[[res$trans]]$lab)
}

## What the error bars and letters on a plot of means mean, at the chosen level.
## For a split, strip or pooled interaction both differ: the bars are the SE(m)
## for comparing means at the same level of the slicing factor, and the letters
## restart in each of its levels. `lets_on` is FALSE, TRUE, or the name of the
## procedure the letters come from.
plot_caption <- function(e, bars, lets_on) {
  sl <- e$slice
  by <- if (is.character(lets_on)) paste0(" by ", lets_on) else ""
  bars <- if (!bars) NULL
          else if (is.null(sl)) "Error bars: one standard error either side of each mean."
          else sprintf("Error bars: SE(m) for comparing means at the same level of %s (SE(d) / sqrt(2)).", sl)
  lets <- if (isFALSE(lets_on)) NULL
          else if (!effect_sig(e))
            sprintf("No letters: the F-test is not significant at the %s%% level.", pct(e$alpha))
          else if (is.null(sl))
            sprintf("Means sharing a letter are not significantly different%s at the %s%% level.", by, pct(e$alpha))
          else sprintf(paste0("Letters compare means within the same level of %s only; there, ",
                              "means sharing a letter are not significantly different%s at the %s%% level."),
                       sl, by, pct(e$alpha))
  if (is.null(c(bars, lets))) NULL else paste(c(bars, lets), collapse = " ")
}

## a caption broken into lines that fit under the plot
wrap_cap <- function(x) if (is.null(x)) NULL else paste(strwrap(x, 110), collapse = "\n")

## How strongly a factor asks to be the X-axis of an interaction plot. Only
## numbered labels qualify: their natural order is their order in time or
## size, whereas worded labels (Vegetative, Flowering) sort alphabetically and
## a line through them would run in the wrong order. Time comes first,
## recognised by the column name (Days, Week, Stage, Interval...) or by a
## common stem (D0, D60; Week1, Week2; 30 DAS). Next come labels that carry
## real quantities (N0, N60, N120; 2021, 2022; 0, 25, 50) rather than mere
## numbering (T1, T2, V1, V2, V4), which is read as codes. One unnumbered label
## such as Control or Fresh may sit among the numbered ones.
TIME_NAME <- "(^|[^a-z])(day|days|das|dat|dae|doy|time|week|weeks|month|months|year|years|stage|stages|interval|period|storage|hour|hours|date)([^a-z]|$)"
TIME_STEM <- "^(d|day|days|das|dat|dap|dae|doy|h|hr|hrs|hour|hours|wk|wks|week|weeks|month|months|yr|yrs|year|years)$"

x_score <- function(name, lv) {
  num <- "[0-9]+(?:[.][0-9]+)?"
  cnt <- lengths(regmatches(lv, gregexpr(num, lv, perl = TRUE)))
  lab <- lv[cnt == 1]
  if (length(lab) < 2 || any(cnt > 1) || sum(cnt == 0) > 1) return(0)
  stem <- unique(gsub("[^a-z]", "", tolower(gsub(num, "", lab, perl = TRUE))))
  one_stem <- length(stem) == 1
  n <- sort(as.numeric(regmatches(lab, regexpr(num, lab, perl = TRUE))))
  step <- diff(n)
  ## codes: whole numbers starting at 0 or 1 that either run 1, 2, 3 or skip
  ## unevenly (a dropped entry: V1, V2, V4); evenly spaced rates (0, 2, 4;
  ## 0, 40, 80) and other values are quantities
  counting <- anyDuplicated(n) > 0 ||
    (all(n == round(n)) && n[1] %in% c(0, 1) &&
     (all(step == 1) || length(unique(round(step, 9))) > 1))
  ## a one-letter stem (D, H) counts as time only on real quantities, so D0,
  ## D60 and H6, H12 are times while the dose codes D1, D2 and hybrids H1, H2
  ## are not
  stem_time <- one_stem && grepl(TIME_STEM, stem) && (nchar(stem) > 1 || !counting)
  is_time <- grepl(TIME_NAME, tolower(name)) || stem_time
  2 * is_time + (one_stem && !counting)
}

## The factor that goes on the X-axis by default: the best-scoring one above,
## the one with more levels on a tie, and otherwise the effect's first factor.
default_x <- function(e, d) {
  v <- e$vars
  sc <- vapply(v, function(f) x_score(f, levels(d[[f]])), numeric(1))
  if (max(sc) <= 0) return(v[1])
  cand <- v[sc == max(sc)]
  cand[which.max(vapply(cand, function(f) nlevels(d[[f]]), numeric(1)))]
}

## `x_var` names the factor for the X-axis of an interaction plot; by default
## default_x() chooses it. The other factor becomes the lines (or the bar
## colours), and any further factors become panels. `letters` holds a letter
## for each mean, in the order of the effect's table of means (from the
## comparison chosen), or is NULL for none; `method` names the procedure they
## come from, for the caption.
plot_main <- function(res, effect, type = "bar", letters = NULL, x_var = NULL, method = NULL) {
  e <- res$effects[[effect]]; d <- res$data; resp <- res$resp
  m <- e$means
  v <- e$vars
  show <- length(letters) == nrow(m) && effect_sig(e) && any(nzchar(letters))
  m$.let <- if (show) letters else rep("", nrow(m))
  m$.se <- m$SE                     # each mean's own SE: replication may differ
  lets_on <- if (!length(letters)) FALSE else if (!is.null(method)) method else TRUE

  if (length(v) == 1) {
    p <- ggplot(m, aes(x = .data[[v]], y = Mean)) +
      (if (type == "bar")
        geom_col(fill = SLX_BLUE, width = .62)
       else if (type == "box")
        geom_boxplot(data = d, aes(x = .data[[v]], y = .data[[resp]]),
                     fill = SLX_FILL, colour = SLX_NAVY, inherit.aes = FALSE, width = .6)
       else geom_point(size = 3.2, colour = SLX_BLUE)) +
      (if (type != "box") geom_errorbar(aes(ymin = Mean - .se, ymax = Mean + .se),
                                        width = .15, colour = SLX_NAVY) else NULL) +
      (if (show && type != "box")
        geom_text(aes(y = Mean + .se, label = .let), vjust = -0.6, size = 4.3, colour = SLX_NAVY) else NULL) +
      scale_y_continuous(expand = expansion(mult = c(if (type == "bar" && all(m$Mean - m$.se >= 0)) 0 else 0.05, 0.12))) +
      labs(title = paste("Effect of", v, "on", resp), y = resp, x = v,
           subtitle = scale_note(res),
           caption = wrap_cap(plot_caption(e, type != "box", if (type == "box") FALSE else lets_on))) +
      theme_doe()
    return(p)
  }

  f1 <- if (length(x_var) == 1L && isTRUE(x_var %in% v)) x_var else default_x(e, d)
  rest <- setdiff(v, f1)
  f2 <- rest[1]
  pal <- slx_pal(nlevels(factor(m[[f2]])))
  base <- ggplot(m, aes(x = .data[[f1]], y = Mean, fill = .data[[f2]],
                        colour = .data[[f2]], group = .data[[f2]]))
  p <- switch(type,
    "bar" = base + geom_col(position = position_dodge(.8), width = .72, colour = NA) +
      geom_errorbar(aes(ymin = Mean - .se, ymax = Mean + .se),
                    position = position_dodge(.8), width = .2, colour = "grey30") +
      (if (show) geom_text(aes(y = Mean + .se, label = .let),
        position = position_dodge(.8), vjust = -0.5, size = 3.9, colour = SLX_NAVY) else NULL) +
      scale_y_continuous(expand = expansion(mult = c(if (all(m$Mean - m$.se >= 0)) 0 else 0.05, 0.12))),
    "line" = base + geom_line(linewidth = 1) + geom_point(size = 3) +
      geom_errorbar(aes(ymin = Mean - .se, ymax = Mean + .se), width = .12),
    "heat" = ggplot(m, aes(x = .data[[f1]], y = .data[[f2]], fill = Mean)) +
      geom_tile(colour = "white", linewidth = 0.8) +
      geom_text(aes(label = fmt(Mean, 1)), colour = SLX_NAVY, size = 4) +
      scale_fill_gradient(low = "#EAF1FB", high = "#3B7DD8"),
    "box" = ggplot(d, aes(x = .data[[f1]], y = .data[[resp]], fill = .data[[f2]])) +
      geom_boxplot(position = position_dodge(.8), colour = "grey25"))
  if (type != "heat") p <- p + scale_fill_manual(values = pal) + scale_colour_manual(values = pal)
  if (length(rest) > 1) p <- p + facet_wrap(stats::as.formula(
    paste("~", paste(rest[-1], collapse = "+"))))
  p <- p + labs(title = paste("Interaction:", e$label), y = resp, x = f1,
                colour = if (type %in% c("bar", "line")) f2, subtitle = scale_note(res),
                caption = wrap_cap(plot_caption(e, type %in% c("bar", "line"),
                                                if (type == "bar") lets_on else FALSE))) + theme_doe()
  if (type == "heat") p + labs(fill = paste("Mean", resp), y = f2) else p + labs(fill = f2)
}

## ------------------------------------------------------- interaction plot ----

## Can the cell means of effect `e` carry confidence intervals? Only when
## each mean's own standard error is known, as in a design with one error
## term. The SE of a split, strip or pooled interaction's cell is the SE(m)
## for comparing means within one level of its slicing factor, not the
## standard error of the cell mean on its own, and a pooled factorial's
## carries several environment interactions; intervals built from either
## would be wrong.
ci_ok <- function(e) is.null(e$slice) && is.null(e$mix) && !isTRUE(e$is_gxe)

## why an effect's cell means carry no confidence intervals
ci_why <- function(e) {
  if (!is.null(e$mix)) "in a pooled factorial each cell mean carries several environment interactions, so it has no single standard error"
  else if (!is.null(e$slice)) sprintf(paste("the standard error printed for these means is the one for comparing them within the same",
                                            "level of %s, not the standard error of each mean on its own"), e$slice)
  else ""
}

## The interaction plot: one line for each level of the second factor across
## the levels of the factor on the X-axis, with each cell mean's confidence
## interval at the analysis's level where one can be given (ci_ok()).
plot_interaction <- function(res, effect, x_var = NULL, ci = TRUE) {
  e <- res$effects[[effect]]; v <- e$vars; m <- e$means; resp <- res$resp
  if (length(v) < 2) return(NULL)
  f1 <- if (length(x_var) == 1L && isTRUE(x_var %in% v)) x_var else default_x(e, res$data)
  rest <- setdiff(v, f1); f2 <- rest[1]
  ci <- isTRUE(ci) && ci_ok(e)
  tq <- stats::qt(1 - e$alpha / 2, e$df)
  m$lo <- m$Mean - tq * m$SE; m$hi <- m$Mean + tq * m$SE
  pd <- position_dodge(width = if (ci) 0.18 else 0)
  k <- nlevels(factor(m[[f2]]))
  p <- ggplot(m, aes(x = .data[[f1]], y = Mean, colour = .data[[f2]], group = .data[[f2]], shape = .data[[f2]])) +
    (if (ci) geom_errorbar(aes(ymin = .data$lo, ymax = .data$hi), width = 0.14, linewidth = 0.6, position = pd) else NULL) +
    geom_line(linewidth = 1, position = pd) + geom_point(size = 3.1, position = pd) +
    scale_colour_manual(values = slx_pal(k)) +
    scale_shape_manual(values = rep(c(16, 17, 15, 18, 1, 2, 0, 5), length.out = k))
  if (length(rest) > 1) p <- p + facet_wrap(stats::as.formula(paste("~", paste(rest[-1], collapse = "+"))))
  cap <- if (ci) sprintf("Error bars: %s%% confidence interval of each cell mean (t on %s error d.f. times its standard error).",
                         pct(1 - e$alpha), df_text(e$df))
         else if (isTRUE(ci_ok(e))) NULL
         else sprintf("No confidence intervals: %s.", ci_why(e))
  p + labs(title = sprintf("Interaction of %s", paste(v, collapse = " and ")), x = f1, y = resp,
           colour = f2, shape = f2, subtitle = scale_note(res),
           caption = wrap_cap(cap)) +
    theme_doe()
}

## "What it shows" and the reading of the interaction plot: the pattern the
## lines draw, judged against the interaction's F-test, never on the lines alone
interaction_text <- function(res, effect, x_var = NULL, ci = TRUE, digits = 2) {
  e <- res$effects[[effect]]
  if (is.null(e) || length(e$vars) < 2) return(NULL)
  f1 <- if (length(x_var) == 1L && isTRUE(x_var %in% e$vars)) x_var else default_x(e, res$data)
  f2 <- setdiff(e$vars, f1)[1]
  ci <- isTRUE(ci) && ci_ok(e)
  scale <- if (is.null(res$trans) || identical(res$trans, "none")) "" else ", on the transformed scale,"
  what <- paste0(sprintf("Each line joins the means%s of one level of %s across the levels of %s.", scale, f2, f1),
                 if (ci) sprintf(paste(" The bars are %s%% confidence intervals for each cell mean: they show how precisely each mean",
                                       "is known, and two intervals that overlap can still belong to means that differ significantly."),
                                 pct(1 - e$alpha))
                 else if (!ci_ok(e)) sprintf(" No confidence intervals are drawn: %s.", ci_why(e)) else "",
                 if (length(e$vars) > 2) sprintf(" Each panel is one level of %s.", join_and(setdiff(e$vars, c(f1, f2)))) else "")
  base <- main_plot_text(res, effect, "line", FALSE, f1, digits)
  list(what = what, reading = base$reading)
}

## The residuals are standardised (divided by their standard deviation), the
## scale on which the assumption checks flag a value beyond -3 or 3; those
## points are labelled with their row numbers in the data table.
plot_diag <- function(res) {
  df <- data.frame(fit = res$fitted, res = res$resid,
                   std = res$resid / stats::sd(res$resid), row = row_ids(res$data))
  far <- df[reg_far(df$std), , drop = FALSE]
  p1 <- ggplot(df, aes(fit, std)) + geom_hline(yintercept = 0, lty = 2, colour = "#5B6B86") +
    geom_hline(yintercept = c(-3, 3), linetype = 3, colour = "grey45") +
    geom_point(colour = SLX_BLUE, size = 2.2, alpha = 0.85) +
    (if (nrow(far)) geom_text(data = far, aes(label = paste("row", .data$row), vjust = ifelse(.data$std > 0, -0.8, 1.8)),
                              size = 3.4, colour = SLX_RED)) +
    scale_y_continuous(expand = expansion(mult = 0.12)) +
    labs(title = "Residuals against fitted values", x = "Fitted value", y = "Standardised residual") + theme_doe()
  p2 <- ggplot(df, aes(sample = std)) + stat_qq(colour = SLX_BLUE, size = 2.2) + stat_qq_line(colour = SLX_RED) +
    labs(title = "Normal Q-Q plot of the residuals", x = "Theoretical quantile", y = "Standardised residual") + theme_doe()
  p3 <- ggplot(df, aes(res)) + geom_histogram(bins = 12, fill = SLX_FILL, colour = "white") +
    labs(title = "Histogram of the residuals", x = "Residual", y = "Count") + theme_doe()
  ## With only a few distinct fitted values (a CRD has one per treatment) a
  ## loess curve swings between them and rises where there are no points, so
  ## the trend joins the mean at each fitted value instead.
  df$sl <- sqrt(abs(df$std))
  df$at <- signif(df$fit, 10)
  trend <- if (length(unique(df$at)) <= 10) {
    m <- stats::aggregate(sl ~ at, data = df, FUN = mean)
    geom_line(data = m, aes(.data$at, .data$sl), colour = SLX_RED, linewidth = 0.9)
  } else geom_smooth(se = FALSE, method = "loess", formula = y ~ x,
                     method.args = list(degree = 1), colour = SLX_RED)
  p4 <- ggplot(df, aes(.data$fit, .data$sl)) + geom_point(colour = SLX_BLUE, size = 2.2, alpha = 0.85) + trend +
    labs(title = "Scale-location", x = "Fitted value", y = "sqrt|standardised residual|") + theme_doe()
  list(p1, p2, p3, p4)
}

plot_boxcox <- function(asm) {
  bc <- asm$bc
  if (is.null(bc)) return(NULL)
  df <- data.frame(lambda = bc$x, loglik = bc$y)
  df <- df[stats::complete.cases(df), ]
  ggplot(df, aes(lambda, loglik)) +
    geom_line(colour = SLX_BLUE, linewidth = 1) +
    geom_vline(xintercept = bc$lambda, colour = SLX_RED, lty = 2) +
    geom_vline(xintercept = bc$ci, colour = "grey55", lty = 3) +
    annotate("text", x = bc$lambda, y = min(df$loglik), vjust = -0.4, hjust = -0.1,
             label = sprintf("lambda = %.2f", bc$lambda), colour = SLX_RED, size = 3.6) +
    labs(title = sprintf("Box-Cox profile (optimal lambda = %.2f, %s%% CI %.2f to %.2f)",
                         bc$lambda, pct(bc$level), bc$ci[1], bc$ci[2]),
         x = "lambda", y = "log-likelihood") + theme_doe()
}

plot_meanvar <- function(asm) {
  if (nrow(asm$mv) < 3) return(NULL)
  ggplot(asm$mv, aes(log(m), log(v))) + geom_point(size = 2.6, colour = SLX_BLUE) +
    geom_smooth(method = "lm", formula = y ~ x, se = FALSE, colour = SLX_RED) +
    labs(title = sprintf("Mean-variance relationship (Taylor slope b = %.2f)", asm$slope),
         x = "log(cell mean)", y = "log(cell variance)") + theme_doe()
}

## ------------------------------------------------------------- downloads ----

## a file name for a saved plot: StatLabX_<what>_<response>.png
plot_file <- function(what, resp = NULL, ext = "png") {
  clean <- function(x) gsub("^-+|-+$", "", gsub("[^A-Za-z0-9]+", "-", x))
  parts <- c(APP_BRAND, clean(what), if (length(resp) && nzchar(resp)) clean(resp))
  paste0(paste(parts[nzchar(parts)], collapse = "_"), ".", ext)
}

## ---------------------------------------------------------- charts.R ----
###############################################################################
##  CHARTS IN THE BROWSER
###############################################################################
## The app's graphs are drawn in the browser, as SVG in the platform's own
## style, from the plots this package builds with ggplot2. ggplot2 still
## decides what is drawn: every bar, interval, point, line, label and axis
## comes from ggplot_build(), so the readings beside each graph, worked out
## from the same plots, stay true. The browser only draws it, crisp at any
## size, with tooltips, and saves it as PNG or SVG exactly as it is shown
## (APP_CHART_JS). The plot functions keep returning ggplot objects for use
## outside the app.

## each geom as the browser draws it; anything else is left out, and the
## tests check that no plot of the app uses one
CHART_GEOMS <- c(GeomCol = "bar", GeomBar = "bar", GeomRect = "rect", GeomTile = "tile",
                 GeomPoint = "point", GeomLine = "line", GeomPath = "path",
                 GeomErrorbar = "errorbar", GeomLinerange = "errorbar",
                 GeomHline = "hline", GeomVline = "vline", GeomAbline = "abline",
                 GeomText = "text", GeomLabel = "text", GeomSegment = "segment",
                 GeomBoxplot = "box", GeomRibbon = "ribbon", GeomArea = "area",
                 GeomSmooth = "smooth", GeomRug = "rug")

## the columns each kind of mark needs
CHART_COLS <- list(
  bar = c("xmin", "xmax", "ymin", "ymax", "x", "y", "fill", "colour", "alpha", "group"),
  rect = c("xmin", "xmax", "ymin", "ymax", "fill", "colour", "alpha", "group"),
  tile = c("xmin", "xmax", "ymin", "ymax", "x", "y", "fill", "colour", "alpha", "group"),
  point = c("x", "y", "colour", "fill", "shape", "size", "alpha", "group"),
  line = c("x", "y", "group", "colour", "linewidth", "linetype", "alpha"),
  path = c("x", "y", "group", "colour", "linewidth", "linetype", "alpha"),
  errorbar = c("x", "xmin", "xmax", "ymin", "ymax", "colour", "linewidth", "group"),
  hline = c("yintercept", "colour", "linewidth", "linetype", "alpha"),
  vline = c("xintercept", "colour", "linewidth", "linetype", "alpha", "group"),
  abline = c("slope", "intercept", "colour", "linewidth", "linetype", "alpha"),
  text = c("x", "y", "label", "colour", "size", "hjust", "vjust", "angle", "fontface", "alpha"),
  segment = c("x", "y", "xend", "yend", "colour", "linewidth", "linetype", "alpha"),
  box = c("x", "xmin", "xmax", "ymin", "lower", "middle", "upper", "ymax", "outliers", "fill", "colour", "group"),
  ribbon = c("x", "ymin", "ymax", "group", "fill", "colour", "alpha"),
  area = c("x", "y", "ymin", "ymax", "group", "fill", "colour", "alpha"),
  smooth = c("x", "y", "ymin", "ymax", "group", "colour", "fill", "alpha", "linewidth"),
  rug = c("x", "y", "colour", "alpha"))

## colours as #RRGGBB, so the browser and the tests compare like with like
hex_col <- function(x) {
  out <- rep(NA_character_, length(x))
  x <- as.character(x)
  ok <- !is.na(x) & nzchar(x) & x != "NA"
  if (any(ok)) {
    m <- grDevices::col2rgb(x[ok])
    out[ok] <- sprintf("#%02X%02X%02X", m[1, ], m[2, ], m[3, ])
  }
  out
}

## line types by name: solid, dashed, dotted, ...
LINETYPES <- c("blank", "solid", "dashed", "dotted", "dotdash", "longdash", "twodash")
lty_name <- function(x) {
  x <- as.character(x)
  i <- suppressWarnings(as.integer(x))
  ifelse(!is.na(i) & i >= 0 & i <= 6, LINETYPES[pmin(pmax(i, 0), 6) + 1L], x)
}

## text justification as a number from 0 to 1
just_num <- function(x) {
  if (is.numeric(x)) return(x)
  x <- as.character(x)
  v <- suppressWarnings(as.numeric(x))
  words <- c(left = 0, bottom = 0, center = 0.5, centre = 0.5, middle = 0.5, right = 1, top = 1)
  v[is.na(v)] <- unname(words[x[is.na(v)]])
  v[is.na(v)] <- 0.5
  v
}

## One layer's marks: the kind, the columns it needs, colours as hex and the
## arrows of segments. NULL for a layer that draws nothing.
chart_layer <- function(layer, d) {
  cls <- class(layer$geom)
  hit <- cls[cls %in% names(CHART_GEOMS)][1]
  if (is.na(hit) || !nrow(d)) return(NULL)
  kind <- CHART_GEOMS[[hit]]
  ## a histogram's bars stand edge to edge
  if (kind == "bar" && inherits(layer$stat, "StatBin")) kind <- "hist"
  cols <- CHART_COLS[[if (kind == "hist") "bar" else kind]]
  out <- d[, intersect(c("PANEL", cols), names(d)), drop = FALSE]
  out$PANEL <- as.integer(as.character(out$PANEL))
  for (cc in intersect(c("colour", "fill"), names(out))) out[[cc]] <- hex_col(out[[cc]])
  if ("linetype" %in% names(out)) out$linetype <- lty_name(out$linetype)
  for (cc in intersect(c("hjust", "vjust"), names(out))) out[[cc]] <- just_num(out[[cc]])
  if ("label" %in% names(out)) out$label <- as.character(out$label)
  if ("shape" %in% names(out)) out$shape <- as.character(out$shape)
  for (cc in setdiff(names(out), c("PANEL", "colour", "fill", "linetype", "label", "shape", "outliers")))
    if (!is.numeric(out[[cc]])) out[[cc]] <- suppressWarnings(as.numeric(as.character(out[[cc]])))
  if ("outliers" %in% names(out)) out$outliers <- lapply(out$outliers, function(z) as.numeric(z))
  rownames(out) <- NULL
  arrow <- layer$geom_params$arrow
  ## the grouping letters of a plot of means (plot_main() labels them .let),
  ## which the browser draws as pills; any other text stays plain text
  lab <- layer$mapping$label
  lets <- kind == "text" && !is.null(lab) && identical(rlang::as_label(lab), ".let")
  list(kind = kind, geom = sub("^Geom", "", hit), data = out,
       arrow = if (inherits(arrow, "arrow")) list(ends = c("first", "last", "both")[arrow$ends[1]],
                                                  closed = identical(as.integer(arrow$type[1]), 2L)) else NULL,
       se = if (kind == "smooth") isTRUE(layer$stat_params$se) else NULL,
       letters = if (lets) TRUE else NULL)
}

## The kinds of mark that show aesthetic `a` in its legend: the layers that
## map it and do not leave the legend out. The browser draws each key as
## those marks: a swatch for bars, boxes and tiles, a point, a line, or both.
legend_kinds <- function(p, a) {
  out <- character(0)
  for (l in p$layers) {
    sl <- l$show.legend
    if (isFALSE(sl) || (!is.null(names(sl)) && a %in% names(sl) && isFALSE(sl[[a]]))) next
    m <- names(l$mapping)
    if (isTRUE(l$inherit.aes)) m <- c(m, names(p$mapping))
    if (!a %in% m) next
    hit <- intersect(class(l$geom), names(CHART_GEOMS))[1]
    if (!is.na(hit)) out <- c(out, CHART_GEOMS[[hit]])
  }
  unique(out)
}

## an axis of a panel: its range and the breaks with their labels, where a
## discrete axis puts its levels at 1, 2, 3, ...
chart_axis <- function(sc, range) {
  br <- sc$get_breaks()
  lab <- sc$get_labels()
  disc <- isTRUE(sc$is_discrete())
  pos <- if (disc) attr(br, "pos") %||% tryCatch(sc$map(br), error = function(e) seq_along(br)) else br
  pos <- suppressWarnings(as.numeric(pos))
  lab <- as.character(lab)
  if (length(lab) != length(pos)) lab <- rep_len(lab, length(pos))
  keep <- !is.na(pos) & pos >= min(range) - 1e-9 & pos <= max(range) + 1e-9
  list(range = as.numeric(range), breaks = pos[keep], labels = lab[keep], discrete = disc)
}

## the labels of a plot as it is drawn, set ones and those from mappings alike
chart_labs <- function(p) {
  f <- tryCatch(getExportedValue("ggplot2", "get_labs"), error = function(e) NULL)
  l <- if (is.function(f)) tryCatch(suppressMessages(f(p)), error = function(e) NULL) else NULL
  l %||% p$labels
}

## Every legend the plot shows: a discrete one as items (label and the
## fill, colour, shape and line type of its key) and the kinds of mark its
## keys stand for, a colour bar as its colour stops. Legends with the same
## title and labels (colour and shape of one factor) are merged.
chart_legends <- function(p, labs) {
  gd <- tryCatch(getExportedValue("ggplot2", "get_guide_data"), error = function(e) NULL)
  if (!is.function(gd)) return(list())
  out <- list()
  for (a in c("fill", "colour", "shape", "linetype")) {
    g <- tryCatch(suppressMessages(gd(p, a)), error = function(e) NULL)
    if (is.null(g) || !is.data.frame(g) || !nrow(g) || !".label" %in% names(g)) next
    ttl <- labs[[a]]
    ttl <- if (is.null(ttl) || is.function(ttl) || !length(ttl)) "" else as.character(ttl)[1]
    if (is.numeric(g$.value) && a %in% c("fill", "colour")) {
      v <- g$.value
      out[[length(out) + 1L]] <- list(type = "bar", title = ttl, aes = a,
        stops = data.frame(at = (v - min(v)) / max(diff(range(v)), 1e-12), colour = hex_col(g[[a]]),
                           label = as.character(g$.label), stringsAsFactors = FALSE))
      next
    }
    items <- data.frame(label = as.character(g$.label), stringsAsFactors = FALSE)
    items[[a]] <- if (a %in% c("fill", "colour")) hex_col(g[[a]]) else if (a == "linetype") lty_name(g[[a]]) else as.character(g[[a]])
    hit <- 0L
    for (k in seq_along(out))
      if (identical(out[[k]]$type, "items") && identical(out[[k]]$title, ttl) &&
          identical(out[[k]]$items$label, items$label)) hit <- k
    if (hit) {
      out[[hit]]$items[[a]] <- items[[a]]
      out[[hit]]$keys <- union(out[[hit]]$keys, legend_kinds(p, a))
    } else out[[length(out) + 1L]] <- list(type = "items", title = ttl, items = items, keys = legend_kinds(p, a))
  }
  out
}

## The chart the browser draws for plot `p`: titles, panels with their
## axes, layers of marks, legends, the aspect ratio when the plot fixes one,
## and the name of the file it saves to.
chart_spec <- function(p, what = "graph", resp = NULL) {
  if (is.null(p)) return(NULL)
  b <- suppressMessages(ggplot2::ggplot_build(p))
  labs <- chart_labs(p)
  lay <- b$layout$layout
  fv <- setdiff(names(lay), c("PANEL", "ROW", "COL", "SCALE_X", "SCALE_Y", "COORD"))
  panels <- lapply(seq_len(nrow(lay)), function(k) {
    pp <- b$layout$panel_params[[k]]
    list(panel = as.integer(as.character(lay$PANEL[k])), row = as.integer(lay$ROW[k]), col = as.integer(lay$COL[k]),
         strip = if (length(fv)) paste(vapply(fv, function(v) as.character(lay[[v]][k]), ""), collapse = ", ") else NULL,
         x = chart_axis(pp$x, pp$x.range), y = chart_axis(pp$y, pp$y.range))
  })
  layers <- Filter(Negate(is.null), lapply(seq_along(b$data), function(i) chart_layer(p$layers[[i]], b$data[[i]])))
  txt <- function(x) if (is.null(x) || is.function(x) || !length(x) || is.na(x[1])) NULL else as.character(x)[1]
  ## an aspect ratio the plot fixes (coord_equal), and axis labels it hides
  ratio <- p$coordinates$ratio
  blank <- function(el) any(grepl("element_blank", class(p$theme[[el]]), fixed = TRUE))
  list(title = txt(labs$title), subtitle = txt(labs$subtitle), caption = txt(labs$caption),
       xlab = txt(labs$x), ylab = txt(labs$y),
       ratio = if (is.numeric(ratio) && length(ratio) == 1L && is.finite(ratio)) ratio else NULL,
       hide = list(x = blank("axis.text.x") || blank("axis.text"), y = blank("axis.text.y") || blank("axis.text")),
       panels = panels, layers = layers, legends = chart_legends(p, labs),
       file = sub("[.]$", "", plot_file(what, resp, "")))
}

## The output that holds a chart, with its download menu: PNG at 300 dpi,
## or SVG, of the chart as it is shown, with the platform named at its foot
chart_output <- function(id, height = "320px") {
  div(class = "slx-plot",
      div(id = id, class = "slx-chart", style = sprintf("height:%s", height), role = "img"),
      div(class = "slx-plot-dl", role = "group", `aria-label` = "Download this graph",
          tags$button(type = "button", class = "slx-dl", `data-plot` = id, `data-fmt` = "png",
                      title = "Download this graph as a PNG image (300 dpi)", icon("download"), "PNG"),
          tags$button(type = "button", class = "slx-dl", `data-plot` = id, `data-fmt` = "svg",
                      title = "Download this graph as an SVG (vector) image", "SVG")))
}

## the render function of a chart output: `fun` returns a ggplot (or NULL)
render_chart <- function(fun, what = "graph", resp = NULL) {
  shiny::createRenderFunction(function() {
    p <- fun()
    chart_spec(p, if (is.function(what)) what() else what,
               if (is.function(resp)) tryCatch(resp(), error = function(e) NULL) else resp)
  }, function(value, session, name, ...) value, outputFunc = chart_output)
}

## The browser's half: draws the charts chart_spec() describes, in the
## platform's style, and saves them as PNG (2400 pixels wide, marked 300 dpi)
## or SVG. Plain JavaScript, no library: every byte here is paid for on the
## first visit. Kept as a raw string, so it reads as the JavaScript it is.
APP_CHART_JS <- r"---(/* StatLabX charts: the app's graphs drawn in the browser as SVG, from the
   chart descriptions R sends (chart_spec()). R decides what is drawn; this
   only draws it, in the platform's style, and saves it as PNG or SVG. */
(function () {
  "use strict";
  var NS = "http://www.w3.org/2000/svg";
  var FONT = "system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif";
  var INK = "#14284B", TXT = "#3D4B63", MUTED = "#6B7A93", GRID = "#E3E9F2", AXIS = "#C9D3E2";
  var BRAND_TOP = "#9CC3FF", BRAND = "#3B7DD8";
  var uid = 0;
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* ------------------------------------------------------------ helpers */
  function S(tag, a, parent) {
    var e = document.createElementNS(NS, tag);
    if (a) for (var k in a) if (a[k] !== undefined && a[k] !== null && a[k] !== false) e.setAttribute(k, a[k]);
    if (parent) parent.appendChild(e);
    return e;
  }
  var mctx = document.createElement("canvas").getContext("2d");
  function tw(s, size, weight) { mctx.font = (weight || 400) + " " + size + "px " + FONT; return mctx.measureText(String(s)).width; }
  function str(x) { return typeof x === "string" ? x : ""; }
  function arr(v) { return v === undefined || v === null ? [] : (Array.isArray(v) ? v : [v]); }
  function nrows(d) { var n = 0; for (var k in d) n = Math.max(n, arr(d[k]).length); return n; }
  function rows(d) {
    var n = nrows(d), keys = Object.keys(d), cols = {}, out = [], i, k;
    for (k = 0; k < keys.length; k++) cols[keys[k]] = arr(d[keys[k]]);
    for (i = 0; i < n; i++) { var r = {}; for (k = 0; k < keys.length; k++) r[keys[k]] = cols[keys[k]][i]; out.push(r); }
    return out;
  }
  function num(v) { return typeof v === "number" && isFinite(v); }
  /* a figure's minus sign as a true minus, which a hyphen is too short to
     read as: -2.5 shows as \u22122.5. Only labels that are wholly a figure. */
  function minus(s) {
    s = String(s);
    return /^-\d*\.?\d+(e[+-]?\d+)?\**$/i.test(s) ? "\u2212" + s.slice(1) : s;
  }
  function fnum(v) {
    if (!num(v)) return "-";
    var a = Math.abs(v);
    if (a !== 0 && (a < 0.001 || a >= 1e6)) return minus(v.toExponential(2));
    return minus(String(+v.toPrecision(4)));
  }
  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
  function rgb(h) {
    h = String(h || "").replace("#", "");
    if (h.length !== 6) return [59, 125, 216];
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }
  function mix(h, w, t) {
    var a = rgb(h), b = rgb(w);
    return "rgb(" + [0, 1, 2].map(function (i) { return Math.round(a[i] + (b[i] - a[i]) * t); }).join(",") + ")";
  }
  function lum(h) { var c = rgb(h); return (0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2]) / 255; }
  function same(a, b) { return String(a || "").toUpperCase() === String(b || "").toUpperCase(); }
  var DASH = { solid: null, blank: "0 1000", dashed: "6 5", dotted: "1.5 4", dotdash: "1.5 4 6 4", longdash: "11 5", twodash: "7 3 2 3" };

  /* the brand's own blues (bars, histogram, boxes) get the brand gradient */
  function isBrand(c) { return same(c, "#3B7DD8") || same(c, "#BBD3F2") || same(c, "#3B82F6"); }

  /* ------------------------------------------------------------ the chart */
  function render(el, spec, opt) {
    opt = opt || {};
    var W = Math.round(opt.width || el.clientWidth), H = Math.round(opt.height || el.clientHeight);
    while (el.firstChild) el.removeChild(el.firstChild);
    if (!spec || !W || !H) return null;
    var id = "slx" + (++uid), anim = !!opt.animate && !reduce && !opt.exporting;
    var svg = S("svg", { xmlns: NS, width: W, height: H, viewBox: "0 0 " + W + " " + H, "font-family": FONT, role: "img",
                         "aria-label": str(spec.title) || "Chart" }, el);
    S("title", null, svg).textContent = str(spec.title);
    var defs = S("defs", null, svg);
    if (opt.exporting) S("rect", { x: 0, y: 0, width: W, height: H, fill: "#FFFFFF" }, svg);
    var grads = {};
    function grad(top, bottom, vertical) {
      var key = top + "|" + bottom + "|" + vertical;
      if (grads[key]) return grads[key];
      var gid = id + "g" + Object.keys(grads).length;
      var g = S("linearGradient", vertical === false ? { id: gid, x1: 0, y1: 0, x2: 1, y2: 0 } : { id: gid, x1: 0, y1: 0, x2: 0, y2: 1 }, defs);
      S("stop", { offset: 0, "stop-color": top }, g);
      S("stop", { offset: 1, "stop-color": bottom }, g);
      return (grads[key] = "url(#" + gid + ")");
    }
    function fillOf(c, invert) {
      if (isBrand(c)) return invert ? grad(BRAND, BRAND_TOP) : grad(BRAND_TOP, BRAND);
      return invert ? grad(c, mix(c, "#FFFFFF", 0.32)) : grad(mix(c, "#FFFFFF", 0.32), c);
    }
    var markers = {};
    function marker(c, closed) {
      var key = c + closed;
      if (markers[key]) return markers[key];
      var mid = id + "m" + Object.keys(markers).length;
      var m = S("marker", { id: mid, viewBox: "0 0 10 10", refX: 9, refY: 5, markerWidth: 7, markerHeight: 7, orient: "auto-start-reverse" }, defs);
      S("path", closed ? { d: "M0,1 L10,5 L0,9 Z", fill: c } : { d: "M1,1 L9,5 L1,9", fill: "none", stroke: c, "stroke-width": 1.6, "stroke-linecap": "round", "stroke-linejoin": "round" }, m);
      return (markers[key] = "url(#" + mid + ")");
    }

    var padX = 18, top = 16, right = opt.exporting ? padX : 132;
    /* titles */
    var y = top;
    /* words into lines: the first line may be narrower (beside the download
       buttons), and the last line kept ends in an ellipsis if text is left */
    function wrapText(t, size, weight, maxW, firstW, most) {
      var words = String(t).replace(/\s+/g, " ").trim().split(" "), lines = [], cur = "";
      words.forEach(function (w) {
        var next = cur ? cur + " " + w : w, lim = lines.length ? maxW : (firstW || maxW);
        if (tw(next, size, weight) > lim && cur) { lines.push(cur); cur = w; } else cur = next;
      });
      if (cur) lines.push(cur);
      if (most && lines.length > most) {
        lines = lines.slice(0, most);
        var last = lines[most - 1];
        while (last && tw(last + "\u2026", size, weight) > maxW) last = last.replace(/\s*\S+$/, "");
        lines[most - 1] = last + "\u2026";
      }
      return lines;
    }
    var title = str(spec.title), sub = str(spec.subtitle);
    if (title) {
      wrapText(title, 15, 700, W - 2 * padX, W - padX - right, 3).forEach(function (ln) {
        y += 18; S("text", { x: padX, y: y, "font-size": 15, "font-weight": 700, fill: INK }, svg).textContent = ln;
      });
    }
    if (sub) wrapText(sub, 12, 400, W - 2 * padX, title ? 0 : W - padX - right, 2).forEach(function (ln, i) {
