          if (anchor === "start" && px + wl > c.x0 + c.pw) { anchor = "end"; px = Math.min(px, c.x0 + c.pw) - 4; }
          else if (anchor === "end" && px - wl < c.x0) { anchor = "start"; px = Math.max(px, c.x0) + 4; }
