authors_html <- function(with_contact = FALSE) paste0(
  "<div class='authors'><b>Developed by</b><br>",
  paste(vapply(seq_along(AUTHORS), function(i) {
    a <- AUTHORS[[i]]
    orc <- if (!is.null(a$orcid) && !is.na(a$orcid))
      sprintf(" &nbsp;<a href='https://orcid.org/%s'>ORCID</a>", a$orcid) else ""
    eml <- if (with_contact && !is.null(a$email) && !is.na(a$email))
      sprintf(" &nbsp;&middot;&nbsp; <a href='mailto:%s'>%s</a>", a$email, a$email) else ""
    sprintf("%d. %s &mdash; %s, %s%s%s", i, a$name, a$role, a$aff, orc, eml)
  }, character(1)), collapse = "<br>"),
  "</div>")

credit_block <- function() paste0(
  "<div class='creditblock'>", CREDIT_LONG, "<br>",
  "Please cite: ", CITE_AUTHORS, " (", format(Sys.Date(), "%Y"), "). ", APP_NAME,
  ": analysis of designed agricultural experiments. Version ", APP_VERSION,
  ". Zenodo. doi:<a href='https://doi.org/", APP_DOI, "'>", APP_DOI, "</a><br>",
  format(Sys.time(), "%d %B %Y, %H:%M"), "</div>")

## the heading over one response's analysis of variance
anova_heading <- function(header) sprintf("Analysis of Variance (%s)", header)

## An ANOVA table as the app and the report show it, its significance column
## headed with the level it is judged at
anova_show <- function(an, alpha) {
  d <- anova_display(an, alpha)
  names(d)[names(d) == "Signif"] <- sprintf("Significance (%s%%)", pct(alpha))
  d
}

#' Render an analysis as an HTML report
#'
#' Turns the result of \code{\link{run_all}} into a complete, self-contained HTML
#' report: the analysis of variance of each response, the tables of means with
#' their standard errors and the comparison chosen, the checks of the
#' assumptions, and a plain-English interpretation. The report carries the
#' StatLabX credit and the DOEpro citation, and prints cleanly on A4 (the
#' browser's \emph{Print} then \emph{Save as PDF} gives a PDF).
#'
#' @param rr The object returned by \code{\link{run_all}}.
#' @param comparison How the means are compared, from
#'   \code{\link{comparison}}: the means alone (the default), the critical
#'   difference, the letters of a multiple-comparison procedure, or Dunnett's
#'   test. Letters and a critical difference are never shown together, and
#'   letters are suppressed for any effect whose F-test is not significant.
#' @param detailed If \code{TRUE}, include the full per-effect tables of means.
#'   If \code{FALSE}, give the compact summary tables only.
#' @param screen If \code{TRUE}, add a small credit line fixed to the corner of
#'   the screen.
#' @param digits Decimal places for the means in the tables of means. A
#'   standard error or critical difference that would print as zero is given
#'   more.
#' @param letters_on No longer used: the comparison decides whether letters are
#'   shown. Kept so that older calls still run.
#' @param nature The declared nature of each response, for the summary of the
#'   checks: \code{"auto"}, \code{"continuous"}, \code{"count"} or
#'   \code{"percent"}, one value or one per response (named).
#'
#' @return A character string of HTML, of length one.
#'
#' @examples
#' rr <- run_all(demo_data("CRD"), "CRD", list(treat = "Treatment"), "Yield")
#' html <- build_report(rr, comparison = comparison("Tukey HSD"))
#' substr(html, 1, 60)
#' \donttest{
#' # writeLines(html, "report.html")
#' }
#'
#' @export
build_report <- function(rr, comparison = NULL, detailed = TRUE, screen = FALSE, digits = 2,
                         letters_on = NULL, nature = "auto") {
  ## an older call passing letters_on (TRUE or FALSE) second
  if (is.logical(comparison)) comparison <- NULL
  cmp <- if (is.null(comparison)) comparison_spec("none") else comparison
  fits <- rr$fits
  heads <- vapply(fits, function(f) esc(f$header), character(1))
  cmp_txt <- if (cmp$kind == "none") "means only" else CMP_NAME[[cmp$method]]
  hdr <- sprintf(paste0(
    "<header class='rpt-head'><img class='rpt-logo' src='%s' alt='StatLabX'>",
    "<div><h1>Analysis report</h1><div class='rpt-sub'>Generated with %s &middot; %s v%s</div></div></header>",
    "<p class='meta'>Design: <b>%s</b> &nbsp;|&nbsp; Response variable(s): <b>%s</b> &nbsp;|&nbsp; ",
    "Significance level: <b>%s</b> &nbsp;|&nbsp; Comparison of means: <b>%s</b> &nbsp;|&nbsp; %s</p>%s"),
    LOGO_URI, APP_BRAND, APP_NAME, APP_VERSION,
    names(DESIGNS)[match(rr$design, DESIGNS)], paste(heads, collapse = ", "),
    p_lab(rr$alpha), cmp_txt, format(Sys.Date(), "%d %B %Y"), authors_html())

  ## Dunnett's comparisons are made on one effect, against one control
  dunnett <- if (cmp$kind == "dunnett") {
    eff <- cmp$effect %||% rr$facs[1]
    paste(vapply(names(fits), function(nm) cmp_effect_html(fits[[nm]], eff, cmp), character(1)), collapse = "")
  } else ""

  parts <- c(hdr,
    "<section class='rpt-sec'><h2>1. Analysis of variance</h2>",
    paste(vapply(names(fits), function(nm) paste0(
      "<div class='rpt-block'><h3>", esc(anova_heading(fits[[nm]]$header)), "</h3>",
      df_html(anova_show(fits[[nm]]$final$anova, rr$alpha)),
      anova_note(fits[[nm]]$final), "</div>"), character(1)), collapse = ""),
    "</section>",
    "<section class='rpt-sec'><h2>2. Means and comparisons</h2>",
    means_section_html(rr, digits = digits, cmp = cmp, detailed = detailed),
    if (nzchar(dunnett)) paste0("<h3>Dunnett's comparisons with the control</h3>",
                                gsub("<details class='slx-fold'>", "<details class='slx-fold' open>", dunnett, fixed = TRUE)) else "",
    "</section>",
    "<section class='rpt-sec'><h2>3. Assumptions and diagnostics</h2>",
    paste(vapply(names(fits), function(nm) {
      f <- fits[[nm]]
      paste0("<div class='rpt-block'><h3>", esc(f$header), "</h3>",
             assum_summary_html(assum_summary(f, dtype_for(nature, nm))),
             assum_table_html(f$asm),
             sprintf("<div class='note'>Suggested transformation%s: <b>%s</b>. %s</div>",
                     if (identical(f$trans, "none")) ""
                     else sprintf(", judged on the values as entered (the checks above are on the %s scale)", TRANS[[f$trans]]$lab),
                     TRANS[[f$sug$method]]$lab, esc(f$sug$why)), "</div>")
    }, character(1)), collapse = ""),
    "</section>",
    "<section class='rpt-sec'><h2>4. Interpretation</h2>",
    paste(vapply(names(fits), function(nm) {
      f <- fits[[nm]]
      paste0("<div class='rpt-block'><h3>", esc(f$header), "</h3>",
             as.character(interpret(f$final, f$asm, f$sug, TRANS[[f$trans]]$lab, cmp)), "</div>")
    }, character(1)), collapse = ""),
    "</section>",
    credit_block(),
    sprintf("<div class='print-foot'>%s &middot; %s</div>", esc(CREDIT_LONG), format(Sys.Date(), "%d %B %Y")),
    if (screen) sprintf("<div class='screencredit'>%s</div>", CREDIT_SHORT) else "")

  paste0("<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'>",
         "<meta name='viewport' content='width=device-width, initial-scale=1'>",
         "<title>StatLabX report</title><style>", REPORT_CSS, MEANS_CSS, "</style></head><body>",
         "<main class='rpt'>", paste(parts, collapse = "\n"), "</main></body></html>")
}

## comparison() under another name, for build_report(), whose argument of
## that name would otherwise hide it
comparison_spec <- function(...) comparison(...)

## Compile the HTML report to PDF.  Tries, in order: pagedown (headless Chrome),
## weasyprint, wkhtmltopdf.  Returns TRUE on success.
save_pdf <- function(html, outfile) {
  tmp <- tempfile(fileext = ".html")
  writeLines(html, tmp, useBytes = TRUE)

  ftr <- sprintf(paste0("<div style=\"font-size:8px;color:#666;width:100%%;",
                        "padding:0 12mm 0 0;text-align:right\">%s &nbsp;|&nbsp; ",
                        "page <span class='pageNumber'></span> of ",
                        "<span class='totalPages'></span></div>"), CREDIT_SHORT)

  if (requireNamespace("pagedown", quietly = TRUE)) {
    ok <- tryCatch({
      pagedown::chrome_print(tmp, output = outfile, verbose = 0, timeout = 90,
        options = list(displayHeaderFooter = TRUE, printBackground = TRUE,
                       headerTemplate = "<span></span>", footerTemplate = ftr,
                       marginTop = 0.6, marginBottom = 0.75))
      file.exists(outfile)
    }, error = function(e) FALSE)
    if (isTRUE(ok)) return(TRUE)
  }
  for (bin in c("weasyprint", "wkhtmltopdf")) {
    p <- Sys.which(bin)
    if (!nzchar(p)) next
    args <- if (bin == "weasyprint") c(shQuote(tmp), shQuote(outfile))
            else c("--enable-local-file-access", "--footer-right", shQuote(CREDIT_SHORT),
                   "--footer-font-size", "7", shQuote(tmp), shQuote(outfile))
    ok <- tryCatch(system2(p, args, stdout = FALSE, stderr = FALSE) == 0L,
                   error = function(e) FALSE)
    if (isTRUE(ok) && file.exists(outfile)) return(TRUE)
  }
  FALSE
}

## What sits under an ANOVA table: the key to the stars at the chosen level, and
## a warning when the sums of squares are adjusted ones that need not add up.
anova_note <- function(res) {
  paste0("<div class='note'>", star_key(res$alpha),
         if (isTRUE(res$adjusted_ss))
           paste0(" The data are unbalanced, so each term is tested after allowing for ",
                  "every other term (Type III sums of squares); these need not add up to ",
                  "the total.") else "",
         "</div>")
}

## The assumption checks, each judged at the analysis's significance level.
## A test that could not be computed says so and why; it is never given a
## verdict, least of all "significant departure".
assum_table_html <- function(a) {
  rows <- character(0)
  ok <- function(p, why = NULL) {
    if (!is.finite(p)) return(paste0("not available", if (length(why)) paste0(": ", esc(why)) else ""))
    if (p >= a$alpha) "no significant departure" else "<b>significant departure</b>"
  }
  stat <- function(lab, v) if (is.finite(v)) paste(lab, "=", fmt(v)) else "-"
  pv <- function(p) if (is.finite(p)) p_eq(p, a$alpha) else "-"
  rows <- c(rows, sprintf(
    "<tr><td>Shapiro-Wilk (normality of residuals)</td><td>%s</td><td>%s</td><td>%s</td></tr>",
    stat("W", if (is.null(a$shapiro)) NA else a$shapiro$statistic), pv(a$p_norm), ok(a$p_norm, a$norm_why)))
  rows <- c(rows, sprintf(
    "<tr><td>Levene, median-centred (homogeneity)</td><td>%s</td><td>%s</td><td>%s</td></tr>",
    stat("F", a$levene$F), pv(a$levene$p), ok(a$levene$p, a$levene$why)))
  rows <- c(rows, sprintf(
    "<tr><td>Bartlett (homogeneity)</td><td>%s</td><td>%s</td><td>%s</td></tr>",
    stat("K2", a$bartlett$statistic), pv(a$bartlett$p.value), ok(a$bartlett$p.value, a$bartlett$why)))
  rows <- c(rows, sprintf(
    "<tr><td>Taylor's power-law slope b</td><td colspan='2'>%s</td><td>%s</td></tr>",
    dfmt(a$slope, 2), if (isTRUE(a$exact)) "not estimable (the model fits every value exactly)"
      else if (is.na(a$slope)) "-"
      ## judged by the slope's own test, as the mean-variance plot's note is
      else if (is.na(a$slope_p)) "cannot be tested with three points"
      else if (a$slope_p >= a$alpha)
        sprintf("insufficient evidence that the variance changes with the mean (%s)", p_eq(a$slope_p, a$alpha))
      else sprintf("the variance %s with the mean (%s)", if (a$slope > 0) "rises" else "falls",
                   p_eq(a$slope_p, a$alpha))))
  rows <- c(rows, sprintf(
    "<tr><td>Optimal Box-Cox lambda</td><td colspan='2'>%s</td><td>%s</td></tr>",
    ## at the end of the range searched the profile is still rising: the
    ## optimum lies beyond it, and the figure is only where the search stopped
    if (!is.na(a$lambda) && abs(a$lambda) >= 2 - 1e-9) sprintf("beyond %s", fmt(a$lambda, 2)) else fmt(a$lambda, 2),
    if (isTRUE(a$exact)) "not estimable (the model fits every value exactly)"
    else if (is.null(a$bc)) "not estimable (response must be &gt; 0)"
    else sprintf("%s%% CI %.2f to %.2f", pct(a$bc$level), a$bc$ci[1], a$bc$ci[2])))
  rows <- c(rows, sprintf(
    "<tr><td>Possible outliers (|std resid| &gt; 3)</td><td colspan='2'>%s</td><td></td></tr>",
    if (length(a$outliers)) paste(a$outliers, collapse = ", ") else "none"))
  lev <- a$levene; bart <- a$bartlett
  left <- join_and(head_more(lev$left_out, 6))
  sig <- function(p) is.finite(p) && p < a$alpha
  notes <- c(
    if (isTRUE(a$on_residuals) && !isTRUE(a$exact))
      paste("The design has blocks, so the tests of equal variances use each plot's residual, recentred on its",
            "treatment's mean: the block differences, which the error variance does not include, would otherwise",
            "hide unequal variances. The Taylor slope uses the values themselves, as residuals would flatten it."),
    if (isTRUE(a$exact)) paste("The model fits every value exactly: each observation equals its fitted value,",
                               "so there is no", if (isTRUE(a$strata)) "sub-plot" else "residual",
                               "error variation to test or to plot."),
    if (isTRUE(lev$zeros_removed > 0))
      paste("In cells with an odd number of values the median is one of the values, so its deviation is always",
            "zero; Levene's test leaves that one zero out (Hines and O'Hara Hines, 2000), without which it could",
            "hardly ever find unequal variances with three values per cell."),
    if (!isTRUE(a$exact) && !is.finite(lev$p) && lev$cells < 2) "Levene's test needs at least three values in a cell.",
    if (is.finite(lev$p) && lev$dropped > 0)
      sprintf("Levene's test leaves out %s, which %s fewer than three values, so it compares only the other cells.",
              left, if (lev$dropped == 1) "has" else "have"),
    if (identical(a$hov_test, "Bartlett"))
      sprintf("The verdict on equal variances uses Bartlett's test, which covers every cell%s but assumes the values are normal.",
              if (bart$dropped > 0) " with two or more values" else ""),
    if (identical(a$hov_test, "Levene") && lev$dropped > 0)
      "Bartlett's test cannot be run here, so the verdict on equal variances rests on Levene's test of the cells it could use.",
    ## the two tests disagree: say which verdict is used, and why
    if (identical(a$hov_test, "Levene") && lev$dropped == 0 && is.finite(bart$p.value) && sig(bart$p.value) != sig(lev$p))
      if (sig(bart$p.value)) paste("Bartlett's test finds a departure that Levene's does not. Bartlett's is the more",
                                   "sensitive of the two when the values are normal but is easily misled when they are not,",
                                   "so the verdict follows Levene's; treat the variances with some caution.")
      else "Levene's test finds a departure that Bartlett's does not; the verdict follows Levene's, which does not assume normality.",
    if (is.finite(bart$p.value) && bart$dropped > 0)
      sprintf("Bartlett's test leaves out %d %s with a single value.", bart$dropped,
              if (bart$dropped == 1) "cell" else "cells"))
  paste0("<table class='doe'><caption>The tests in detail</caption><thead><tr><th>Test</th><th>Statistic</th><th>p</th>",
         "<th>Verdict</th></tr></thead><tbody>", paste(rows, collapse = ""), "</tbody></table>",
         sprintf("<div class='note'>Verdicts are at the %s%% significance level.%s</div>", pct(a$alpha),
                 paste0(" ", notes, collapse = "")))
}

## The report's own look, on screen and on paper. On paper: A4, the
## navigation and buttons gone, no table or heading split from what follows
## it, each response's block kept together where it fits, wide tables on a
## landscape page (where the browser supports named pages), and the credit
## line at the foot of every page.
REPORT_CSS <- "
@page{size:A4 portrait;margin:15mm 13mm 18mm 13mm}
@page wide{size:A4 landscape;margin:13mm 13mm 16mm 13mm}
*{box-sizing:border-box}
body{font-family:Segoe UI,Inter,Helvetica,Arial,sans-serif;margin:0;background:#F5F7FB;color:#1C2B4A;line-height:1.5}
main.rpt{max-width:1060px;margin:24px auto;background:#fff;border:1px solid #E2E8F2;border-radius:16px;padding:28px 34px 40px}
.rpt-head{display:flex;align-items:center;gap:18px;border-bottom:3px solid #3B7DD8;padding-bottom:10px;margin-bottom:6px}
.rpt-head h1{margin:0;font-size:26px;color:#14284B;letter-spacing:-.01em}
.rpt-sub{font-size:12px;color:#5B6B86;letter-spacing:.04em}
.rpt-logo{height:46px;width:auto;flex:0 0 auto}
h2{color:#14284B;border-bottom:1px solid #C8D8EE;margin:30px 0 10px;padding-bottom:4px;font-size:20px;break-after:avoid;page-break-after:avoid}
h3{color:#1B4F9C;margin:18px 0 6px;font-size:16px;break-after:avoid;page-break-after:avoid}
h4{margin:12px 0 4px;color:#1B4F9C;break-after:avoid;page-break-after:avoid}
p.meta{color:#5B6B86;font-size:12px;margin:8px 0 0}
table.doe{border-collapse:collapse;margin:8px 0 4px 0;font-size:13px;font-variant-numeric:tabular-nums;break-inside:avoid;page-break-inside:avoid}
table.doe th,table.doe td{border:1px solid #C3D0E2;padding:5px 10px;text-align:right}
table.doe th{background:#EEF3FA;text-align:center;color:#14284B}
table.doe td:first-child,table.doe th:first-child{text-align:left}
table.doe caption{caption-side:top;text-align:left;font-weight:600;padding:6px 0;color:#1B4F9C}
table.doe tfoot td{background:#FAFCFF;font-size:12px}
table.doe-summary td{text-align:left;vertical-align:top;font-size:12.5px}
td.cdrow{text-align:left !important;background:#FAFCFF;font-size:12px}
table.foot{font-size:12px;margin-top:0;background:#FAFCFF}
span.sig{color:#C0392B;font-weight:600}
span.ns{color:#7A889E}
sup{color:#1B4F9C;font-weight:600}
.slx-kind{display:inline-block;margin-top:3px;padding:1px 7px;border-radius:999px;font-size:10.5px;font-weight:600;
  background:#EEF3FA;color:#1B4F9C}
.slx-kind-designrequirement{background:#FFF4E0;color:#8A5A00}
.slx-kind-visualcheck{background:#EEF8F1;color:#1E7A44}
.block,.rpt-block{margin-bottom:22px}
.note{font-size:12px;color:#5B6B86;margin:2px 0 14px 0}
.box{border:1px solid #E2E8F2;border-left:4px solid #3B7DD8;border-radius:10px;padding:10px 14px;margin:10px 0;font-size:13px}
.warn{background:#FFF6E5;border-left:4px solid #E8A33D;padding:8px 12px;margin:10px 0;border-radius:8px}
.err{background:#FDEEEC;border-left:4px solid #C0392B;padding:8px 12px;margin:10px 0;border-radius:8px}
details.slx-fold>summary{cursor:pointer;color:#1B4F9C;font-weight:600;margin:6px 0}
.authors{font-size:12px;color:#444;margin:12px 0 0 0}
.creditblock{margin-top:30px;padding-top:8px;border-top:1px solid #C8D8EE;
  font-size:11px;color:#5B6B86;text-align:right;break-inside:avoid;page-break-inside:avoid}
.print-foot{display:none}
.screencredit{position:fixed;right:12px;bottom:8px;font-size:10px;color:#8a8a8a;
  background:rgba(255,255,255,.85);padding:2px 6px;border-radius:3px}
@media print{
  body{background:#fff;font-size:11pt}
  main.rpt{max-width:none;margin:0;border:0;border-radius:0;padding:0 0 10mm}
  .screencredit{display:none}
  details.slx-fold>summary{display:none}
  details.slx-fold{display:block}
  details.slx-fold>*{display:block}
  table.doe{font-size:10pt}
  table.doe.wide{page:wide}
  table.doe tbody tr:hover td{background:inherit}
  .rpt-sec h2{break-before:auto}
  .print-foot{display:block;position:fixed;bottom:0;left:0;right:0;text-align:right;font-size:8pt;color:#666}
  a{color:inherit;text-decoration:none}
}
"

## ---------------------------------------------------------- run_all.R ----
###############################################################################
##  MULTI-RESPONSE DRIVER
###############################################################################

## Analyse every selected response variable with the same design and mapping.
## `trans` is a named character vector: response -> transformation key.
#' Analyse several responses from a designed experiment
#'
#' Runs \code{\link{analyze}} for every response variable in turn, using the same
#' design and mapping, and optionally applying a variance-stabilising
#' transformation to each. This is what the application calls when more than one
#' response is selected.
#'
#' @param d A data frame in long format.
#' @param design The design code; see \code{\link{DESIGNS}}.
#' @param map A named list mapping roles to columns; see \code{\link{analyze}}.
#'   The \code{response} element is set for each response in turn and need not be
#'   supplied.
#' @param responses A character vector of response column names.
#' @param alpha The significance level. Defaults to 0.05.
#' @param trans Either \code{NULL} (analyse every response untransformed) or a
#'   named list or character vector giving a transformation for each response.
#'   The names are the response columns and the values are keys of
#'   \code{\link{TRANS}}, for example \code{list(Incidence = "arcsine")}.
#' @param dtype Passed to the transformation adviser; \code{"auto"} lets DOEpro
#'   judge the type of each response from its name and its mean-variance
#'   behaviour.
#'
#' @return A list with \code{fits} (one entry per response, each containing the
#'   fitted analysis in \code{final}), together with the design, the mapping and
#'   the significance level.
#'
#' @examples
#' d <- demo_data("FRCBD")
#' rr <- run_all(d, "FRCBD",
#'               list(factors = c("Nitrogen", "Variety"), block = "Block"),
#'               responses = "Yield")
#' rr$fits[["Yield"]]$final$anova
#'
#' @export
run_all <- function(d, design, map, responses, alpha = 0.05,
                    trans = NULL, dtype = "auto") {
  fits <- list()
  for (v in responses) {
    b <- fit_base(d, design, map, v, alpha, dtype_for(dtype, v))
    tr <- if (is.null(trans)) "none" else {
      x <- trans[[v]]; if (is.null(x) || !nzchar(x)) "none" else x
    }
    fits[[v]] <- fit_final(b, d, design, map, tr)
  }
  rr_of(design, alpha, map, responses, fits)
}

## the analysis of several responses as one object, from their fits
rr_of <- function(design, alpha, map, responses, fits, errors = NULL)
  list(design = design, alpha = alpha, map = map, responses = responses,
       facs = if (length(fits)) fits[[1]]$final$facs else NULL, fits = fits, errors = errors)

## the nature of response `v`: one choice for every response, or one each,
## named by the responses
dtype_for <- function(dtype, v) {
  if (is.null(dtype)) return("auto")
  if (!is.null(names(dtype))) { x <- dtype[[v]]; return(if (is.null(x) || !nzchar(x)) "auto" else x) }
  dtype[[1]]
}

## The analysis of one response as entered, its checks and the adviser's
## suggestion. The screening on the Data tab shows these, and the analysis
## starts from them (fit_final), so the two never disagree and the model is
## fitted once.
fit_base <- function(d, design, map, v, alpha = 0.05, dtype = "auto") {
  base <- analyze(d, design, modifyList(map, list(response = v)), alpha)
  asm0 <- check_assumptions(base)
  list(resp = v, base = base, asm0 = asm0, sug = suggest_transform(base, asm0, dtype))
}

## The transformations that can be applied to response `v` of the data: those
## defined for every value, and Box-Cox only when its profile has an optimum
## inside the range searched (fit_final() refuses it otherwise).
trans_ok <- function(b) {
  y <- b$base$data[[b$resp]]
  ok <- vapply(names(TRANS), function(m) trans_defined(m, y), logical(1))
  lam <- b$asm0$lambda
  ok[["boxcox"]] <- ok[["boxcox"]] && !is.na(lam) && abs(lam) < 2 - 1e-9
  names(TRANS)[ok]
}

## The analysis of one response on the scale chosen: the model as entered
## when `tr` is "none", else the analysis of the transformed values, with
## every mean also given back-transformed.
fit_final <- function(b, d, design, map, tr = "none") {
  v <- b$resp; base <- b$base; asm0 <- b$asm0; alpha <- base$alpha
  mv <- modifyList(map, list(response = v))
  lam <- if (!is.na(asm0$lambda)) asm0$lambda else 1

  if (identical(tr, "none")) {
    fin <- base; asm <- asm0
  } else {
    if (!tr %in% names(TRANS)) stop(sprintf("Unknown transformation '%s'.", tr))
    ## Box-Cox needs positive values for its profile; without one there is
    ## no optimal lambda, and applying lambda = 1 would only subtract 1
    if (identical(tr, "boxcox") && is.na(asm0$lambda))
      stop(sprintf("The Box-Cox transformation needs every value of '%s' to be positive, so no optimal lambda can be found; choose another transformation.", v))
    if (identical(tr, "boxcox") && abs(lam) >= 2 - 1e-9)
      stop(sprintf(paste("The Box-Cox profile of '%s' is still rising at lambda = %s, the end of the range searched (-2 to 2),",
                         "so no optimal lambda was found there; choose another transformation, such as 1 / y."), v, fmt(lam, 0)))
    y <- response_values(d[[v]])
    y[!is.finite(y)] <- NA          # Inf is left out, as analyze() leaves it out
    z <- suppressWarnings(TRANS[[tr]]$f(y, lam))
    if (any(!is.finite(z[!is.na(y)])))   # entries that are not numbers are left out, not "out of range"
      stop(sprintf("The %s transformation is not defined for '%s' - the column has values outside its permitted range (e.g. zero or negative).",
                   TRANS[[tr]]$lab, v))
    d2 <- d; d2[[v]] <- z
    fin <- analyze(d2, design, mv, alpha)
    fin$trans <- tr; fin$lambda <- lam
    fin$excluded <- base$excluded      # reasons in terms of the data as entered
    fin$effects <- lapply(fin$effects, function(e) {
      e$means$Mean_bt <- TRANS[[tr]]$b(e$means$Mean, lam); e
    })
    asm <- check_assumptions(fin)
  }
  list(resp = v, base = base, final = fin, asm = asm, asm0 = asm0, sug = b$sug,
       trans = tr, lambda = lam,
       header = if (identical(tr, "none")) v else sprintf("%s (%s)", v, TRANS[[tr]]$lab))
}

## ---------------------------------------------------------- guides.R ----
###############################################################################
##  GUIDES
###############################################################################
## The guidance that used to sit on a Help tab of its own, each part now in
## the tab where it is needed, folded away until it is opened. How to report
## the results is in the interpretation itself (its last section).

## a folded guide: a one-line title that opens to the text
tab_guide <- function(title, html)
  tags$details(class = "slx-guide", tags$summary(title), HTML(html))

GUIDE_START <- "
<ol>
<li>Put your data in <b>long format</b> - one row per plot, one column per variable - and paste it in, upload a CSV, or load an example.</li>
<li>Under <b>Design and variables</b>, choose the design and the column that plays each role. You may choose <b>several response variables at once</b>; each is analysed separately with the same design and appears side by side in the tables of means.</li>
<li>The quick summary and the screening below update at once. The screening says which transformation, if any, each response may need.</li>
<li>Check the assumptions on the <b>Assumptions &amp; Diagnostics</b> tab, where you choose the scale of each response; then read the <b>ANOVA</b>, the <b>Means &amp; Comparisons</b>, the plots and the report. Every result follows your choices at once: there is no button to press.</li>
</ol>
"

GUIDE_DESIGNS <- "
<table class='doe'>
<tr><th>Design</th><th>Columns required</th><th>Error term(s)</th></tr>
<tr><td>CRD</td><td>treatment, response</td><td>single pooled error</td></tr>
<tr><td>RCBD</td><td>block, treatment, response</td><td>single pooled error</td></tr>
<tr><td>Latin square</td><td>row, column, treatment, response</td><td>single pooled error</td></tr>
<tr><td>Factorial CRD / RCBD</td><td>(block,) factors A-D, response</td><td>single pooled error</td></tr>
<tr><td>Split plot</td><td>replication, main plot, sub plot, response</td><td>Error(a), Error(b)</td></tr>
<tr><td>Strip plot</td><td>replication, factor A, factor B, response</td><td>Error(a), Error(b), Error(c)</td></tr>
<tr><td>Pooled over environments (RCBD)</td><td>environment, replication, treatment, response</td><td>R(env), pooled error</td></tr>
<tr><td>Pooled over environments (CRD)</td><td>environment, treatment, response</td><td>pooled error</td></tr>
<tr><td>Pooled factorial over environments (2-4 factors)</td><td>environment, (replication,) factors A-D, response</td><td>each effect vs its environment interaction; pooled error</td></tr>
</table>
"

GUIDE_POOLED <- "
<p>When the <b>same experiment is repeated across several environments</b> - locations,
years, seasons or other groups - a combined analysis tests the treatments, the
environments, and the treatment &times; environment interaction together. Arrange the data
with one column identifying the environment, alongside the usual replication and treatment
columns, and stack all environments in one long table.</p>
<p>The analysis proceeds in three steps:</p>
<ol>
<li><b>Homogeneity of error variances.</b> Bartlett's test compares the error variances of
the separate environments. If the test finds no significant difference at your chosen level,
the environments may be pooled; if it does, the app warns you and a variance-stabilising
transformation (or separate analyses) should be considered. The verdict is shown above the
ANOVA table.</li>
<li><b>Combined ANOVA</b> with the correct error terms:
  <ul>
  <li><b>RCBD base:</b> Environment is tested against replications-within-environment; the
  treatment is tested against the treatment &times; environment interaction; the interaction
  is tested against the pooled error.</li>
  <li><b>CRD base:</b> Environment and the interaction are tested against the pooled error;
  the treatment is tested against the interaction.</li>
  </ul>
  Testing the treatment against the interaction (rather than the pooled error) is the
  essential feature of a combined analysis - it asks whether a treatment's advantage is
  consistent enough across environments to be declared real.</li>
<li><b>Means and critical differences.</b> The treatment table gives means <b>averaged over
all environments</b>, with the critical difference built from the interaction mean square.
The environment &times; treatment table compares treatments <b>within a single environment</b>
using the pooled error, and also reports the standard error for comparing a treatment's
overall mean across environments.</li>
</ol>
<table class='doe'>
<tr><th>Comparison</th><th>Standard error of a difference</th></tr>
<tr><td>two treatment means, over all environments</td><td>&radic;(2&middot;M<sub>TxE</sub> / re)</td></tr>
<tr><td>two environment means</td><td>&radic;(2&middot;M<sub>error</sub> / rt) &nbsp;(CRD) &nbsp;or&nbsp; &radic;(2&middot;M<sub>R(E)</sub> / rt) &nbsp;(RCBD)</td></tr>
<tr><td>two treatments in the same environment</td><td>&radic;(2&middot;M<sub>error</sub> / r)</td></tr>
</table>
<p><b>Factorial treatments over environments.</b> When the treatments themselves form a
2-, 3- or 4-factor factorial, choose one of the <i>Pooled factorial over environments</i>
designs and set the number of treatment factors. The combined analysis then partitions the
treatment variation into every main effect and interaction, and applies the same rule
throughout: <b>each treatment effect (a main effect or an interaction among the treatment
factors) is tested against its own interaction with the environment</b>, and every
environment &times; treatment interaction is tested against the pooled error. This tells you
which main effects and interactions are stable enough across environments to be declared
real. A main effect's table of means, pooled over environments, uses the critical difference
built from that effect's environment interaction. In an interaction table two means can
differ in one factor or in several, and since the environment is random their difference
carries the environment's interaction with each factor in which they differ: with two
factors A and B, two A means at the same B have SE(d) =
&radic;(2[(b&minus;1)&middot;M<sub>ExAxB</sub> + M<sub>ExA</sub>] / erb), as in a strip plot with
the environment as the replication. Each kind of comparison gets its own SE(d) and C.D., the
C.D. from Gomez &amp; Gomez's weighted t.</p>
"

GUIDE_ERRORS <- "
<p>With <i>n</i> observations behind each mean, SE(m) = &radic;(MSE/n),
SE(d) = &radic;(2&middot;MSE/n) and C.D. = t<sub>&alpha;/2, df</sub> &times; SE(d), where
&alpha; is the significance level you chose.</p>
<p>When replication is unequal, mean <i>i</i> has SE(m) = &radic;(MSE/n<sub>i</sub>) and
two means have SE(d) = &radic;(MSE(1/n<sub>i</sub> + 1/n<sub>j</sub>)), so the C.D. depends
on which two means are compared and the tables show its range. In a blocked design with a
missing plot, or a factorial with unequal cells, the means are adjusted (least-squares)
means and their standard errors come from the fitted model. Split plots, strip plots and
pooled analyses must be complete: with a plot missing the app says what is missing rather
than give an approximate answer.</p>
<p>A split plot needs <b>four</b> different SE(d):</p>
<ul>
<li>two main-plot means: &radic;(2&middot;Ea / rb)</li>
<li>two sub-plot means: &radic;(2&middot;Eb / ra)</li>
<li>two sub-plot means within the same main plot: &radic;(2&middot;Eb / r)</li>
<li>two main-plot means at the same sub-plot level: &radic;(2[(b-1)Eb + Ea] / rb), with a weighted <i>t</i></li>
</ul>
<p>A strip plot needs three error terms and the analogous mixed comparisons. The app
prints every one of them under the relevant table of means, so you never have to work
out which C.D. belongs to which comparison.</p>
"

GUIDE_TRANSFORM <- "
<ul>
<li><b>Counts</b> (insects, spores, grains): &radic;y, or &radic;(y+0.5) when zeros occur. Signature: integer data whose variance rises in proportion to the mean, i.e. Taylor slope b &asymp; 1.</li>
<li><b>Percentages and proportions</b>: the angular, or arcsine square-root, transformation. A 0-100 range on its own is <i>not</i> evidence - most yields live there too - so the app also looks at the column name, and you can declare the type yourself.</li>
<li><b>Variance proportional to the square of the mean</b> (b &asymp; 2): log y, or log(y+1) when zeros occur.</li>
<li><b>Variance rising faster still</b> (b &gt; 2.5): 1/y.</li>
<li>Otherwise the Box-Cox profile likelihood chooses &lambda;.</li>
</ul>
<p>Means are always <b>back-transformed</b> for presentation. SE, C.D. and C.V. stay on the
transformed scale, because that is where the tests were performed; tables therefore show
the back-transformed mean with the transformed value in parentheses.</p>
"

GUIDE_POSTHOC <- "
<p>A table of means shows <b>one</b> comparison at a time: the critical difference (C.D.) at the foot of
the table, or the letters of a procedure beside the means, never both, since they are different
procedures and can disagree. With <i>Means only</i> no comparison is made.</p>
<ul>
<li><b>Least significant difference (LSD), Fisher's protected</b>: only after a significant F-test, and best with few treatments.</li>
<li><b>Tukey's honestly significant difference (HSD)</b>: controls the error rate over all pairwise comparisons; the safe default.</li>
<li><b>Duncan's multiple range test (DMRT)</b>: less conservative, still standard in agronomy.</li>
<li><b>Student-Newman-Keuls (SNK) test</b>: sits between Duncan and Tukey.</li>
<li><b>Scheffe's test</b>: the most conservative; built for arbitrary contrasts.</li>
<li><b>Bonferroni-adjusted LSD</b>: simple and strict.</li>
<li><b>Dunnett's test</b>: compares each treatment with a control you choose, two-sided or one-sided (higher, or lower, than the control); the right test when the control is the only comparison of interest.</li>
</ul>
<p>All of them are computed from the error mean square of whichever effect you select, so in a
split or strip plot they automatically use the right error stratum. An interaction in a split
plot, strip plot or pooled analysis is compared within one level of the main-plot (or strip)
factor, or one environment, at a time; an interaction of a pooled factorial gives each pair the
SE(d) of the factors in which the two means differ, with Satterthwaite's degrees of freedom
where a test needs them (Dunnett's test is not offered there, as its exact critical value does
not apply). With unequal replication each pair of means uses its
own SE(d): Tukey's HSD becomes the Tukey-Kramer procedure, and Duncan's and the
Student-Newman-Keuls tests use Kramer's adjustment. As everywhere in the app, no letters are
shown when the effect's F-test is not significant.</p>
"

## ---------------------------------------------------------- app_ui.R ----
###############################################################################
##  UI
###############################################################################

APP_CSS <- "
/* StatLabX on Bootstrap 5. The theme is bslib's precompiled default, so the
   browser compiles no Sass; everything below is plain CSS, much of it set
   through Bootstrap's own variables. The analysis screens stay calm: one
   accent colour, white cards, lines that guide the eye. The gradient belongs
   to the brand and to the About page only. */
:root{
  --slx-ink:#1C2B4A; --slx-navy:#14284B; --slx-muted:#5B6B86; --slx-line:#E2E8F2;
  --slx-blue:#3B7DD8; --slx-blue-dark:#1B4F9C; --slx-violet:#7C4DFF; --slx-bg:#F5F7FB;
  --bs-body-font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;
  --bs-body-font-size:15px; --bs-body-color:#1C2B4A; --bs-body-bg:#F5F7FB;
  --bs-primary:#3B7DD8; --bs-primary-rgb:59,125,216;
  --bs-link-color:#1B4F9C; --bs-link-color-rgb:27,79,156; --bs-link-hover-color:#3B7DD8;
  --bs-border-color:#E2E8F2; --bs-border-radius:10px;
}
body{background:var(--slx-bg);color:var(--slx-ink)}
h1,h2,h3,h4,h5{color:var(--slx-navy);font-weight:650;letter-spacing:-.005em}
h4{font-size:17px;margin-top:14px}

/* ---- navigation: a floating pill ---- */
.navbar.navbar-default{background:rgba(255,255,255,.94);border:1px solid var(--slx-line);border-radius:28px;
  margin:12px 16px 22px;padding:6px 10px 6px 14px;box-shadow:0 8px 28px rgba(20,40,75,.08);
  position:sticky;top:10px;z-index:1030;-webkit-backdrop-filter:saturate(1.4) blur(10px);backdrop-filter:saturate(1.4) blur(10px)}
.navbar.navbar-default .container-fluid{padding:0;flex-wrap:wrap}
.navbar .navbar-brand{display:flex;align-items:center;gap:10px;padding:2px 0;margin-right:16px;
  color:var(--slx-navy);text-decoration:none;white-space:nowrap}
.navbar .navbar-brand{cursor:pointer}
.navbar .navbar-brand img.slx-logo{height:30px;width:auto;display:block}
.slx-sub{display:inline-block;padding-left:12px;border-left:1px solid var(--slx-line);font:500 10px/1.25 ui-monospace,SFMono-Regular,Consolas,Menlo,monospace;
  letter-spacing:.12em;text-transform:uppercase;color:var(--slx-muted)}
@media (max-width:575.98px){.slx-sub{display:none}}
.navbar .navbar-nav{gap:2px;flex-wrap:wrap}
.navbar .nav-link{color:var(--slx-ink) !important;border-radius:999px;padding:7px 13px !important;
  font-weight:500;font-size:14px;border:0 !important}
.navbar .nav-link:hover,.navbar .nav-link:focus{background:#EEF3FB;color:var(--slx-blue-dark) !important}
.navbar .nav-link.active,.navbar .nav-item.show>.nav-link{background:var(--slx-blue);color:#fff !important}
.navbar .dropdown-menu{border-radius:14px;border:1px solid var(--slx-line);box-shadow:0 12px 32px rgba(20,40,75,.12);padding:6px}
.navbar .dropdown-item{border-radius:10px;padding:7px 12px;font-size:14px}
.navbar .dropdown-item.active,.navbar .dropdown-item:active{background:var(--slx-blue);color:#fff}
.navbar .dropdown-header{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--slx-muted);padding:8px 12px 4px}
.navbar .navbar-toggle,.navbar .navbar-toggler{border:1px solid var(--slx-line);border-radius:999px;margin-left:auto}
@media (max-width:767.98px){.navbar.navbar-default{border-radius:22px;position:static}}

/* ---- panels and content ---- */
.tab-content{padding:0 4px 48px}
.well{background:#fff;border:1px solid var(--slx-line);border-radius:16px;box-shadow:0 1px 2px rgba(20,40,75,.04);padding:18px}
.well h4:first-child{margin-top:0}
.control-label{font-weight:600;font-size:13.5px;color:var(--slx-navy)}
.form-control,.selectize-input{border-radius:10px !important;border-color:var(--slx-line) !important;box-shadow:none !important}
.selectize-input.focus,.form-control:focus{border-color:var(--slx-blue) !important;box-shadow:0 0 0 3px rgba(59,125,216,.15) !important}
.btn{border-radius:999px;font-weight:500;padding:7px 16px}
.btn-primary{background:var(--slx-blue);border-color:var(--slx-blue)}
.btn-primary:hover,.btn-primary:focus{background:var(--slx-blue-dark);border-color:var(--slx-blue-dark)}
.btn-default{background:#fff;border:1px solid var(--slx-line);color:var(--slx-ink)}
.btn-default:hover{background:#EEF3FB;border-color:#CDDAEE;color:var(--slx-blue-dark)}
.btn-lg{padding:10px 24px;font-size:16px}
.dataTables_wrapper{background:#fff;border:1px solid var(--slx-line);border-radius:14px;padding:10px 12px;margin:6px 0 12px}
table.dataTable{font-size:13.5px;font-variant-numeric:tabular-nums}
hr{border-color:var(--slx-line);opacity:1}

/* ---- cards that group a step of the work ---- */
.slx-card{background:#fff;border:1px solid var(--slx-line);border-radius:16px;padding:16px 18px;margin:16px 0;
  box-shadow:0 1px 2px rgba(20,40,75,.04)}
.slx-card>h4:first-child,.slx-card-h{margin:0 0 4px;font-size:17px;color:var(--slx-navy);font-weight:650}
.slx-card .slx-lead{font-size:13px;color:var(--slx-muted);margin:0 0 12px}
.slx-step{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;
  background:var(--slx-blue);color:#fff;font-size:12px;font-weight:700;margin-right:8px;vertical-align:2px}
.slx-map-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:4px 14px}
.slx-map-grid .form-group{margin-bottom:8px}
.slx-ctx{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 14px}
.slx-ctx span{background:#fff;border:1px solid var(--slx-line);border-radius:999px;padding:3px 11px;font-size:12.5px;color:var(--slx-ink)}
.slx-ctx span b{color:var(--slx-blue-dark);font-weight:600}
.slx-demo{background:#F3F0FF;border:1px solid #DCD3FF;border-left:4px solid var(--slx-violet);border-radius:12px;
  padding:10px 14px;margin:10px 0;font-size:13.5px}
.slx-resp{margin-top:22px;padding-top:10px;border-top:1px solid var(--slx-line)}
.slx-resp:first-child{border-top:0;padding-top:0;margin-top:6px}
table.slx-settings{width:100%;border-collapse:separate;border-spacing:0 6px}
table.slx-settings th{font-size:12.5px;color:var(--slx-muted);font-weight:600;padding:0 8px}
table.slx-settings td{vertical-align:top;padding:0 8px}
table.slx-settings .form-group{margin-bottom:0}
details.slx-fold{margin:8px 0 14px}
details.slx-fold>summary{cursor:pointer;color:var(--slx-blue-dark);font-weight:600;padding:4px 0}

/* ---- graphs: a small download menu in the corner of each ---- */
.slx-plot{position:relative;margin-bottom:8px}
.slx-plot-dl{position:absolute;top:12px;right:12px;display:flex;gap:5px;opacity:.6;transition:opacity .15s;z-index:6}
.slx-plot:hover .slx-plot-dl,.slx-plot-dl:focus-within{opacity:1}
.slx-dl{border:1px solid var(--slx-line);background:rgba(255,255,255,.95);color:var(--slx-blue-dark);border-radius:999px;
  font-size:11.5px;font-weight:600;padding:3px 9px;line-height:1.4;cursor:pointer}
.slx-dl:hover,.slx-dl:focus{background:var(--slx-blue);border-color:var(--slx-blue);color:#fff;outline:none}

/* ---- charts drawn in the browser (APP_CHART_JS): a card, crisp SVG inside ---- */
.slx-chart{position:relative;background:#fff;border:1px solid var(--slx-line);border-radius:18px;overflow:hidden;
  box-shadow:0 1px 2px rgba(20,40,75,.04),0 18px 40px -28px rgba(20,40,75,.35)}
.slx-chart svg{display:block}
.slx-chart.shiny-output-error{display:flex;align-items:center;justify-content:center;padding:28px;text-align:center;
  color:var(--slx-muted);font-size:13.5px;line-height:1.5}
.slx-chart.recalculating{opacity:.45;transition:opacity .25s}
.slx-tip{position:absolute;left:0;top:0;pointer-events:none;background:rgba(11,21,48,.94);color:#fff;font-size:12px;line-height:1.4;
  padding:7px 11px;border-radius:10px;box-shadow:0 10px 28px rgba(11,21,48,.28);white-space:nowrap;
  transform:translate(-50%,calc(-100% - 12px));opacity:0;transition:opacity .12s;z-index:5}
.slx-tip.on{opacity:1}
.slx-tip b{font-weight:650}
.slx-chart .slx-mark{transition:filter .15s ease}
.slx-chart .slx-mark:hover{filter:brightness(1.07) drop-shadow(0 4px 8px rgba(20,40,75,.22))}
@keyframes slx-grow{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@keyframes slx-pop{from{opacity:0;transform:scale(.3)}to{opacity:1;transform:scale(1)}}
@keyframes slx-fade{from{opacity:0}to{opacity:1}}
@keyframes slx-draw{to{stroke-dashoffset:0}}
@media (prefers-reduced-motion:reduce){.slx-chart *{animation:none !important}}

/* ---- messages: colour carries meaning, not decoration ---- */
.box{background:#fff;border:1px solid var(--slx-line);border-left:4px solid var(--slx-blue);border-radius:12px;padding:12px 16px;margin:12px 0}
.sugbox{background:#EEF8F1;border:1px solid #CBE9D4;border-left:4px solid #2F9E5B;border-radius:12px;padding:10px 14px;margin:10px 0}
.warn{background:#FFF7EA;border:1px solid #F3DEB8;border-left:4px solid #E09A2C;border-radius:12px;padding:10px 14px;margin:10px 0}
.err{background:#FDEEEC;border:1px solid #F3CBC6;border-left:4px solid #C0392B;border-radius:12px;padding:10px 14px;margin:10px 0}
.note{font-size:12.5px;color:var(--slx-muted);margin:4px 0 14px 0;line-height:1.5}
ul.slx-why{font-size:13px;margin:6px 0 10px;padding-left:20px}
.authors{font-size:12.5px;color:var(--slx-muted)}
.appfoot{position:fixed;right:12px;bottom:8px;font-size:10.5px;color:var(--slx-muted);
  background:rgba(255,255,255,.92);padding:3px 10px;border-radius:999px;z-index:1000;border:1px solid var(--slx-line)}

/* ---- tables of the analysis: numbers that line up ---- */
table.doe{border-collapse:collapse;margin:10px 0 6px 0;font-size:13.5px;background:#fff;font-variant-numeric:tabular-nums}
table.doe th,table.doe td{border:1px solid #D6E0EE;padding:6px 11px;text-align:right}
table.doe th{background:#EEF3FA;color:var(--slx-navy);font-weight:600;text-align:center}
table.doe td:first-child,table.doe th:first-child{text-align:left}
table.doe caption{caption-side:top;text-align:left;font-weight:600;padding:6px 0;color:var(--slx-navy)}
table.doe tfoot td{background:#FAFCFF;font-size:12.5px}
table.doe-summary td,table.doe-structure td,table.doe-screen td{text-align:left;vertical-align:top}
table.doe-summary td{font-size:13px}
.slx-scroll{overflow-x:auto;max-width:100%}
td.cdrow{text-align:left !important;background:#FAFCFF;font-size:12.5px}
span.sig{color:#C0392B;font-weight:600}
span.ns{color:#7A889E}
sup{color:var(--slx-blue-dark);font-weight:600}
.slx-kind{display:inline-block;margin-top:3px;padding:1px 8px;border-radius:999px;font-size:11px;font-weight:600;
  background:#EEF3FA;color:var(--slx-blue-dark)}
.slx-kind-designrequirement{background:#FFF4E0;color:#8A5A00}
.slx-kind-visualcheck{background:#EEF8F1;color:#1E7A44}
.slx-kind-declared{background:#F3F0FF;color:#5B3CC4}

/* ---- About: the one landing page ---- */
.slx-hero{text-align:center;padding:44px 16px 36px;margin:0 0 28px;border-radius:24px;
  background:radial-gradient(900px 380px at 20% 0%,#E4EEFD 0%,rgba(228,238,253,0) 65%),
             radial-gradient(800px 360px at 100% 100%,#EFE7FD 0%,rgba(239,231,253,0) 60%),#FBFCFF;
  border:1px solid var(--slx-line)}
.slx-chip{display:inline-flex;align-items:center;gap:7px;padding:5px 12px;border-radius:999px;
  background:#fff;border:1px solid var(--slx-line);font-size:13px;color:var(--slx-ink);font-weight:500}
.slx-dot{width:8px;height:8px;border-radius:50%;background:#2F9E5B;box-shadow:0 0 0 3px rgba(47,158,91,.18)}
.slx-hero-logo{height:64px;width:auto;margin:0 auto 22px;display:block}
.slx-h1{font:400 clamp(40px,7vw,84px)/.95 Anton,Impact,Haettenschweiler,'Arial Narrow Bold',sans-serif;text-transform:uppercase;
  letter-spacing:.005em;margin:20px auto 16px;max-width:880px;color:#0B1530}
.slx-grad{background:linear-gradient(100deg,#0A2477 0%,#1E4FD7 36%,#3B82F6 68%,#7CB7FF 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.slx-lead{font-size:16.5px;color:var(--slx-muted);max-width:720px;margin:0 auto 22px;line-height:1.6}
.slx-chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}
.slx-section{background:#fff;border:1px solid var(--slx-line);border-radius:16px;padding:18px 22px;margin:0 0 16px}
.slx-section h3{font-size:19px;margin-top:0}

/* ---- guides folded into the tabs ---- */
.slx-guide{background:#fff;border:1px solid var(--slx-line);border-radius:12px;padding:0 16px;margin:12px 0}
.slx-guide>summary{cursor:pointer;padding:10px 0;font-weight:600;color:var(--slx-blue-dark)}
.slx-guide[open]>summary{border-bottom:1px solid var(--slx-line);margin-bottom:10px}
.slx-guide>*:last-child{margin-bottom:12px}
.slx-guide table.doe{font-size:13px}
.slx-guide table.doe th,.slx-guide table.doe td{text-align:left}
"

## The scripts of the app's own page: saving a file the server sends, the
## download menu of every graph (drawn and saved in the browser by
## APP_CHART_JS), printing the report from a hidden frame (no file is saved
## first), and, in the browser build, handing the About tab and the logo back
## to the website.
APP_JS <- "
(function () {
  function save(blob, name) {
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    setTimeout(function () { document.body.removeChild(a); URL.revokeObjectURL(url); }, 1500);
  }
  window.slxSave = save;
  Shiny.addCustomMessageHandler('doepro_save', function (m) {
    try { save(new Blob([m.content], {type: m.mime || 'text/html'}), m.filename); }
    catch (e) { alert('Download failed: ' + e.message); }
  });
  Shiny.addCustomMessageHandler('doepro_print', function (m) {
    var old = document.getElementById('slx-print-frame');
    if (old) old.parentNode.removeChild(old);
    var f = document.createElement('iframe');
    f.id = 'slx-print-frame'; f.setAttribute('aria-hidden', 'true'); f.setAttribute('tabindex', '-1');
    f.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;';
    f.onload = function () {
      setTimeout(function () {
        try { f.contentWindow.focus(); f.contentWindow.print(); }
        catch (e) { alert('The print dialog could not be opened here. Download the HTML report and print it from your browser.'); }
      }, 300);
    };
    document.body.appendChild(f);
    f.srcdoc = m.html;
  });
  document.addEventListener('click', function (e) {
    var b = e.target.closest ? e.target.closest('.slx-dl') : null;
    if (!b) return;
    if (window.SLXChart) window.SLXChart.download(b.getAttribute('data-plot'), b.getAttribute('data-fmt'));
  });
  document.addEventListener('click', function (e) {
    var a = e.target.closest ? e.target.closest('.navbar a[data-value=about], .navbar .navbar-brand') : null;
    if (!a) return;
    var shell = null;
    try { shell = window.parent !== window ? window.parent.StatLabX : null; } catch (err) { shell = null; }
    if (shell && shell.home) { e.preventDefault(); e.stopPropagation(); shell.home(); }
  }, true);
})();
"

## The choices for the transformation menus. This is a function, not a stored
## object: R sources the files of a package in alphabetical order, so TRANS (in
## assumptions.R) does not yet exist while this file is being loaded.
trans_choices <- function()
  stats::setNames(names(TRANS), vapply(TRANS, `[[`, character(1), "lab"))

## The brand at the left of the navigation bar: the StatLabX wordmark and
## the package that powers it
nav_brand <- function()
  tagList(tags$img(src = LOGO_URI, alt = "StatLabX", class = "slx-logo"),
          tags$span(class = "slx-sub", sprintf("powered by %s %s", APP_NAME, APP_VERSION)))

## the line of chips at the top of an analysis tab: what is being analysed
ctx_strip <- function(id) uiOutput(id)

## a step of the work on the Data tab, as a card
step_card <- function(n, title, lead, ...)
  div(class = "slx-card",
      div(class = "slx-card-h", span(class = "slx-step", n), title),
      if (!is.null(lead)) p(class = "slx-lead", lead),
      ...)

#' The DOEpro user interface
#'
#' Builds the Shiny UI object. Called by \code{\link{run_DOEpro}}; you should not
#' normally need to call it yourself.
#'
#' @return A Shiny UI definition.
#' @keywords internal
doepro_ui <- function() navbarPage(
  title = nav_brand(), windowTitle = "StatLabX",
  ## bslib's precompiled Bootstrap 5: a theme with changed variables would be
  ## compiled from Sass in the browser on every visit (5 s natively), so the
  ## look is set in APP_CSS instead
  theme = bslib::bs_theme(version = 5),
  id = "nav", collapsible = TRUE,
  header = tagList(tags$head(tags$style(HTML(paste0(APP_CSS, MEANS_CSS))),
                             tags$script(HTML(APP_JS)), tags$script(HTML(APP_CHART_JS))),
                   tags$div(class = "appfoot", CREDIT_SHORT)),

  ## ----------------------------------------------------------------- about --
  ## first, so that the app opens on it; in the browser build the website
  ## (site/) takes its place, and choosing it there brings the website back
  tabPanel("About", value = "about", htmlOutput("about")),

  ## ------------------------------------------------------------------ data --
  tabPanel("1. Data", value = "data",
    sidebarLayout(
      sidebarPanel(width = 4,
        h4("Paste from Excel"),
        radioButtons("sep", "Column separator", inline = TRUE,
                     c("Tab" = "\t", "Comma" = ",", "Semicolon" = ";", "Space" = " ")),
        checkboxInput("header", "First row contains column names", TRUE),
        textAreaInput("paste", NULL, rows = 10, width = "100%",
          placeholder = "Block  Variety  Yield  Incidence_percent\nB1  V1  42.3  18.5\nB1  V2  47.1  12.0  ..."),
        actionButton("load", "Load pasted data", class = "btn-primary"),
        tags$hr(),
        h4("or upload a CSV"),
        fileInput("file", NULL, accept = c(".csv", ".txt")),
        tags$hr(),
        h4("or try an example"),
        selectInput("demo", NULL, DEMO_CHOICES),
        actionButton("loaddemo", "Load example"),
        div(class = "note", style = "margin-top:8px",
            "The examples are demonstration data, built for illustration; they are not from real experiments.")),
      mainPanel(width = 8,
        uiOutput("dataNote"),
        tab_guide("How to start", GUIDE_START),
        uiOutput("dqOut"),
        h4("Data (click a cell to edit)"),
        DTOutput("tbl"),
        step_card("2", "Design and variables",
          "Choose the design, the response variable(s) and the column that plays each role. Everything below and on the next tabs updates as you choose.",
          fluidRow(
            column(7, selectInput("design", "Experimental design", DESIGNS, selected = "RCBD", width = "100%")),
            column(5, selectInput("alpha", "Significance level", c("0.05 (5%)" = "0.05", "0.01 (1%)" = "0.01"),
                                  selected = "0.05", width = "100%"))),
          conditionalPanel("input.design == 'FCRD' || input.design == 'FRCBD' || input.design == 'POOLFRCBD' || input.design == 'POOLFCRD'",
            sliderInput("nfac", "Number of treatment factors", 2, 4, 2, step = 1)),
          uiOutput("mapUI"),
          uiOutput("mapNote"),
          tab_guide("The designs and their error terms", GUIDE_DESIGNS),
          conditionalPanel("['POOLRCBD', 'POOLCRD', 'POOLFRCBD', 'POOLFCRD'].indexOf(input.design) >= 0",
            tab_guide("Pooled (combined) analysis over environments", GUIDE_POOLED))),
        step_card("3", "Quick descriptive statistics",
          "A first look at each response chosen above, before any analysis.",
          uiOutput("quickOut"),
          actionButton("dl_quick", "Summary (CSV)", icon = icon("download"), class = "btn-default btn-sm")),
        step_card("4", "Automatic screening",
          "A preliminary check of each response chosen above, from the model for the design and before any transformation. The full checks, with their plots, are on the Assumptions & Diagnostics tab.",
          uiOutput("screenOut")))
    )),

  ## ------------------------------------------------- exploration and diagnostics --
  ## analyses that describe and explore the data without a design, straight
  ## after the data and before the analysis of variance
  navbarMenu("2. Exploration & Diagnostics", menuName = "explore",
    "Exploratory visualisations",
    tabPanel("Distributions and descriptive graphs", value = "explore_dist",
      sidebarLayout(
        sidebarPanel(width = 3,
          div(class = "note", paste(
            "Plots of how each numeric column's values are spread, with a fuller summary that can be split by a",
            "grouping column. Entries that are not plain numbers (such as 5,6 or 12a) count as missing here",
            "until they are corrected on the Data tab.")),
          uiOutput("descUI"),
          actionButton("dl_desc", "Table (CSV)", icon = icon("download"))),
        mainPanel(width = 9,
          h4(textOutput("descPlotTitle", inline = TRUE)),
          fluidRow(
            column(6, chart_output("descHist"), uiOutput("descHistText")),
            column(6, chart_output("descDens"), uiOutput("descDensText"))),
          fluidRow(
            column(6, chart_output("descBox"), uiOutput("descBoxText")),
            column(6, chart_output("descQQ"), uiOutput("descQQText"))),
          tags$hr(),
          uiOutput("descTab"),
          uiOutput("descText"))
      )),
    "----",
    "Data structure & quality",
    tabPanel("Data structure and quality", value = "explore_structure",
      uiOutput("structOut")),
    "----",
    "Additional exploratory analysis",
    tabPanel("Correlation", value = "explore_cor",
      sidebarLayout(
        sidebarPanel(width = 3,
          div(class = "note", paste(
            "How each pair of numeric columns varies together. Each pair uses every row with both values;",
            "entries that are not plain numbers count as missing until they are corrected on the Data tab.")),
          uiOutput("corUI"),
          radioButtons("corMethod", "Coefficient",
            c("Pearson's r (straight-line association)" = "pearson",
              "Spearman's rho (ranks)" = "spearman",
              "Kendall's tau (ranks, pairs of rows)" = "kendall")),
          selectInput("corAlpha", "Significance level", c(0.05, 0.01), selected = 0.05),
          uiOutput("corPairUI"),
          actionButton("dl_cor", "Pairs (CSV)", icon = icon("download"))),
        mainPanel(width = 9,
          uiOutput("corMatrix"),
          uiOutput("corText"),
          uiOutput("corPairs"),
          tags$hr(),
          fluidRow(
            column(7, chart_output("corHeat", "420px"), uiOutput("corHeatText")),
            column(5, chart_output("corScatter", "420px"), uiOutput("corScatterText"))))
      )),
    tabPanel("Regression", value = "explore_reg",
      sidebarLayout(
        sidebarPanel(width = 3,
          div(class = "note", paste(
            "A straight-line equation for predicting one numeric column from one or more others, fitted by least",
            "squares. Only rows with every value are used; entries that are not plain numbers count as missing",
            "until they are corrected on the Data tab.")),
          uiOutput("regUI"),
          selectInput("regAlpha", "Significance level", c(0.05, 0.01), selected = 0.05),
          uiOutput("regShowUI"),
          actionButton("dl_reg", "Coefficients (CSV)", icon = icon("download"))),
        mainPanel(width = 9,
          uiOutput("regEquation"),
          uiOutput("regCoef"),
          uiOutput("regModel"),
          uiOutput("regText"),
          uiOutput("regAnova"),
          tags$hr(),
          fluidRow(
            column(7, chart_output("regMain", "440px")),
            column(5, uiOutput("regMainText"))),
          tags$hr(),
          h4("Checking the fit"),
          uiOutput("regChecks"),
          fluidRow(
            column(4, chart_output("regResid", "340px"), uiOutput("regResidText")),
            column(4, chart_output("regQQ", "340px"), uiOutput("regQQText")),
            column(4, chart_output("regObs", "340px"), uiOutput("regObsText"))))
      )),
    tabPanel("Principal components", value = "explore_pca",
      sidebarLayout(
        sidebarPanel(width = 3,
          div(class = "note", paste(
            "Principal component analysis: a few new variables, the components, that carry as much as possible of",
            "how the chosen columns vary together. Only rows with every value are used; entries that are not plain",
            "numbers count as missing until they are corrected on the Data tab.")),
          uiOutput("pcaUI"),
          radioButtons("pcaScale", "Analyse",
            c("Correlations: each variable standardised (when units differ)" = "cor",
              "Covariances: variables as measured (same units only)" = "cov")),
          uiOutput("pcaAxesUI"),
          uiOutput("pcaGroupUI"),
          actionButton("dl_pca_load", "Loadings (CSV)", icon = icon("download")),
          actionButton("dl_pca_scores", "Scores (CSV)", icon = icon("download"))),
        mainPanel(width = 9,
          uiOutput("pcaEigen"),
          uiOutput("pcaText"),
          uiOutput("pcaLoadings"),
          tags$hr(),
          fluidRow(
            column(6, chart_output("pcaScree", "380px"), uiOutput("pcaScreeText")),
            column(6, chart_output("pcaScores", "380px"), uiOutput("pcaScoresText"))),
          fluidRow(
            column(6, chart_output("pcaLoadPlot", "420px"), uiOutput("pcaLoadText")),
            column(6, chart_output("pcaBiplot", "420px"), uiOutput("pcaBiplotText"))),
          uiOutput("pcaScoreTable"))
      )),
    tabPanel("Cluster analysis", value = "explore_cl",
      sidebarLayout(
        sidebarPanel(width = 3,
          div(class = "note", paste(
            "Hierarchical clustering: rows, or the means of each level of a grouping column (varieties by their",
            "trait means), joined step by step into a tree and cut into clusters of items alike in the chosen columns.",
            "Only rows with every value are used.")),
          uiOutput("clUI"),
          uiOutput("clGroupUI"),
          checkboxInput("clScale", "Standardise each variable (when units differ)", TRUE),
          selectInput("clLink", "Linkage", c("Ward's method" = "ward", "Complete linkage" = "complete",
                                             "Average linkage (UPGMA)" = "average", "Single linkage" = "single")),
          conditionalPanel("input.clLink != 'ward'",
            selectInput("clDist", "Distance", c("Euclidean" = "euclidean", "Manhattan" = "manhattan"))),
          conditionalPanel("input.clLink == 'ward'",
            div(class = "note", "Ward's method works on Euclidean distances.")),
          uiOutput("clKUI"),
          actionButton("dl_cl", "Clusters (CSV)", icon = icon("download"))),
        mainPanel(width = 9,
          uiOutput("clText"),
          uiOutput("clMembers"),
          uiOutput("clMeans"),
          tags$hr(),
          fluidRow(
            column(7, chart_output("clDendro", "440px")),
            column(5, uiOutput("clDendroText"))),
          fluidRow(
            column(6, chart_output("clPcs", "400px"), uiOutput("clPcsText")),
            column(6, chart_output("clSil", "400px"), uiOutput("clSilText"))),
          uiOutput("clItems"))
      )),
    tabPanel("Factor analysis", value = "explore_fa",
      sidebarLayout(
        sidebarPanel(width = 3,
          div(class = "note", paste(
            "Factor analysis (maximum likelihood): a few underlying factors that account for the correlations between",
            "the chosen columns. Only rows with every value are used; entries that are not plain numbers count as",
            "missing until they are corrected on the Data tab.")),
          uiOutput("faUI"),
          uiOutput("faKUI"),
          selectInput("faRot", "Rotation", c("Varimax (factors uncorrelated)" = "varimax",
                                             "Promax (factors may correlate)" = "promax", "None" = "none")),
          selectInput("faAlpha", "Significance level", c(0.05, 0.01), selected = 0.05),
          uiOutput("faAxesUI"),
          actionButton("dl_fa_load", "Loadings (CSV)", icon = icon("download")),
          actionButton("dl_fa_scores", "Scores (CSV)", icon = icon("download"))),
        mainPanel(width = 9,
          uiOutput("faText"),
          uiOutput("faAdequacy"),
          uiOutput("faLoadings"),
          uiOutput("faVariance"),
          uiOutput("faPhi"),
          tags$hr(),
          fluidRow(
            column(6, chart_output("faScree", "380px"), uiOutput("faScreeText")),
            column(6, chart_output("faHeat", "380px"), uiOutput("faHeatText"))),
          fluidRow(
            column(6, chart_output("faLoadPlot", "420px"), uiOutput("faLoadText")),
            column(6, uiOutput("faScores"))))
      ))),

  ## ----------------------------------------------------------- assumptions --
  ## before the analysis of variance: the checks decide the scale it is on
  tabPanel("3. Assumptions & Diagnostics", value = "assumptions",
    ctx_strip("ctxAssum"),
    div(class = "slx-card",
      div(class = "slx-card-h", "The scale of each response"),
      p(class = "slx-lead", paste(
        "Say what kind of measurement each response is, and choose the scale it is analysed on. The ANOVA, the means",
        "and the plots all use the scale chosen here; the values as entered are used until you choose otherwise.")),
      uiOutput("transUI"),
      actionButton("applysug", "Apply every suggested transformation", class = "btn-default btn-sm")),
    fluidRow(column(4, uiOutput("aRespUI"))),
    uiOutput("asmSummary"),
    uiOutput("asmText"),
    uiOutput("sugbox"),
    tags$details(class = "slx-fold", tags$summary("The tests in detail"), uiOutput("assumtxt")),
    tab_guide("Choosing a transformation", GUIDE_TRANSFORM),
    h4("Residual diagnostics"),
    div(class = "note", "Residuals are the observed values minus those the analysis fits; the plots show whether they behave as the F-tests assume."),
    fluidRow(column(6, chart_output("diagFit", "300px"), uiOutput("diagFitText")),
             column(6, chart_output("diagQQ", "300px"), uiOutput("diagQQText"))),
    fluidRow(column(6, chart_output("diagHist", "300px"), uiOutput("diagHistText")),
             column(6, chart_output("diagScale", "300px"), uiOutput("diagScaleText"))),
    fluidRow(column(6, chart_output("diagCook", "300px"), uiOutput("diagCookText"))),
    h4("Choosing a transformation"),
    fluidRow(column(6, chart_output("bcPlot", "300px"), uiOutput("bcText")),
             column(6, chart_output("mvPlot", "300px"), uiOutput("mvText")))),

  ## ------------------------------------------------------------------ anova --
  tabPanel("4. ANOVA", value = "anova",
    ctx_strip("ctxAnova"),
    fluidRow(column(12, actionButton("dl_anova", "ANOVA tables (CSV)", icon = icon("download"), class = "btn-default btn-sm"))),
    uiOutput("runNote"),
    uiOutput("anovaOut")),

  ## ---------------------------------------------------- means and comparisons --
  tabPanel("5. Means & Comparisons", value = "means",
    ctx_strip("ctxMeans"),
    sidebarLayout(
      sidebarPanel(width = 3,
        uiOutput("cmpRespUI"),
        selectInput("phMethod", "Compare the means by", CMP_CHOICES, selected = "none"),
        ## a control means something only to Dunnett's test
        conditionalPanel("input.phMethod == 'Dunnett'",
          uiOutput("phControlUI"),
          radioButtons("phAlt", "Compare each treatment with the control",
            c("Does it differ? (two-sided)" = "two.sided", "Is it higher? (one-sided)" = "greater",
              "Is it lower? (one-sided)" = "less"))),
        uiOutput("phEffectUI"),
        uiOutput("phByUI"),
        numericInput("digits", "Decimal places", 2, 0, 5, 1),
        checkboxInput("detailed", "Show detailed tables (every effect)", FALSE),
        actionButton("dl_means", "Means (CSV)", icon = icon("download"), class = "btn-default btn-sm"),
        tags$br(), tags$br(),
        actionButton("dl_ph", "Comparisons (CSV)", icon = icon("download"), class = "btn-default btn-sm"),
        tags$br(), tags$br(),
        actionButton("dl_ph_pairs", "Every pair (CSV)", icon = icon("download"), class = "btn-default btn-sm")),
      mainPanel(width = 9,
        uiOutput("meansOut"),
        uiOutput("phOut"),
        tab_guide("How SE(m), SE(d) and the C.D. are worked out", GUIDE_ERRORS),
        tab_guide("Which comparison to choose", GUIDE_POSTHOC))
    )),

  ## ----------------------------------------------------------------- plots --
  tabPanel("6. Plots", value = "plots",
    ctx_strip("ctxPlots"),
    tabsetPanel(id = "plotTabs", type = "pills",
      tabPanel("Means", value = "plot_means",
        sidebarLayout(
          sidebarPanel(width = 3,
            uiOutput("aRespUI3"), uiOutput("plEffectUI"), uiOutput("plXUI"),
            radioButtons("plType", "Plot type",
              c("Bar chart" = "bar", "Points with error bars" = "line",
                "Heat map" = "heat", "Box plot" = "box")),
            uiOutput("plLettersUI")),
          mainPanel(width = 9, chart_output("mainPlot", "540px"), uiOutput("mainPlotText")))),
      tabPanel("Interaction plots", value = "plot_inter",
        sidebarLayout(
          sidebarPanel(width = 3,
            uiOutput("ipRespUI"), uiOutput("ipEffectUI"), uiOutput("ipXUI"),
            checkboxInput("ipCI", "Show confidence intervals of the means (where they can be given)", TRUE)),
          mainPanel(width = 9, chart_output("interPlot", "540px"), uiOutput("interPlotText")))))),

  ## -------------------------------------------------------------- interpret --
  tabPanel("7. Interpretation & Report", value = "report",
    ctx_strip("ctxReport"),
    div(class = "slx-card",
      div(class = "slx-card-h", "The report"),
      p(class = "slx-lead", paste(
        "The full analysis as one document: the ANOVA, the means with the comparison chosen on the Means &",
        "Comparisons tab, the checks and the interpretation, with the StatLabX credit and the date.")),
      actionButton("print_report", "Print / Save as PDF", icon = icon("print"), class = "btn-primary"),
      actionButton("dl_html", "Download HTML", icon = icon("download"), class = "btn-default"),
      uiOutput("pdfBtn", inline = TRUE),
      div(class = "note", style = "margin-top:10px", paste(
        "Print / Save as PDF opens your browser's print dialog: choose 'Save as PDF' as the printer to keep a PDF.",
        "Tables are kept whole and wide tables print on a landscape page where your browser allows."))),
    uiOutput("interpOut"))
)

